// scripts/place-book/descriptions.py가 descriptions.json으로 만든 파일입니다. 손으로 고치지 않습니다.

enum MapHomePlaceBookDescriptions {
    struct Item {
        let id: String
        let ko: String
        let english: String
    }

    static let items: [Item] = [
        .init(id: "kr.gyeongbokgung", ko: "서울 종로구에 있는 조선 시대의 법궁이다. 근정전과 경회루 등 전각이 남아 있고 수문장 교대식을 볼 수 있다.", english: "The main royal palace of the Joseon dynasty, located in Jongno-gu, Seoul. Visitors see Geunjeongjeon Hall, Gyeonghoeru Pavilion and the royal guard changing ceremony."),
        .init(id: "kr.namsan", ko: "남산 정상에 선 전파 송신탑 겸 전망 시설이다. 서울 도심과 한강을 한눈에 내려다볼 수 있고 사랑의 자물쇠로도 알려져 있다.", english: "A communication and observation tower on top of Namsan Mountain. It offers wide views over central Seoul and the Han River, and is known for its love lock fences."),
        .init(id: "kr.changdeokgung", ko: "조선 시대 이궁으로 지은 궁궐로 유네스코 세계유산이다. 자연 지형을 살린 배치와 후원이 특징이다.", english: "A Joseon-era royal palace listed as a UNESCO World Heritage Site. It is known for buildings that follow the natural terrain and for its secret garden."),
        .init(id: "kr.changgyeonggung", ko: "창덕궁 옆에 있는 조선 시대 궁궐이다. 명정전과 넓은 정원, 온실이 있어 조용히 거닐기 좋다.", english: "A Joseon-era palace next to Changdeokgung. It has Myeongjeongjeon Hall, spacious gardens and a greenhouse, making it a calm place for a walk."),
        .init(id: "kr.deoksugung", ko: "서울시청 앞에 있는 궁궐로 대한제국 시기에 황실이 머물렀다. 전통 건물과 서양식 석조전이 함께 있다.", english: "A palace facing Seoul City Hall that served the Korean Empire as an imperial residence. Traditional halls stand beside a Western-style stone building."),
        .init(id: "kr.gyeonghuigung", ko: "조선 시대에 지은 궁궐로 서울 서쪽에 있어 서궐이라 불렀다. 지금은 일부 전각이 복원되어 있고 무료로 둘러볼 수 있다.", english: "A Joseon-era palace once called the Western Palace for its location in western Seoul. Several halls have been restored and the grounds are easy to explore."),
        .init(id: "kr.jongmyo", ko: "조선 왕과 왕비의 신주를 모신 사당으로 유네스코 세계유산이다. 긴 정전 건물과 종묘제례가 대표적인 볼거리다.", english: "A shrine housing the spirit tablets of Joseon kings and queens, listed as a UNESCO World Heritage Site. Its very long main hall and the royal ancestral rites are highlights."),
        .init(id: "kr.sajikdan", ko: "조선 시대에 토지신과 곡식신에게 제사를 지내던 제단이다. 경복궁 서쪽 종로구에 있으며 도성의 중요한 제례 공간이었다.", english: "An altar where Joseon rulers held rites for the gods of land and grain. It lies west of Gyeongbokgung in Jongno-gu and was an important ritual site of the capital."),
        .init(id: "kr.sungnyemun", ko: "한양도성의 남쪽 정문으로 흔히 남대문이라 부른다. 서울에 남은 목조 성문 가운데 오래된 국보로 꼽힌다.", english: "The southern main gate of the old Seoul city wall, commonly called Namdaemun. It is a designated National Treasure and one of the city’s oldest wooden gates."),
        .init(id: "kr.heunginjimun", ko: "한양도성의 동쪽 문으로 흔히 동대문이라 부른다. 성문 바깥에 반달 모양 옹성이 있는 것이 특징이다.", english: "The eastern gate of the old Seoul city wall, commonly called Dongdaemun. It is distinguished by a semicircular outer wall protecting the gate."),
        .init(id: "kr.bukchon", ko: "경복궁과 창덕궁 사이에 한옥이 모여 있는 마을이다. 골목길을 따라 전통 가옥과 서울 도심 풍경을 함께 볼 수 있다.", english: "A neighborhood of traditional houses between Gyeongbokgung and Changdeokgung. Its alleys offer views of hanok roofs with the city beyond."),
        .init(id: "kr.insadong", ko: "서울 종로에 있는 전통 문화의 거리다. 화랑과 공예품점, 찻집이 늘어서 있어 천천히 걸으며 구경하기 좋다.", english: "A traditional culture street in Jongno, Seoul. Galleries, craft shops and tea houses line the road, which suits a slow stroll."),
        .init(id: "kr.gwanghwamun_square", ko: "광화문 앞에 이어진 넓은 광장이다. 세종대왕상과 이순신 장군상이 서 있고 집회와 행사가 자주 열린다.", english: "A broad public square in front of Gwanghwamun Gate. Statues of King Sejong and Admiral Yi Sun-sin stand here, and events are often held."),
        .init(id: "kr.cheonggyecheon", ko: "서울 도심을 가로지르는 하천을 복원해 만든 산책로다. 광화문 근처에서 동쪽으로 길게 이어지며 다리 아래를 걸을 수 있다.", english: "A restored stream running through downtown Seoul. The walking path stretches east from near Gwanghwamun and passes under many bridges."),
        .init(id: "kr.cheongwadae", ko: "대통령 집무 공간으로 쓰이다 시민에게 개방된 곳이다. 본관과 영빈관, 뒤편 산책로를 둘러볼 수 있다.", english: "The former presidential office and residence, now open to the public. Visitors can see the main building, the state guesthouse and the walking paths behind."),
        .init(id: "kr.myeongdong_cathedral", ko: "서울 명동에 있는 고딕 양식의 천주교 성당이다. 붉은 벽돌 외관이 특징이며 한국 천주교의 중심 성당으로 알려져 있다.", english: "A Gothic-style Catholic cathedral in Myeongdong, Seoul. Its red brick exterior stands out, and it is a central church for Korean Catholics."),
        .init(id: "kr.seoul_station", ko: "옛 서울역사를 복원해 전시와 공연 공간으로 쓰는 곳이다. 1925년에 지어진 르네상스풍 건물로 서울 역 앞에 있다.", english: "The restored old Seoul Station building, now used for exhibitions and performances. It is a Renaissance-style structure standing next to the current station."),
        .init(id: "kr.seodaemun_prison", ko: "일제강점기에 독립운동가들이 투옥된 형무소 터에 세운 역사관이다. 옥사와 전시관을 통해 당시 역사를 살펴볼 수 있다.", english: "A history museum on the site of a prison where independence activists were jailed during Japanese rule. Cell buildings and exhibits explain that period."),
        .init(id: "kr.ddp", ko: "서울 동대문에 있는 전시·디자인 복합 문화 공간이다. 곡선형 외관이 눈에 띄며 밤에는 조명이 켜진 정원도 볼 수 있다.", english: "A design and exhibition complex in Dongdaemun, Seoul. Its curved metallic exterior is distinctive, and the grounds are lit up at night."),
        .init(id: "kr.gwangjang_market", ko: "종로에 있는 전통시장으로 먹거리로 널리 알려져 있다. 빈대떡, 마약김밥, 육회 같은 음식과 포목점이 모여 있다.", english: "A traditional market in Jongno known for its street food. Stalls sell items such as mung bean pancakes and beef tartare, alongside fabric shops."),
        .init(id: "kr.namdaemun_market", ko: "숭례문 가까이에 있는 서울의 오래된 전통시장이다. 의류와 잡화, 먹거리를 파는 가게가 좁은 골목에 이어져 있다.", english: "One of Seoul’s old traditional markets, near Sungnyemun Gate. Clothing, goods and food shops fill its narrow lanes."),
        .init(id: "kr.national_museum", ko: "서울 용산에 있는 국가 대표 박물관이다. 선사 시대부터 근현대까지의 유물을 전시하며 넓은 정원과 호수도 있다.", english: "Korea’s national museum in Yongsan, Seoul. Its collections range from prehistory to modern times, and the grounds include gardens and a pond."),
        .init(id: "kr.war_memorial", ko: "용산에 있는 전쟁 관련 기념관이다. 한국 전쟁을 포함한 전쟁사 자료를 전시하고 야외에는 군용 장비가 놓여 있다.", english: "A war museum in Yongsan covering Korean military history, including the Korean War. Military vehicles and aircraft are displayed outdoors."),
        .init(id: "kr.mmca_seoul", ko: "종로 삼청동 인근에 있는 국립 현대미술관 분관이다. 옛 건물을 활용한 공간에서 현대 미술 전시가 열린다.", english: "A branch of the national modern and contemporary art museum near Samcheong-dong in Jongno. Exhibitions are held in a space that incorporates older buildings."),
        .init(id: "kr.leeum", ko: "서울 용산구 한남동에 있는 사립 미술관이다. 전통 미술과 현대 미술을 함께 소장하고 유명 건축가들이 지은 건물로 알려져 있다.", english: "A private art museum in Hannam-dong, Yongsan-gu. It holds both traditional and contemporary art in buildings designed by well-known architects."),
        .init(id: "kr.lotte_tower", ko: "서울 송파구 잠실에 있는 초고층 복합 건물이다. 높은 층의 전망대에서 서울 시내를 내려다볼 수 있다.", english: "A supertall mixed-use skyscraper in Jamsil, Songpa-gu. Its upper-level observation deck looks out over Seoul."),
        .init(id: "kr.lotte_world", ko: "잠실에 있는 도심형 테마파크다. 실내 놀이공원과 야외 매직 아일랜드가 이어져 있고 민속박물관도 함께 있다.", english: "An urban theme park in Jamsil. An indoor amusement area connects with the outdoor Magic Island, and a folk museum is also on site."),
        .init(id: "kr.seokchon_lake", ko: "송파구 잠실에 있는 인공 호수로 동호와 서호로 나뉜다. 호숫가 산책로와 벚꽃 풍경으로 사랑받는다.", english: "An artificial lake in Songpa-gu split into east and west parts. Its lakeside paths are popular, especially in cherry blossom season."),
        .init(id: "kr.olympic_park", ko: "1988년 서울 올림픽을 기념해 조성한 공원이다. 체육 경기장과 조각 작품, 잔디밭이 있어 산책과 휴식에 좋다.", english: "A park built for the 1988 Seoul Olympics. Sports venues, sculptures and wide lawns make it good for walks and rest."),
        .init(id: "kr.pungnaptoseong", ko: "한강 변 송파구에 남은 백제 시대 토성 유적이다. 하남 위례성으로 보는 견해가 있는 곳으로 일부 성벽이 보존되어 있다.", english: "The remains of an earthen fortress from the Baekje period on the Han River in Songpa-gu. Some walls survive, and it is considered a candidate site for an early Baekje capital."),
        .init(id: "kr.coex", ko: "서울 강남구 삼성동에 있는 대형 전시·컨벤션 복합 시설이다. 쇼핑몰과 수족관, 별마당 도서관이 함께 있다.", english: "A large convention and shopping complex in Samseong-dong, Gangnam-gu. It includes an aquarium and the open Starfield Library."),
        .init(id: "kr.bongeunsa", ko: "강남 도심 한가운데 있는 불교 사찰이다. 신라 시대에 창건된 것으로 전하며 큰 미륵불상과 판전이 알려져 있다.", english: "A Buddhist temple in the middle of Gangnam. Tradition dates its founding to the Silla period, and it is known for a large Maitreya statue and a scripture hall."),
        .init(id: "kr.seonjeongneung", ko: "조선 시대 왕과 왕비의 무덤 선릉과 정릉이 있는 곳이다. 빌딩 숲 속에서 솔숲 산책로를 걸을 수 있는 유네스코 세계유산이다.", english: "The site of Joseon royal tombs, Seolleung and Jeongneung, now a UNESCO World Heritage Site. Pine-lined paths offer a quiet walk amid Gangnam’s office towers."),
        .init(id: "kr.seoul_forest", ko: "성동구 성수동 옆에 있는 대형 도시 숲이다. 넓은 잔디밭과 연못, 사슴 방사장이 있고 한강과도 가깝다.", english: "A large urban park beside Seongsu-dong in Seongdong-gu. It has wide lawns, ponds and a deer enclosure, and lies close to the Han River."),
        .init(id: "kr.ttukseom", ko: "광진구 한강 변에 있는 공원이다. 자전거길과 잔디밭, 수영장 같은 시설이 있어 휴식과 운동에 많이 찾는다.", english: "A riverside park along the Han River in Gwangjin-gu. Bike paths, lawns and a pool make it popular for relaxing and exercise."),
        .init(id: "kr.yeouido_park", ko: "한강 변 여의도에 있는 공원이다. 넓은 잔디밭과 산책로가 있고 봄에는 벚꽃, 가을에는 불꽃 축제로 알려져 있다.", english: "A riverside park on Yeouido along the Han River. It has broad lawns and walking paths, and is known for spring cherry blossoms and fireworks events."),
        .init(id: "kr.yeouido_63", ko: "서울 여의도에 있는 금빛 외관의 고층 건물이다. 1985년에 완공되었으며 전망대와 수족관, 전시 시설이 있다.", english: "A golden high-rise building on Yeouido, Seoul, completed in 1985. It houses an observation deck, an aquarium and exhibition spaces."),
        .init(id: "kr.national_assembly", ko: "서울 여의도에 있는 대한민국 입법부 건물이다. 둥근 돔 지붕이 특징이며 일부 구역은 참관할 수 있다.", english: "The legislative building of South Korea on Yeouido, Seoul. It is recognized by its round dome roof, and parts of it are open for visits."),
        .init(id: "kr.seonyudo", ko: "한강 가운데 작은 섬에 있는 공원이다. 옛 정수장 시설을 활용해 만들었으며 연못과 식물, 철제 구조물이 어우러진다.", english: "A park on a small island in the Han River. It reuses an old water treatment plant, blending ponds, plants and industrial structures."),
        .init(id: "kr.banpo_bridge", ko: "한강을 가로지르는 다리로 위에 잠수교가 함께 있는 이층 구조다. 밤에는 달빛무지개분수가 물줄기를 뿜는다.", english: "A Han River bridge with the low Jamsu Bridge running beneath it. At night its Moonlight Rainbow Fountain sprays water from the deck."),
        .init(id: "kr.sebitseom", ko: "반포대교 옆 한강에 떠 있는 인공 섬 형태의 복합 문화 공간이다. 밤에는 조명이 켜지고 카페와 전시 공간이 있다.", english: "A set of floating artificial islands on the Han River beside Banpo Bridge. They hold cafes and event spaces and are lit up at night."),
        .init(id: "kr.seoul_arts_center", ko: "서초구에 있는 종합 문화 예술 공간이다. 오페라와 클래식 공연장, 미술관, 서예박물관이 모여 있다.", english: "A cultural complex in Seocho-gu with opera and concert halls, an art museum and a calligraphy museum."),
        .init(id: "kr.world_cup_stadium", ko: "마포구 상암동에 있는 축구 경기장이다. 2002년 월드컵 개막 경기를 치렀고 지금도 축구 경기와 공연이 열린다.", english: "A football stadium in Sangam-dong, Mapo-gu. It hosted matches of the 2002 World Cup and still holds games and concerts."),
        .init(id: "kr.haneul_park", ko: "마포구 상암동의 월드컵공원에 있는 언덕 공원이다. 옛 쓰레기 매립지를 되살린 곳으로 가을 억새밭이 유명하다.", english: "A hilltop park in World Cup Park, Sangam-dong, Mapo-gu. Built on a former landfill, it is known for its silver grass fields in autumn."),
        .init(id: "kr.hongdae", ko: "홍익대학교 앞 마포구의 번화가다. 거리 공연과 카페, 클럽, 작은 가게가 모여 젊은 분위기가 강하다.", english: "A lively district near Hongik University in Mapo-gu. Street performances, cafes, clubs and small shops give it a youthful feel."),
        .init(id: "kr.itaewon", ko: "서울 용산구의 외국 음식점과 상점이 많은 거리다. 다양한 나라의 문화가 섞여 있어 이국적인 분위기를 느낄 수 있다.", english: "A Yongsan-gu district with many international restaurants and shops. The mix of cultures gives it a cosmopolitan atmosphere."),
        .init(id: "kr.seongsu", ko: "성동구에 있는 옛 공장 지대로 지금은 카페와 공방, 편집 매장이 모인 곳이다. 오래된 건물을 고쳐 쓴 공간이 많다.", english: "A former factory area in Seongdong-gu, now filled with cafes, workshops and select shops. Many occupy renovated old buildings."),
        .init(id: "kr.ikseondong", ko: "종로 3가 근처의 좁은 골목에 한옥이 모인 동네다. 한옥을 고쳐 만든 카페와 식당이 많다.", english: "A neighborhood of narrow alleys and hanok houses near Jongno 3-ga. Many of the old houses have become cafes and restaurants."),
        .init(id: "kr.seochon", ko: "경복궁 서쪽의 오래된 주택가 동네다. 한옥과 좁은 골목, 작은 가게와 갤러리가 어우러진다.", english: "An old residential area west of Gyeongbokgung. Hanok houses, narrow lanes, small shops and galleries sit side by side."),
        .init(id: "kr.ihwa_mural", ko: "종로구 낙산 아래 비탈 마을에 벽화가 그려진 곳이다. 골목을 따라 걸으며 그림과 서울 도심 풍경을 볼 수 있다.", english: "A hillside village below Naksan in Jongno-gu decorated with murals. Walking its lanes reveals paintings and views of the city."),
        .init(id: "kr.naksan", ko: "서울 한양도성 동쪽 낙산에 조성된 공원이다. 성곽길을 따라 걸으며 도심 야경을 볼 수 있다.", english: "A park on Naksan, the eastern hill of the old Seoul city wall. A walking path follows the wall and offers night views of the city."),
        .init(id: "kr.hanyang_wall", ko: "조선의 수도 한양을 둘러싼 성곽이다. 인왕산, 북악산, 낙산, 남산을 잇는 길을 따라 걸을 수 있다.", english: "The wall that enclosed Hanyang, the Joseon capital. Hikers can follow its route across Inwangsan, Bugaksan, Naksan and Namsan."),
        .init(id: "kr.seoul_grand_park", ko: "경기도 과천에 있는 대규모 공원이다. 동물원과 식물원, 놀이공원, 호수가 있어 가족 나들이 장소로 알려져 있다.", english: "A large park in Gwacheon, Gyeonggi Province. It combines a zoo, botanical garden, amusement park and lake, and suits family outings."),
        .init(id: "kr.children_grand_park", ko: "광진구에 있는 공원으로 어린이를 위한 놀이 시설과 동물원이 있다. 넓은 잔디밭과 식물원도 있어 가족 나들이에 알맞다.", english: "A park in Gwangjin-gu with children’s play areas and a small zoo. Wide lawns and a botanical garden make it suitable for family visits."),
        .init(id: "kr.bukhansan", ko: "서울 북쪽에 솟은 산으로 국립공원이다. 백운대와 인수봉의 화강암 봉우리가 대표적이고 등산로가 많다.", english: "A mountain north of Seoul protected as a national park. Granite peaks such as Baegundae and Insubong stand out, and many hiking trails cross it."),
        .init(id: "kr.dobongsan", ko: "서울 북쪽 도봉구에 있는 산으로 북한산 국립공원에 속한다. 자운봉과 선인봉 같은 바위 봉우리가 이어진다.", english: "A mountain in Dobong-gu, Seoul, within Bukhansan National Park. It is known for rocky peaks such as Jaunbong and Seonin."),
        .init(id: "kr.inwangsan", ko: "서울 도심 서쪽에 있는 바위산이다. 한양도성 성곽길이 지나며 정상에서 경복궁과 서울 시내를 내려다볼 수 있다.", english: "A rocky mountain on the western side of central Seoul. The old city wall trail passes by, and the summit overlooks Gyeongbokgung and the city."),
        .init(id: "kr.bugaksan", ko: "경복궁 뒤편에 있는 서울의 주산이다. 한양도성 성곽길로 오를 수 있으며 일부 구간은 신분 확인이 필요하다.", english: "The mountain behind Gyeongbokgung that guards the Joseon capital. Trails follow the old city wall, and some sections require ID checks."),
        .init(id: "kr.gwanaksan", ko: "서울 남쪽 관악구에 있는 산이다. 바위 봉우리와 연주대 암자가 알려져 있고 등산객이 많이 찾는다.", english: "A mountain on the south side of Seoul in Gwanak-gu. It is known for rocky peaks and the Yeonjudae hermitage, and attracts many hikers."),
        .init(id: "kr.achasan", ko: "광진구 한강 변에 있는 낮은 산이다. 고구려 보루 유적이 있으며 정상에서 한강과 서울 동쪽 풍경이 보인다.", english: "A low mountain beside the Han River in Gwangjin-gu. It holds the remains of Goguryeo fortresses and views of the river and eastern Seoul."),
        .init(id: "kr.hwarangdae", ko: "경춘선의 옛 기차역을 보존한 곳으로 노원구에 있다. 옛 역사와 객차를 활용한 전시 공간이 있다.", english: "A preserved old station on the Gyeongchun Line in Nowon-gu. The old station building and train cars are used as exhibition spaces."),
        .init(id: "kr.gyeongchun_forest", ko: "옛 경춘선 철길 위에 만든 산책로다. 철로와 나무가 어우러진 길을 따라 걸으며 카페와 작은 가게도 만날 수 있다.", english: "A walking path built along the old Gyeongchun railway line. Rails and trees line the route, with some cafes and small shops along the way."),
        .init(id: "kr.gyeongui_forest", ko: "옛 경의선 철길 자리에 조성한 마포·용산 일대의 선형 공원이다. 연남동과 공덕 사이를 산책하며 카페와 식당을 만날 수 있다.", english: "A linear park on the former Gyeongui railway line through Mapo and Yongsan. Walkers can stroll between Yeonnam-dong and Gongdeok past cafes and restaurants."),
        .init(id: "kr.haeundae", ko: "부산 동쪽에 있는 대표적인 해수욕장과 번화가다. 긴 모래사장과 바닷가 고층 건물이 인상적이며 여름에 사람이 많이 찾는다.", english: "A major beach and resort district on the east side of Busan. It has a long sandy shore backed by high-rise buildings and is busy in summer."),
        .init(id: "kr.gwangalli", ko: "부산 수영구에 있는 해수욕장이다. 광안대교가 바라보여 야경으로 알려져 있으며 해변에 카페와 식당이 이어진다.", english: "A beach in Suyeong-gu, Busan. It faces Gwangan Bridge and is known for its night views, with cafes and restaurants lining the shore."),
        .init(id: "kr.gwangan_bridge", ko: "부산 광안리와 해운대 쪽을 잇는 바다 위 이층 다리다. 밤에 다리 조명이 바뀌는 모습이 볼거리다.", english: "A double-deck sea bridge linking the Gwangalli and Haeundae sides of Busan. Its changing night lighting is a major attraction."),
        .init(id: "kr.gamcheon", ko: "부산 사하구 산비탈에 알록달록한 집들이 모인 마을이다. 골목 벽화와 조형물, 전망 포인트가 있어 걷기 좋다.", english: "A hillside village in Saha-gu, Busan, packed with colorful houses. Murals, sculptures and viewpoints make its lanes fun to explore."),
        .init(id: "kr.haedong_yonggungsa", ko: "부산 기장군 바닷가에 있는 사찰이다. 고려 시대에 창건된 것으로 전하며 파도 앞에 자리 잡은 모습이 특징이다.", english: "A seaside Buddhist temple in Gijang-gun, Busan. Tradition traces it to the Goryeo period, and it is notable for sitting right by the waves."),
        .init(id: "kr.taejongdae", ko: "부산 영도구 남쪽 끝에 있는 해안 절경지다. 절벽과 등대, 숲길이 이어지며 순환 열차도 이용할 수 있다.", english: "A scenic coastal area at the southern tip of Yeongdo-gu, Busan. Cliffs, a lighthouse and forest paths are linked by a loop train."),
        .init(id: "kr.jagalchi", ko: "부산 중구에 있는 대표 수산시장이다. 살아 있는 생선과 해산물을 팔고 그 자리에서 회를 먹을 수 있다.", english: "A major fish market in Jung-gu, Busan. Live fish and seafood are sold, and you can eat raw fish on the spot."),
        .init(id: "kr.busan_tower", ko: "부산 중구 용두산공원에 있는 탑이다. 전망대에서 부산항과 도심을 내려다볼 수 있다.", english: "A tower in Yongdusan Park, Jung-gu, Busan. Its observation deck overlooks Busan Port and the city center."),
        .init(id: "kr.oryukdo", ko: "부산 남구 앞바다에 늘어선 작은 바위섬들이다. 바다 위로 솟은 모습이 특징이며 해안 산책로와 스카이워크에서 볼 수 있다.", english: "A group of small rocky islets off Nam-gu, Busan. They rise from the sea and can be viewed from the coastal path and a sky walk."),
        .init(id: "kr.beomeosa", ko: "부산 금정산 자락에 있는 큰 사찰이다. 신라 시대에 창건된 것으로 전하며 산책로와 일주문이 알려져 있다.", english: "A large Buddhist temple on the slopes of Geumjeongsan in Busan. Tradition dates it to the Silla period, and it is known for its gate and walking paths."),
        .init(id: "kr.dongseongno", ko: "대구 중구에 있는 중심 번화가다. 상점과 카페, 식당이 모여 있고 쇼핑과 만남의 장소로 알려져 있다.", english: "The main downtown shopping street in Jung-gu, Daegu. Shops, cafes and restaurants gather here, and it is a popular meeting place."),
        .init(id: "kr.seomun_market", ko: "대구 중구에 있는 큰 전통시장이다. 직물과 의류, 먹거리를 파는 가게가 많고 야시장도 열린다.", english: "A large traditional market in Jung-gu, Daegu. It has many fabric, clothing and food stalls, and a night market is held there."),
        .init(id: "kr.apsan", ko: "대구 남구에 있는 산으로 시민들이 즐겨 찾는 등산로가 많다. 전망대에서 대구 시내를 내려다볼 수 있다.", english: "A mountain in Nam-gu, Daegu, with many trails used by locals. Its lookout offers views over the city."),
        .init(id: "kr.palgongsan", ko: "대구 북동쪽에 솟은 산으로 도립공원이다. 동화사와 갓바위 같은 불교 유적과 등산로가 알려져 있다.", english: "A mountain rising northeast of Daegu, protected as a provincial park. It is known for Buddhist sites such as Donghwasa and Gatbawi, and for hiking trails."),
        .init(id: "kr.donghwasa", ko: "대구 팔공산에 있는 사찰이다. 신라 시대에 창건된 것으로 전하며 큰 통일대불이 서 있다.", english: "A Buddhist temple on Palgongsan in Daegu. Tradition dates its founding to the Silla period, and a large Unification Buddha statue stands here."),
        .init(id: "kr.suseongmot", ko: "대구 수성구에 있는 인공 연못이다. 둘레길과 오리배, 호숫가 카페가 있어 산책 장소로 사랑받는다.", english: "An artificial pond in Suseong-gu, Daegu. A walking trail, paddle boats and lakeside cafes make it a favorite place for strolls."),
        .init(id: "kr.e_world", ko: "대구 달서구에 있는 놀이공원이다. 83타워가 상징이며 놀이기구와 야간 조명 행사로 알려져 있다.", english: "An amusement park in Dalseo-gu, Daegu. The 83 Tower is its symbol, and it is known for rides and night lighting events."),
        .init(id: "kr.kim_gwangseok", ko: "대구 중구 방천시장 옆 골목에 가수 김광석을 기리는 벽화와 조형물이 있는 길이다. 골목을 걸으며 구경할 수 있다.", english: "An alley beside Bangcheon Market in Jung-gu, Daegu, with murals and artworks honoring the singer Kim Kwang-seok. It is a pleasant place to stroll."),
        .init(id: "kr.incheon_chinatown", ko: "인천 중구 개항장 부근에 있는 중국풍 거리다. 짜장면 같은 중화요리를 맛볼 수 있고 붉은 문루가 눈에 띈다.", english: "A Chinese-style district near the old treaty port in Jung-gu, Incheon. Chinese restaurants serve dishes like jajangmyeon, and a red gateway marks the entrance."),
        .init(id: "kr.wolmido", ko: "인천 중구의 월미산 일대와 바닷가 지역이다. 놀이시설과 해안 산책로가 있고 월미바다열차를 탈 수 있다.", english: "A seaside area around Wolmisan in Jung-gu, Incheon. It has amusements, a coastal promenade and the Wolmi Sea Train."),
        .init(id: "kr.songdo_central", ko: "인천 송도국제도시 중심에 있는 도시 공원이다. 바닷물을 끌어들인 수로와 고층 건물이 어우러진다.", english: "An urban park at the heart of Songdo International City in Incheon. A seawater canal winds among high-rise buildings."),
        .init(id: "kr.incheon_bridge", ko: "인천 송도와 영종도를 잇는 바다 위 다리다. 사장교 형태의 주탑이 특징이며 서해를 가로지르는 드라이브로 알려져 있다.", english: "A sea bridge linking Songdo and Yeongjongdo in Incheon. Its cable-stayed towers are distinctive, and the drive crosses the Yellow Sea."),
        .init(id: "kr.ganghwa_dolmen", ko: "인천 강화도에 있는 청동기 시대 고인돌이다. 거대한 덮개돌이 얹힌 모습으로 유네스코 세계유산에 포함되어 있다.", english: "A Bronze Age dolmen on Ganghwado, Incheon. Its huge capstone is striking, and the site is part of a UNESCO World Heritage listing."),
        .init(id: "kr.jeondeungsa", ko: "강화도 정족산성 안에 있는 사찰이다. 삼랑성 안에 위치하며 고려 시대에도 이름이 전해지는 오래된 절이다.", english: "A Buddhist temple inside the Jeongjoksanseong fortress on Ganghwado. It is an old temple whose name appears in records since the Goryeo period."),
        .init(id: "kr.mani_san", ko: "강화도 남쪽에 있는 산이다. 정상 부근에 참성단이 있어 단군 전설과 관련된 곳으로 알려져 있다.", english: "A mountain in southern Ganghwado. Chamseongdan altar near the summit is linked to the legend of Dangun."),
        .init(id: "kr.eulwangri", ko: "인천 영종도 서쪽에 있는 해수욕장이다. 공항에서 가까워 접근이 쉽고 해변에서 노을과 갯벌을 볼 수 있다.", english: "A beach on the west side of Yeongjongdo in Incheon. It is close to the airport, and visitors can enjoy sunsets and tidal flats."),
        .init(id: "kr.asia_culture", ko: "광주 동구 옛 전남도청 일대에 조성된 문화 복합 시설이다. 전시와 공연, 연구 공간을 갖추고 있다.", english: "A cultural complex built around the former provincial office site in Dong-gu, Gwangju. It offers exhibitions, performances and research spaces."),
        .init(id: "kr.may18_park", ko: "광주 서구에 있는 5·18 민주화운동을 기억하는 공원이다. 당시 군 시설이 있던 자리에 조성되었다.", english: "A park in Seo-gu, Gwangju, commemorating the May 18 Democratic Uprising. It occupies a former military site from that period."),
        .init(id: "kr.may18_cemetery", ko: "광주 북구에 있는 5·18 민주화운동 희생자들이 묻힌 국립묘지다. 기념탑과 참배 공간, 전시관이 있다.", english: "A national cemetery in Buk-gu, Gwangju, for victims of the May 18 Democratic Uprising. It has a memorial tower, a place for paying respects and an exhibition hall."),
        .init(id: "kr.mudeungsan", ko: "광주와 화순에 걸친 산으로 국립공원이다. 주상절리 암벽인 서석대와 입석대가 알려져 있다.", english: "A mountain spanning Gwangju and Hwasun, protected as a national park. Columnar-jointed rock formations such as Seoseokdae and Ipseokdae are well known."),
        .init(id: "kr.yangnim", ko: "광주 남구에 있는 근대 건축이 남은 동네다. 서양식 건물과 선교사 유적, 작은 카페와 갤러리가 어우러진다.", english: "A neighborhood in Nam-gu, Gwangju, with preserved early modern buildings. Western-style houses, missionary sites, cafes and small galleries share the streets."),
        .init(id: "kr.chungjang", ko: "광주 동구의 중심 상가 거리다. 오래된 가게와 새 상점이 이어져 있고 쇼핑과 식사를 하기에 알맞다.", english: "A central shopping street in Dong-gu, Gwangju. Old stores and new shops line the road, which suits shopping and meals."),
        .init(id: "kr.gwangju_folk", ko: "광주 북구에 있는 민속박물관이다. 호남 지역 생활 문화와 전통 민속 자료를 전시한다.", english: "A folk museum in Buk-gu, Gwangju. It displays traditional daily life and folk culture materials from the Honam region."),
        .init(id: "kr.expo_park", ko: "대전 유성구에 있는 공원으로 1993년 대전 엑스포를 계기로 조성되었다. 한빛탑과 과학 시설이 있다.", english: "A park in Yuseong-gu, Daejeon, created for the 1993 Daejeon Expo. It features the Hanbit Tower and science facilities."),
        .init(id: "kr.hanbat_arboretum", ko: "대전 서구 도심에 있는 대형 수목원이다. 다양한 나무와 꽃, 연못이 있어 산책하기에 알맞다.", english: "A large arboretum in the city of Seo-gu, Daejeon. A variety of trees, flowers and ponds make it good for walks."),
        .init(id: "kr.yuseong_spa", ko: "대전 유성구에 있는 온천 지역이다. 온천 호텔과 족욕 시설이 있어 휴식하기에 알맞다.", english: "A hot spring area in Yuseong-gu, Daejeon. Spa hotels and a foot bath are available for relaxing."),
        .init(id: "kr.gyejoksan", ko: "대전 대덕구에 있는 산이다. 황톳길 맨발 걷기 코스로 알려져 있으며 산성 터도 남아 있다.", english: "A mountain in Daedeok-gu, Daejeon. It is known for a barefoot walking trail of red clay and for the remains of a mountain fortress."),
        .init(id: "kr.daecheong_lake", ko: "대전과 충북 청주·옥천에 걸친 대형 인공호수로, 대청댐 건설로 생겼다. 호반을 따라 드라이브 길과 산책로가 이어진다.", english: "A large reservoir created by the Daecheong Dam, spanning Daejeon and North Chungcheong. Lakeside drives and walking paths follow its shore."),
        .init(id: "kr.sungsimdang", ko: "대전 은행동에 본점을 둔 대표적인 제과점이다. 튀김소보로와 부추빵 같은 빵을 사려는 사람들이 줄을 서는 곳이다.", english: "A well-known bakery whose main shop is in Eunhaeng-dong, Daejeon. People queue for its fried soboro bread and chive bread."),
        .init(id: "kr.ppuri_park", ko: "대전 중구에 있는 공원으로, 성씨와 족보를 주제로 꾸민 곳이다. 여러 성씨의 뿌리를 알리는 조형물과 산책로가 있다.", english: "A park in Jung District, Daejeon, themed around family names and genealogy. It has monuments about the origins of Korean clans and pleasant walking paths."),
        .init(id: "kr.taehwagang", ko: "울산 도심을 가로지르는 태화강 변의 국가정원이다. 넓은 십리대숲과 계절마다 피는 꽃밭이 볼거리다.", english: "A national garden along the Taehwa River that runs through Ulsan. The broad bamboo grove and seasonal flower fields are the main sights."),
        .init(id: "kr.ganjeolgot", ko: "울산 울주군 동쪽 끝의 곶으로, 한반도에서 일출이 이른 곳으로 알려져 있다. 바다를 향한 등대와 대형 우체통이 있다.", english: "A cape at the eastern edge of Ulju County, Ulsan, known for early sunrises on the peninsula. A lighthouse and a giant postbox face the sea."),
        .init(id: "kr.daewangam", ko: "울산 동구 바닷가에 있는 공원으로, 기암괴석과 울창한 해송 숲이 어우러진다. 바위섬과 연결된 출렁다리와 등대를 볼 수 있다.", english: "A coastal park in Dong District, Ulsan, with odd rock formations and a dense pine forest. A suspension bridge and a lighthouse stand by the rocky islet."),
        .init(id: "kr.bangudae", ko: "울산 울주군 태화강 상류 절벽에 새겨진 선사시대 바위그림이다. 고래와 동물, 사냥 장면 등이 새겨져 있다.", english: "Prehistoric rock carvings on a cliff along the upper Taehwa River in Ulju County, Ulsan. The images include whales, animals and hunting scenes."),
        .init(id: "kr.jujeon", ko: "울산 동구 바닷가에 있는 몽돌해변이다. 파도에 닳은 둥근 자갈이 밀려가며 내는 소리가 특징이다.", english: "A pebble beach on the coast of Dong District, Ulsan. Waves rolling over the smooth round stones make a distinctive sound."),
        .init(id: "kr.yeongnam_alps", ko: "울산과 경남 양산 경계에 솟은 영남알프스의 대표 봉우리다. 가을 억새 평원으로 널리 알려져 있다.", english: "A main peak of the Yeongnam Alps on the border of Ulsan and Yangsan. It is widely known for its silver grass plains in autumn."),
        .init(id: "kr.jangsaengpo", ko: "울산 남구 장생포에 있는 고래 테마 마을이다. 한때 고래잡이 항구였던 곳으로, 고래박물관과 생태체험관이 있다.", english: "A whale-themed village in Jangsaengpo, Nam District, Ulsan, once a whaling port. It has a whale museum and an ecology experience center."),
        .init(id: "kr.sejong_lake", ko: "세종시 중심부에 있는 대규모 인공 호수공원이다. 호수 주변으로 산책로와 섬 정원, 수변 무대가 있다.", english: "A large artificial lake park in the heart of Sejong City. Walking paths, an island garden and a waterside stage surround the lake."),
        .init(id: "kr.sejong_arboretum", ko: "세종시에 있는 국립 수목원으로, 다양한 기후대의 식물을 한곳에 모았다. 온실과 한국 전통 정원 등을 둘러볼 수 있다.", english: "A national arboretum in Sejong City gathering plants from several climate zones. Visitors can tour its greenhouse and traditional Korean gardens."),
        .init(id: "kr.sejong_library", ko: "세종시 정부청사 가까이에 있는 국립 도서관이다. 책을 펼친 모양을 닮은 건물과 옥상 정원이 특징이다.", english: "A national library near the government buildings in Sejong City. The building resembles an open book and has a rooftop garden."),
        .init(id: "kr.government_complex", ko: "세종시에 자리한 정부 중앙 부처 청사로, 긴 건물이 곡선으로 이어진다. 옥상 정원이 이어져 있어 도시를 내려다볼 수 있다.", english: "The government ministries complex in Sejong City, a long curving chain of buildings. A connected rooftop garden offers views over the city."),
        .init(id: "kr.geumgang_bridge", ko: "세종시에서 금강을 가로지르는 보행 전용 다리로, 둥근 고리 모양의 독특한 형태다. 강 위를 걸으며 경치를 볼 수 있다.", english: "A pedestrian-only bridge over the Geum River in Sejong City, with a distinctive ring-shaped design. Visitors can stroll above the river and enjoy the view."),
        .init(id: "kr.hwaseong", ko: "조선 정조 때 수원에 쌓은 성곽으로 유네스코 세계유산이다. 성벽 길을 따라 팔달문과 화서문, 장안문 등을 볼 수 있다.", english: "A fortress built in Suwon during the reign of King Jeongjo of Joseon and a UNESCO World Heritage Site. Its wall walk passes gates such as Paldalmun, Hwaseomun and Janganmun."),
        .init(id: "kr.namhansanseong", ko: "경기 광주와 성남, 하남에 걸친 산성으로 유네스코 세계유산이다. 조선 시대에 임금이 피신했던 곳으로 성곽 길이 이어진다.", english: "A mountain fortress spanning Gwangju, Seongnam and Hanam in Gyeonggi, and a UNESCO World Heritage Site. It served as a refuge for Joseon kings, and a wall trail runs along it."),
        .init(id: "kr.everland", ko: "경기 용인에 있는 대형 테마파크다. 놀이기구와 동물원, 계절 축제가 있는 곳이다.", english: "A large theme park in Yongin, Gyeonggi. It offers rides, a zoo and seasonal festivals."),
        .init(id: "kr.korean_folk", ko: "경기 용인에 있는 민속 마을 테마파크로, 조선 시대 생활상을 재현했다. 전통 가옥과 공연, 장터 체험을 즐길 수 있다.", english: "A folk village theme park in Yongin, Gyeonggi, recreating life in the Joseon era. Visitors can see traditional houses, performances and a market."),
        .init(id: "kr.dmz_imjingak", ko: "경기 파주 임진강변에 있는 관광지로, 분단의 역사를 보여 주는 곳이다. 자유의 다리와 망배단, 평화누리공원이 가까이 있다.", english: "A tourist site on the Imjin River in Paju, Gyeonggi, reflecting the history of national division. The Freedom Bridge, a memorial altar and Peace Nuri Park are nearby."),
        .init(id: "kr.heyri", ko: "경기 파주에 조성된 예술인 마을이다. 갤러리와 박물관, 공방, 카페가 모여 있다.", english: "An artists’ village in Paju, Gyeonggi. Galleries, museums, workshops and cafes are gathered here."),
        .init(id: "kr.dumulmeori", ko: "경기 양평에서 남한강과 북한강이 만나는 곳이다. 수령 높은 느티나무와 연꽃, 물안개 풍경이 알려져 있다.", english: "The place in Yangpyeong, Gyeonggi, where the South and North Han Rivers meet. It is known for an old zelkova tree, lotus flowers and misty river scenery."),
        .init(id: "kr.gwangmyeong_cave", ko: "경기 광명에 있는 옛 광산 동굴로, 문화 공간으로 바뀌었다. 지하 터널 안에 조명과 전시, 와인 저장 공간이 있다.", english: "A former mine in Gwangmyeong, Gyeonggi, converted into a cultural space. The underground tunnels hold lighting displays, exhibitions and a wine cellar."),
        .init(id: "kr.ilsan_lake", ko: "경기 고양 일산신도시에 있는 큰 인공 호수공원이다. 호수를 도는 산책로와 자전거길, 꽃 전시가 있다.", english: "A large artificial lake park in Ilsan New Town, Goyang, Gyeonggi. It has a loop path for walkers and cyclists and flower displays."),
        .init(id: "kr.yongmunsa", ko: "경기 양평 용문산에 있는 사찰이다. 경내에는 오래된 은행나무가 있어 가을 단풍으로 유명하다.", english: "A temple on Yongmunsan in Yangpyeong, Gyeonggi. An old ginkgo tree in its grounds is famous for golden autumn colors."),
        .init(id: "kr.seoraksan", ko: "강원 속초·양양·인제에 걸친 산으로 국립공원이자 유네스코 생물권보전지역이다. 기암괴석과 계곡, 가을 단풍이 볼거리다.", english: "A mountain spanning Sokcho, Yangyang and Inje in Gangwon, a national park and UNESCO Biosphere Reserve. Rugged rock peaks, valleys and autumn foliage are the highlights."),
        .init(id: "kr.nami", ko: "강원 춘천 북한강에 있는 섬으로, 가평 쪽 선착장에서 배로 들어간다. 메타세쿼이아 길과 은행나무 길이 이어진다.", english: "An island in the North Han River near Chuncheon, Gangwon, reached by ferry from the Gapyeong side. Tree-lined paths of metasequoia and ginkgo run through it."),
        .init(id: "kr.gyeongpo", ko: "강원 강릉 경포호 옆 언덕에 서 있는 옛 누각이다. 호수와 동해, 소나무 숲이 함께 내려다보인다.", english: "An old pavilion on a hill beside Gyeongpo Lake in Gangneung, Gangwon. It overlooks the lake, the East Sea and a pine forest."),
        .init(id: "kr.jeongdongjin", ko: "강원 강릉 바닷가의 마을로, 해돋이 명소로 알려져 있다. 기차역이 바다와 아주 가깝고 모래시계 공원이 있다.", english: "A seaside village in Gangneung, Gangwon, known for sunrise viewing. Its railway station sits very close to the sea, and a sand clock park stands nearby."),
        .init(id: "kr.woljeongsa", ko: "강원 평창 오대산에 있는 사찰로, 신라 때 창건했다고 전해진다. 팔각구층석탑과 전나무 숲길이 알려져 있다.", english: "A temple on Odaesan in Pyeongchang, Gangwon, said to have been founded in the Silla era. Its nine-story octagonal pagoda and fir-lined path are well known."),
        .init(id: "kr.odaesan", ko: "강원 평창·홍천·강릉에 걸친 산으로 국립공원이다. 다섯 봉우리와 깊은 숲, 계곡을 따라 걷는 길이 있다.", english: "A mountain across Pyeongchang, Hongcheon and Gangneung in Gangwon, protected as a national park. It has five peaks, deep forests and valley trails."),
        .init(id: "kr.naksansa", ko: "강원 양양 동해 바닷가 언덕에 있는 사찰이다. 바다를 향한 해수관음상과 의상대가 알려져 있다.", english: "A temple on a hillside by the East Sea in Yangyang, Gangwon. It is known for its sea-facing Haesu Gwaneum statue and Uisangdae pavilion."),
        .init(id: "kr.chiaksan", ko: "강원 원주에 있는 산으로 국립공원이다. 가파른 능선과 구룡사, 가을 단풍이 알려져 있다.", english: "A mountain in Wonju, Gangwon, protected as a national park. It is known for steep ridges, Guryongsa temple and autumn colors."),
        .init(id: "kr.dmz_goseong", ko: "강원 고성의 비무장지대 가까이에 있는 전망대다. 북녘 땅과 금강산 쪽 산줄기를 바라볼 수 있다.", english: "An observatory near the demilitarized zone in Goseong, Gangwon. Visitors can look across to North Korean land and the mountain ranges toward Geumgangsan."),
        .init(id: "kr.alpensia", ko: "강원 평창에 있는 대규모 스포츠·휴양 단지다. 스키장과 점프대가 있고 평창 동계올림픽 경기가 열린 곳이다.", english: "A large sports and resort complex in Pyeongchang, Gangwon. It has ski slopes and jumping hills and hosted events of the Pyeongchang Winter Olympics."),
        .init(id: "kr.cheongnamdae", ko: "충북 청주 대청호반에 있는 옛 대통령 별장이다. 지금은 일반에 개방되어 정원과 호수 산책로를 둘러볼 수 있다.", english: "A former presidential retreat on the shore of Daecheong Lake near Cheongju, North Chungcheong. It is now open to the public, with gardens and a lakeside trail."),
        .init(id: "kr.songnisan", ko: "충북 보은과 경북 상주에 걸친 산으로 국립공원이다. 법주사와 문장대 등 바위 봉우리가 알려져 있다.", english: "A mountain across Boeun in North Chungcheong and Sangju in North Gyeongsang, protected as a national park. Beopjusa temple and the rocky peak Munjangdae are well known."),
        .init(id: "kr.beopjusa", ko: "충북 보은 속리산에 있는 사찰로 유네스코 세계유산이다. 높이 솟은 팔상전과 큰 청동 불상이 볼거리다.", english: "A temple on Songnisan in Boeun, North Chungcheong, and a UNESCO World Heritage Site. The tall Palsangjeon hall and a large bronze Buddha statue stand out."),
        .init(id: "kr.dodamsambong", ko: "충북 단양 남한강 한가운데에 솟은 세 개의 바위 봉우리다. 조선의 학자 정도전과 관련된 이야기가 전해진다.", english: "Three rock peaks rising from the South Han River in Danyang, North Chungcheong. A tale linked to the Joseon scholar Jeong Do-jeon is told about the place."),
        .init(id: "kr.gosu_cave", ko: "충북 단양에 있는 석회암 동굴로 천연기념물이다. 종유석과 석순이 발달해 있고 관람로가 정비되어 있다.", english: "A limestone cave in Danyang, North Chungcheong, designated a natural monument. It has well-developed stalactites and stalagmites along a maintained walkway."),
        .init(id: "kr.woraksan", ko: "충북 제천과 충주, 단양에 걸친 산으로 국립공원이다. 우뚝한 영봉과 충주호를 내려다보는 경치가 알려져 있다.", english: "A mountain across Jecheon, Chungju and Danyang in North Chungcheong, protected as a national park. Its towering peak and views over Chungju Lake are known."),
        .init(id: "kr.uirimji", ko: "충북 제천에 있는 오래된 저수지로, 삼한 시대에 만들어졌다고 전해진다. 호숫가 소나무와 산책로가 어우러진다.", english: "An old reservoir in Jecheon, North Chungcheong, said to date back to the Three Han period. Pine trees and a walking path line its shore."),
        .init(id: "kr.sangdang", ko: "충북 청주 상당산에 있는 산성이다. 성곽을 따라 걷는 길에서 청주 시내가 내려다보인다.", english: "A mountain fortress on Sangdangsan in Cheongju, North Chungcheong. A trail along its walls looks over the city."),
        .init(id: "kr.gongsanseong", ko: "충남 공주 금강변에 있는 백제 시대 산성으로 유네스코 세계유산이다. 성곽 길을 걸으며 강과 시내를 볼 수 있다.", english: "A Baekje-era mountain fortress on the Geum River in Gongju, South Chungcheong, and a UNESCO World Heritage Site. Walking its walls gives views of the river and city."),
        .init(id: "kr.muryeong", ko: "충남 공주 송산리 고분군에 있는 백제 무령왕의 무덤이다. 1971년 발굴 때 훼손되지 않은 채 발견되었고 유네스코 세계유산에 속한다.", english: "The tomb of Baekje King Muryeong in the Songsan-ri tomb group in Gongju, South Chungcheong. It was found intact when excavated in 1971 and is part of a UNESCO World Heritage Site."),
        .init(id: "kr.buso", ko: "충남 부여에 있는 백제 시대 산성으로 유네스코 세계유산에 속한다. 사비 도읍의 뒷산에 있고 낙화암과 고란사가 가까이 있다.", english: "A Baekje-era mountain fortress in Buyeo, South Chungcheong, part of a UNESCO World Heritage Site. It lies behind the old Sabi capital, near Nakhwaam rock and Goransa temple."),
        .init(id: "kr.jeongnimsa", ko: "충남 부여에 있는 백제 시대 절터로 유네스코 세계유산에 속한다. 5층 석탑과 석불좌상이 남아 있다.", english: "A Baekje-era temple site in Buyeo, South Chungcheong, part of a UNESCO World Heritage Site. A five-story stone pagoda and a seated stone Buddha remain."),
        .init(id: "kr.daecheon", ko: "충남 보령에 있는 서해안의 대표적인 해수욕장이다. 넓은 백사장과 얕은 바다가 이어지고 여름에는 머드 축제가 열린다.", english: "A major west coast beach in Boryeong, South Chungcheong. It has a wide sandy shore and shallow water, and hosts a mud festival in summer."),
        .init(id: "kr.anmyeon", ko: "충남 태안 안면도에 있는 해수욕장이다. 두 개의 바위가 선 바다 위로 지는 해가 이름난 곳이다.", english: "A beach on Anmyeondo in Taean, South Chungcheong. It is known for sunsets over the sea with two standing rocks in the water."),
        .init(id: "kr.haemi", ko: "충남 서산에 있는 조선 시대 읍성이다. 성곽과 관아가 잘 남아 있고 천주교 순교와 관련된 역사도 전해진다.", english: "A Joseon-era walled town in Seosan, South Chungcheong. The walls and government buildings are well preserved, and it also has history tied to Catholic martyrdom."),
        .init(id: "kr.independence_hall", ko: "충남 천안에 있는 박물관 단지로 일제강점기 독립운동과 한국 근현대사를 다룬다. 넓은 야외 공간에 큰 전시관이 이어진다.", english: "A museum complex in Cheonan, South Chungcheong, covering the independence movement under Japanese rule and modern Korean history. Large exhibition halls stand in a broad open park."),
        .init(id: "kr.oeam", ko: "충남 아산에 있는 전통 민속 마을이다. 초가와 기와집, 돌담길이 남아 있고 지금도 주민이 살고 있다.", english: "A traditional folk village in Asan, South Chungcheong. Thatched and tile-roofed houses and stone-wall lanes remain, and residents still live there."),
        .init(id: "kr.gyeryongsan", ko: "충남 공주와 대전에 걸친 산으로 국립공원이다. 닭 볏과 용을 닮은 능선이라 이름 붙었고 갑사와 동학사가 있다.", english: "A mountain across Gongju and Daejeon, protected as a national park. Its ridge resembles a rooster comb and a dragon, and the temples Gapsa and Donghaksa lie on it."),
        .init(id: "kr.jeonju_hanok", ko: "전북 전주 도심에 한옥 700여 채가 모여 있는 전통 마을이다. 비빔밥 등 전통 음식과 공예 체험이 알려져 있다.", english: "A traditional village of hundreds of hanok houses in central Jeonju, North Jeolla. It is known for traditional food such as bibimbap and for craft experiences."),
        .init(id: "kr.gyeonggijeon", ko: "전북 전주 한옥마을에 있는 조선 시대 사당으로, 태조 이성계의 초상화를 모신 곳이다. 고즈넉한 경내와 대나무 숲이 볼거리다.", english: "A Joseon-era shrine in Jeonju Hanok Village that houses a portrait of King Taejo, founder of Joseon. A calm courtyard and a bamboo grove are the highlights."),
        .init(id: "kr.naejangsan", ko: "전북 정읍과 전남 순창에 걸친 산으로 국립공원이다. 가을 단풍이 특히 유명하고 내장사가 있다.", english: "A mountain across Jeongeup in North Jeolla and Sunchang in South Jeolla, protected as a national park. It is especially famous for autumn foliage and has Naejangsa temple."),
        .init(id: "kr.maisan", ko: "전북 진안에 있는 산으로 두 봉우리가 말의 귀처럼 솟았다. 탑사의 돌탑 무리가 함께 알려져 있다.", english: "A mountain in Jinan, North Jeolla, whose two peaks rise like a horse’s ears. The clusters of stone towers at Tapsa temple are also well known."),
        .init(id: "kr.seonunsa", ko: "전북 고창 선운산에 있는 사찰이다. 봄의 동백과 가을의 꽃무릇, 단풍으로 이름이 알려져 있다.", english: "A temple on Seonunsan in Gochang, North Jeolla. It is known for camellias in spring and for red spider lilies and foliage in autumn."),
        .init(id: "kr.gochang_dolmen", ko: "전북 고창에 있는 선사시대 고인돌 유적으로 유네스코 세계유산이다. 수백 기의 고인돌이 산자락을 따라 분포한다.", english: "A prehistoric dolmen site in Gochang, North Jeolla, and a UNESCO World Heritage Site. Hundreds of dolmens are scattered along the foothills."),
        .init(id: "kr.mireuksa", ko: "전북 익산에 있는 백제 시대 절터로 유네스코 세계유산에 속한다. 복원된 석탑이 넓은 터에 서 있다.", english: "A Baekje-era temple site in Iksan, North Jeolla, part of a UNESCO World Heritage Site. A restored stone pagoda stands in a wide open field."),
        .init(id: "kr.saemangeum", ko: "전북 군산과 부안을 잇는 거대한 방조제로, 세계에서 매우 긴 방조제로 알려져 있다. 서해를 옆에 두고 달리는 드라이브 길이다.", english: "A huge seawall linking Gunsan and Buan in North Jeolla, known as one of the longest in the world. It makes a scenic drive beside the Yellow Sea."),
        .init(id: "kr.deogyusan", ko: "전북 무주·장수와 경남 거창·함양에 걸친 산으로 국립공원이다. 겨울 설경과 스키장이 알려져 있다.", english: "A mountain across Muju and Jangsu in North Jeolla and Geochang and Hamyang in South Gyeongsang, protected as a national park. It is known for snowy winter scenery and a ski resort."),
        .init(id: "kr.suncheon_bay", ko: "전남 순천에 있는 갯벌과 갈대밭 습지로 람사르 습지다. 철새가 찾아오고 전망대에서 S자 물길을 볼 수 있다.", english: "A tidal flat and reed wetland in Suncheon, South Jeolla, listed as a Ramsar site. Migratory birds visit, and an observatory overlooks the S-shaped waterway."),
        .init(id: "kr.nagan", ko: "전남 순천에 있는 조선 시대 읍성 마을이다. 성곽 안에 초가집이 모여 있고 지금도 사람이 살고 있다.", english: "A Joseon-era walled town in Suncheon, South Jeolla. Thatched houses cluster within the walls, and people still live there."),
        .init(id: "kr.songgwangsa", ko: "전남 순천 조계산에 있는 사찰로, 한국 삼보사찰 가운데 승보사찰로 알려져 있다. 오래된 전각과 호젓한 숲길이 어우러진다.", english: "A temple on Jogyesan in Suncheon, South Jeolla, known as the Sangha Jewel temple among Korea’s three jewel temples. Old halls and quiet forest paths surround it."),
        .init(id: "kr.yeosu_expo", ko: "전남 여수 바닷가에 있는 2012년 여수 세계박람회 터다. 전시관과 해양 시설, 야간 미디어 쇼가 있다.", english: "The site of the 2012 Yeosu World Expo on the Yeosu waterfront, South Jeolla. It has exhibition halls, marine facilities and a night media show."),
        .init(id: "kr.hyangiram", ko: "전남 여수 금오산 절벽에 있는 암자다. 바위 틈새를 지나 올라가며 남해 일출을 볼 수 있다.", english: "A hermitage on a cliff of Geumosan in Yeosu, South Jeolla. Visitors climb through gaps in the rock and can watch the sunrise over the South Sea."),
        .init(id: "kr.boseong_tea", ko: "전남 보성에 있는 계단식 녹차밭이다. 산비탈을 따라 늘어선 초록 이랑과 삼나무 길이 볼거리다.", english: "Terraced green tea fields in Boseong, South Jeolla. Green rows along the hillside and a cedar-lined path are the main sights."),
        .init(id: "kr.damyang_bamboo", ko: "전남 담양에 있는 대나무 숲 공원이다. 울창한 대숲 사이로 산책로가 이어진다.", english: "A bamboo forest park in Damyang, South Jeolla. Walking paths wind through the dense groves."),
        .init(id: "kr.damyang_metasequoia", ko: "전남 담양에 있는 메타세쿼이아 가로수길이다. 곧게 뻗은 나무가 길 양옆으로 늘어서 있다.", english: "A road lined with metasequoia trees in Damyang, South Jeolla. Tall straight trees stand on both sides of the road."),
        .init(id: "kr.jirisan", ko: "전남·전북·경남에 걸친 산으로 한국 최초의 국립공원이다. 천왕봉과 노고단, 넓은 계곡과 사찰이 알려져 있다.", english: "A mountain across South Jeolla, North Jeolla and South Gyeongsang, and Korea’s first national park. Cheonwangbong, Nogodan, wide valleys and temples are well known."),
        .init(id: "kr.haenam_ttangkkeut", ko: "전남 해남에 있는 한반도 육지 최남단 마을이다. 땅끝 전망대와 기념탑, 섬으로 가는 배편이 있다.", english: "A village in Haenam, South Jeolla, at the southern tip of the Korean mainland. It has an observatory, a monument and ferries to nearby islands."),
        .init(id: "kr.bulguksa", ko: "경북 경주 토함산에 있는 신라 시대 사찰로 유네스코 세계유산이다. 다보탑과 석가탑, 청운교·백운교가 대표적인 볼거리다.", english: "A Silla-era temple on Tohamsan in Gyeongju, North Gyeongsang, and a UNESCO World Heritage Site. Dabotap, Seokgatap and the Cheongungyo and Baegungyo bridges are the highlights."),
        .init(id: "kr.seokguram", ko: "경북 경주 토함산 중턱에 있는 신라 시대 석굴 사원으로 유네스코 세계유산이다. 돌로 쌓은 굴 안에 본존불이 모셔져 있다.", english: "A Silla-era grotto temple on the slope of Tohamsan in Gyeongju, North Gyeongsang, and a UNESCO World Heritage Site. A main Buddha statue sits inside the stone chamber."),
        .init(id: "kr.cheomseongdae", ko: "경북 경주에 있는 신라 시대 천문 관측 시설이다. 돌을 쌓아 올린 병 모양 탑으로 한국에서 오래된 천문대로 알려져 있다.", english: "A Silla-era astronomical observatory in Gyeongju, North Gyeongsang. This bottle-shaped tower of stacked stones is known as one of Korea’s oldest observatories."),
        .init(id: "kr.daereungwon", ko: "경북 경주 도심에 있는 신라 시대 고분군이다. 둥근 무덤 사이로 산책로가 이어지고 천마총을 내부까지 볼 수 있다.", english: "A Silla-era tomb park in the center of Gyeongju, North Gyeongsang. Paths wind among the round burial mounds, and Cheonmachong tomb can be viewed from the inside."),
        .init(id: "kr.donggung", ko: "경북 경주에 있는 신라 왕궁의 별궁과 연못 터다. 야경 때 연못에 비치는 전각이 특히 아름다워 많이 찾는다.", english: "The site of a Silla royal secondary palace and pond in Gyeongju, North Gyeongsang. At night the pavilions reflected in the pond draw many visitors."),
        .init(id: "kr.hahoe", ko: "경북 안동에 있는 전통 마을로 유네스코 세계유산이다. 낙동강이 마을을 휘감아 흐르고 옛 양반 가옥과 초가가 남아 있다.", english: "A traditional village in Andong, North Gyeongsang, and a UNESCO World Heritage Site. The Nakdong River curls around it, and old yangban houses and thatched homes remain."),
        .init(id: "kr.dosan", ko: "경북 안동에 있는 조선 시대 서원으로 유네스코 세계유산에 속한다. 학자 이황이 후학을 가르치던 곳이다.", english: "A Joseon-era Confucian academy in Andong, North Gyeongsang, part of a UNESCO World Heritage listing. It is where the scholar Yi Hwang taught students."),
        .init(id: "kr.ulleungdo", ko: "경북 동해에 떨어져 있는 화산섬이다. 해안 절벽과 성인봉, 독특한 기암이 알려져 있고 포항 등에서 배로 간다.", english: "A volcanic island in the East Sea belonging to North Gyeongsang. It is known for coastal cliffs, Seonginbong peak and unusual rock formations, reached by ferry from ports such as Pohang."),
        .init(id: "kr.dokdo", ko: "동해에 있는 화산섬으로 한국이 실효 지배하며 경북 울릉군에 속한다. 동도와 서도 두 섬과 작은 바위들로 이루어져 있다.", english: "A volcanic island group in the East Sea administered by Korea as part of Ulleung County, North Gyeongsang. It consists of two main islets, East and West, and many small rocks."),
        .init(id: "kr.homigot", ko: "경북 포항 동쪽 끝에 있는 곶으로, 한반도를 호랑이에 빗댈 때 꼬리에 해당하는 곳이다. 바다에 선 손 모양 조형물과 등대가 있다.", english: "A cape at the eastern tip of Pohang, North Gyeongsang, which corresponds to the tail when the peninsula is likened to a tiger. A hand-shaped sculpture stands in the sea beside a lighthouse."),
        .init(id: "kr.juwangsan", ko: "경북 청송에 있는 산으로 국립공원이다. 병풍 같은 암벽과 폭포, 계곡 길이 알려져 있다.", english: "A mountain in Cheongsong, North Gyeongsang, protected as a national park. It is known for screen-like rock walls, waterfalls and valley trails."),
        .init(id: "kr.buseoksa", ko: "경북 영주 봉황산에 있는 신라 시대 사찰로 유네스코 세계유산이다. 무량수전은 한국 목조건축의 대표작으로 꼽힌다.", english: "A Silla-era temple on Bonghwangsan in Yeongju, North Gyeongsang, and a UNESCO World Heritage Site. Its Muryangsujeon hall is regarded as a leading example of Korean wooden architecture."),
        .init(id: "kr.haeinsa", ko: "경남 합천 가야산에 있는 사찰로 유네스코 세계유산이다. 팔만대장경판을 보관하는 장경판전으로 알려져 있다.", english: "A temple on Gayasan in Hapcheon, South Gyeongsang, and a UNESCO World Heritage Site. It is known for the Janggyeong Panjeon halls that store the Tripitaka Koreana woodblocks."),
        .init(id: "kr.tongdosa", ko: "경남 양산 영축산에 있는 큰 사찰로 유네스코 세계유산이다. 부처의 사리를 모신 금강계단이 있어 불보사찰로 불린다.", english: "A large temple on Yeongchuksan in Yangsan, South Gyeongsang, and a UNESCO World Heritage Site. It enshrines Buddha relics at the Geumgang Altar and is called the Buddha Jewel temple."),
        .init(id: "kr.jinju_fortress", ko: "경남 진주 남강변에 있는 성곽이다. 임진왜란 때 진주성 전투가 벌어진 곳이고 촉석루가 알려져 있다.", english: "A fortress on the Nam River in Jinju, South Gyeongsang. The Battle of Jinju took place here during the Imjin War, and the Chokseongnu pavilion is well known."),
        .init(id: "kr.tongyeong_cable", ko: "경남 통영의 미륵산을 오르는 케이블카다. 정상에서 한려해상의 섬과 바다가 내려다보인다.", english: "A cable car up Mireuksan in Tongyeong, South Gyeongsang. From the top, visitors see the islands and sea of the Hallyeo Waterway."),
        .init(id: "kr.dongpirang", ko: "경남 통영 바닷가 언덕에 있는 벽화 마을이다. 골목마다 그림이 있고 항구가 내려다보인다.", english: "A mural village on a seaside hill in Tongyeong, South Gyeongsang. Paintings fill the alleys, and the harbor can be seen from above."),
        .init(id: "kr.geoje_oedo", ko: "경남 거제 앞바다에 있는 섬으로 식물원 정원이 조성되어 있다. 유람선으로 가고 해상 정원과 조각 같은 조형물이 볼거리다.", english: "An island off Geoje, South Gyeongsang, with a botanical garden. It is reached by sightseeing boat and is known for its seaside garden and sculptures."),
        .init(id: "kr.namhae_german", ko: "경남 남해에 있는 마을로, 독일에서 돌아온 교포들이 정착해 이룬 곳이다. 독일식 주택과 바다 전망이 어우러진다.", english: "A village in Namhae, South Gyeongsang, settled by Koreans returning from Germany. German-style houses blend with sea views."),
        .init(id: "kr.upo", ko: "경남 창녕에 있는 국내에서 큰 규모의 내륙 습지로 람사르 습지다. 물풀과 철새, 탐조 산책로가 있다.", english: "One of Korea’s largest inland wetlands, in Changnyeong, South Gyeongsang, and a Ramsar site. It has water plants, migratory birds and birdwatching trails."),
        .init(id: "kr.gayasan", ko: "경남 합천과 경북 성주에 걸친 산으로 국립공원이다. 기암 봉우리와 계곡이 있고 해인사가 산자락에 있다.", english: "A mountain across Hapcheon in South Gyeongsang and Seongju in North Gyeongsang, protected as a national park. It has rocky peaks and valleys, with Haeinsa temple on its slope."),
        .init(id: "kr.jinhae", ko: "경남 창원 진해에 있는 하천 길로 봄 벚꽃 명소다. 하천 양옆으로 벚나무가 터널을 이루고 다리와 산책로가 이어진다.", english: "A stream-side road in Jinhae, Changwon, South Gyeongsang, famous for spring cherry blossoms. Cherry trees form a tunnel along both banks, with bridges and walkways."),
        .init(id: "kr.hallasan", ko: "제주도 한가운데 솟은 한국에서 가장 높은 산으로 국립공원이자 유네스코 세계유산이다. 정상에 화구호 백록담이 있고 여러 등산로가 있다.", english: "The tallest mountain in Korea, rising at the center of Jeju Island, a national park and UNESCO World Heritage Site. A crater lake, Baengnokdam, lies at the summit, and several hiking trails lead up."),
        .init(id: "kr.seongsan", ko: "제주 동쪽 끝에 있는 화산 분화구 지형으로 유네스코 세계유산이다. 바다에서 솟은 절벽 모양이며 정상에서 일출과 분화구를 볼 수 있다.", english: "A volcanic tuff cone at the eastern end of Jeju, and a UNESCO World Heritage Site. It rises from the sea as a cliff, with sunrise and crater views from the top."),
        .init(id: "kr.udo", ko: "제주 성산 앞바다에 있는 섬으로 배로 들어간다. 소가 누운 모양이라는 이름이고 해변과 등대, 자전거 일주길이 있다.", english: "An island off Seongsan, Jeju, reached by ferry. Its name refers to a lying ox, and it has beaches, a lighthouse and a cycling loop."),
        .init(id: "kr.manjanggul", ko: "제주 구좌읍에 있는 용암동굴로 유네스코 세계유산에 속한다. 세계적으로 규모가 큰 용암 동굴로 알려져 있고 일부 구간만 개방한다.", english: "A lava tube in Gujwa, Jeju, part of a UNESCO World Heritage Site. It is known as a large lava cave, and only a section is open to visitors."),
        .init(id: "kr.hyeopjae", ko: "제주 서쪽 한림에 있는 해수욕장이다. 에메랄드빛 얕은 바다와 흰 모래, 멀리 보이는 비양도가 특징이다.", english: "A beach in Hallim on western Jeju. It features shallow emerald water, white sand and a view of Biyangdo island."),
        .init(id: "kr.jungmun", ko: "제주 서귀포에 있는 대규모 관광 단지다. 호텔과 해변, 폭포, 박물관이 모여 있다.", english: "A large resort area in Seogwipo, Jeju. Hotels, beaches, waterfalls and museums are gathered here."),
        .init(id: "kr.cheonjiyeon", ko: "서귀포 시내 가까이에 있는 제주의 대표적인 폭포다. 계곡 숲을 따라 걸어 내려가면 바다로 가까운 곳에서 물줄기가 떨어지는 모습을 볼 수 있다.", english: "A waterfall near downtown Seogwipo on Jeju Island. A walk through the wooded valley leads to the cascade, which drops not far from the sea."),
        .init(id: "kr.jeongbang", ko: "서귀포 바닷가에 있는 폭포로, 물이 절벽에서 곧바로 바다로 떨어지는 것이 특징이다. 제주의 이름난 폭포 가운데 하나로 해안 풍경과 함께 감상한다.", english: "A waterfall on the Seogwipo coast whose water plunges from a cliff straight into the sea. It is one of Jeju’s well-known falls and is enjoyed together with the coastal scenery."),
        .init(id: "kr.saryeoni", ko: "제주 중산간의 숲속을 따라 이어지는 산책길이다. 삼나무와 활엽수가 우거진 흙길을 걸으며 숲의 정취를 느낄 수 있다.", english: "A walking trail through the forest in Jeju’s mid-mountain highlands. Visitors stroll along a dirt path shaded by cedar and broadleaf trees."),
        .init(id: "kr.seopjikoji", ko: "제주 동남쪽 성산 가까이에 바다로 튀어나온 곶이다. 푸른 바다와 초원, 해안 절벽이 어우러지는 산책 코스로 알려져 있다.", english: "A headland jutting into the sea on Jeju’s southeast coast near Seongsan. Ocean, grassland and coastal cliffs make it a popular walking spot."),
        .init(id: "kr.yongduam", ko: "제주 시내 바닷가에 있는 용 머리 모양의 화산암 바위다. 오랜 세월 파도에 깎여 생긴 모양으로, 제주공항에서 가까워 많이 찾는다.", english: "A volcanic rock on the Jeju City shore shaped like a dragon’s head. It was carved by waves over a long time and is easy to visit from the airport."),
        .init(id: "kr.seoul_museum_art", ko: "서울 도심 덕수궁 옆에 있는 시립 미술관이다. 옛 대법원 건물의 정면을 살려 쓰고 있으며, 현대 미술 전시가 열린다.", english: "A municipal art museum next to Deoksugung Palace in central Seoul. It reuses the facade of the former Supreme Court building and hosts contemporary art exhibitions."),
        .init(id: "kr.sejong_center", ko: "광화문광장 가까이에 있는 서울의 대표적인 공연장이다. 대극장에서 음악, 무용, 연극 등 여러 공연이 열린다.", english: "A leading performing arts venue near Gwanghwamun Square in Seoul. Its grand theater stages concerts, dance and plays."),
        .init(id: "kr.seoul_city_hall", ko: "서울 중구에 있는 서울시의 청사다. 옛 청사와 유리 곡면의 새 청사가 나란히 서 있고, 앞에는 서울광장이 펼쳐진다.", english: "The seat of the Seoul city government in Jung-gu. The old building and a newer glass-curved one stand side by side, facing Seoul Plaza."),
        .init(id: "kr.myeongdong", ko: "서울 중구의 대표 번화가로 상점과 노점, 음식점이 빼곡하다. 명동성당이 있고 국내외 방문객이 많이 찾는다.", english: "A busy shopping district in Seoul’s Jung-gu packed with stores, street stalls and restaurants. Myeongdong Cathedral stands here, and many local and foreign visitors come."),
        .init(id: "kr.namsangol", ko: "남산 기슭에 조선 시대 한옥 몇 채를 옮겨 놓은 전통 마을이다. 한옥과 정자, 연못이 있는 정원을 거닐 수 있다.", english: "A traditional village at the foot of Namsan where several Joseon-era hanok houses were relocated. Visitors can stroll the gardens with pavilions and a pond."),
        .init(id: "kr.national_theater", ko: "남산 자락에 있는 국가 공연장이다. 해오름극장 등 여러 극장에서 연극, 오페라, 전통 공연이 열린다.", english: "A national performing arts venue on the slope of Namsan. Several theaters, including Haeoreum Theater, present plays, opera and traditional performances."),
        .init(id: "kr.seoullo", ko: "서울역 앞의 옛 고가도로를 보행길로 바꾼 공중 산책로다. 길 위에 화분과 나무를 심어 도심 속 정원처럼 꾸몄다.", english: "An elevated walkway made from the old overpass in front of Seoul Station. Planters and trees line the path like a garden above the city."),
        .init(id: "kr.sewoon", ko: "서울 종로와 을지로 사이에 길게 이어진 전자·기계 상가 건물이다. 부품과 공구를 파는 가게가 모여 있고 주변 골목이 이어진다.", english: "A long commercial complex between Jongno and Euljiro in Seoul, home to electronics and machinery shops. Stores selling parts and tools fill the building and nearby alleys."),
        .init(id: "kr.jogyesa", ko: "서울 종로에 있는 대한불교조계종의 중심 사찰이다. 도심 한가운데 있어 접근하기 쉽고, 큰 대웅전과 오래된 나무가 눈에 띈다.", english: "The head temple of the Jogye Order of Korean Buddhism, in Jongno, Seoul. Set in the middle of the city, it features a large main hall and old trees."),
        .init(id: "kr.gilsangsa", ko: "서울 성북동 골짜기에 있는 사찰이다. 옛 고급 요정 터를 절로 바꾼 곳으로, 조용한 숲길과 정원이 있다.", english: "A temple in the Seongbuk-dong valley of Seoul. It was converted from a former restaurant estate and offers quiet wooded paths and gardens."),
        .init(id: "kr.hwagyesa", ko: "서울 북한산 자락 강북구에 있는 비구니 사찰이다. 숲속 길을 따라 오르며, 외국인 수행자가 머무는 곳으로도 알려져 있다.", english: "A temple for Buddhist nuns on the slopes of Bukhansan in Gangbuk-gu, Seoul. It sits along a forest path and is also known for hosting foreign practitioners."),
        .init(id: "kr.munmyo", ko: "서울 종로구 성균관대 옆에 있는 유교 사당으로, 공자와 여러 성현의 위패를 모신다. 조선 시대 성균관의 일부로 지금도 제례가 이어진다.", english: "A Confucian shrine beside Sungkyunkwan University in Jongno-gu that enshrines tablets of Confucius and other sages. It was part of the Joseon-era Sungkyunkwan, and rites are still held."),
        .init(id: "kr.marronnier", ko: "서울 대학로에 있는 작은 공원이다. 마로니에 나무가 서 있고 소극장과 공연장이 많은 거리의 중심 쉼터 역할을 한다.", english: "A small park on Daehangno in Seoul, named after its horse chestnut trees. It serves as a resting place at the heart of a street full of small theaters."),
        .init(id: "kr.tongin_market", ko: "서울 종로구 서촌에 있는 오래된 전통시장이다. 엽전을 바꿔 반찬과 음식을 사는 도시락 카페가 알려져 있다.", english: "An old traditional market in Seochon, Jongno-gu, Seoul. It is known for a lunchbox cafe where visitors swap coins for side dishes and food."),
        .init(id: "kr.gyeongdong_market", ko: "서울 동대문구 제기동에 있는 대형 전통시장이다. 한약재와 건어물, 채소와 과일 등을 파는 상점이 많다.", english: "A large traditional market in Jegi-dong, Dongdaemun-gu, Seoul. Many stalls sell herbal medicine ingredients, dried seafood, vegetables and fruit."),
        .init(id: "kr.mangwon_market", ko: "서울 마포구 망원동의 동네 전통시장이다. 먹거리와 생활용품 가게가 모여 있고 주변에 한강과 아기자기한 골목이 있다.", english: "A neighborhood traditional market in Mangwon-dong, Mapo-gu, Seoul. Food and household stores fill it, and the Han River and cozy alleys lie nearby."),
        .init(id: "kr.noryangjin", ko: "서울 동작구 한강변에 있는 대표적인 수산시장이다. 신선한 생선과 해산물을 사서 식당에서 바로 먹을 수 있다.", english: "A major fish market on the Han River in Dongjak-gu, Seoul. Visitors can buy fresh fish and seafood and have it prepared at nearby restaurants."),
        .init(id: "kr.yeouido_park2", ko: "서울 여의도의 중심에 있는 도심 공원이다. 잔디밭과 숲, 연못이 있어 직장인과 시민이 산책하고 쉬어 간다.", english: "An urban park in the center of Yeouido, Seoul. Lawns, woods and a pond make it a place for office workers and residents to walk and rest."),
        .init(id: "kr.nodeul", ko: "한강 가운데 한강대교 아래에 있는 인공 섬이다. 공연장과 공원이 있어 강 위에서 서울 풍경을 즐길 수 있다.", english: "A man-made island in the middle of the Han River beneath Hangang Bridge. A performance venue and park offer views of Seoul from the water."),
        .init(id: "kr.national_cemetery", ko: "서울 동작구에 있는 국립묘지로, 나라를 위해 희생한 분들이 잠들어 있다. 현충탑과 넓은 묘역이 관악산 자락에 이어진다.", english: "A national cemetery in Dongjak-gu, Seoul, where those who sacrificed for the country are laid to rest. The memorial tower and broad graves extend along the foot of Gwanaksan."),
        .init(id: "kr.hangeul_museum", ko: "서울 용산구 국립중앙박물관 옆에 있는 박물관이다. 한글의 만들어진 과정과 역사를 전시로 소개한다.", english: "A museum in Yongsan-gu, Seoul, next to the National Museum of Korea. Its exhibits introduce how the Korean alphabet was created and its history."),
        .init(id: "kr.yongsan_family", ko: "서울 용산구 국립중앙박물관 곁에 있는 도심 공원이다. 넓은 잔디밭과 연못, 산책로가 있어 가족 나들이 장소로 쓰인다.", english: "An urban park beside the National Museum of Korea in Yongsan-gu, Seoul. Broad lawns, a pond and trails make it a place for family outings."),
        .init(id: "kr.mongchon", ko: "서울 송파구 올림픽공원 안에 있는 토성 유적이다. 백제 때 쌓은 성으로 알려져 있으며, 흙 언덕을 따라 걷는 산책로가 있다.", english: "An earthen fortress site inside Olympic Park in Songpa-gu, Seoul. Known as a Baekje-era fortification, it has a walking path along the earthen ramparts."),
        .init(id: "kr.jamsil_stadium", ko: "서울 송파구에 있는 대형 체육 시설 단지다. 주경기장, 야구장, 체육관이 모여 있어 경기와 공연이 열린다.", english: "A large sports complex in Songpa-gu, Seoul. The main stadium, baseball park and gymnasium stand together and host matches and concerts."),
        .init(id: "kr.gocheok", ko: "서울 구로구에 있는 국내 첫 돔형 야구장이다. 지붕이 있어 날씨와 상관없이 경기를 볼 수 있고 프로야구 경기가 열린다.", english: "A domed baseball stadium in Guro-gu, Seoul, the first of its kind in Korea. Its roof lets games go on regardless of weather, and professional baseball is played here."),
        .init(id: "kr.botanic", ko: "서울 강서구 마곡에 있는 식물원과 공원이다. 유리 온실 안에서 열대와 지중해 식물을 볼 수 있고 호수 공원도 이어진다.", english: "A botanical garden and park in Magok, Gangseo-gu, Seoul. A glass greenhouse displays tropical and Mediterranean plants, and a lake park adjoins it."),
        .init(id: "kr.yangcheon_hyanggyo", ko: "서울 강서구 궁산 아래에 있는 조선 시대 향교다. 지방 교육과 제사를 맡던 곳으로, 명륜당과 대성전 같은 건물이 남아 있다.", english: "A Joseon-era local Confucian school below Gungsan in Gangseo-gu, Seoul. It handled local education and rites, and buildings such as Myeongnyundang and Daeseongjeon remain."),
        .init(id: "kr.mullae", ko: "서울 영등포구 문래동의 철공소 골목에 예술가들이 모여 만든 공간이다. 공장 사이에 작업실과 벽화, 카페가 섞여 있다.", english: "An area in the metalworking alleys of Mullae-dong, Yeongdeungpo-gu, Seoul, where artists gathered. Studios, murals and cafes mingle with working machine shops."),
        .init(id: "kr.hangdong", ko: "서울 구로구 항동의 옛 철길을 따라 이어지는 산책로다. 철길 옆으로 나무와 들판이 있어 조용히 걷기 좋다.", english: "A walking trail along the old railway in Hangdong, Guro-gu, Seoul. Trees and fields flank the track, making it a quiet place to stroll."),
        .init(id: "kr.taereung", ko: "서울 노원구에 있는 조선 시대 왕릉이다. 중종의 계비 문정왕후의 무덤이며, 유네스코 세계유산인 조선 왕릉에 속한다.", english: "A Joseon royal tomb in Nowon-gu, Seoul, the burial place of Queen Munjeong, consort of King Jungjong. It belongs to the Joseon royal tombs listed as a UNESCO World Heritage Site."),
        .init(id: "kr.uireung", ko: "서울 성북구 석관동에 있는 조선 시대 왕릉이다. 경종과 그 왕비를 모신 곳으로, 숲이 우거진 조용한 산책길로도 알려져 있다.", english: "A Joseon royal tomb in Seokgwan-dong, Seongbuk-gu, Seoul, where King Gyeongjong and his queen are buried. Its wooded grounds also make it a quiet place to walk."),
        .init(id: "kr.jeongneung", ko: "서울 성북구 북한산 자락에 있는 조선 시대 왕릉이다. 태조 이성계의 왕비 신덕왕후의 무덤이며 조선 왕릉에 속한다.", english: "A Joseon royal tomb at the foot of Bukhansan in Seongbuk-gu, Seoul. It is the tomb of Queen Sindeok, consort of King Taejo, and is part of the Joseon royal tombs."),
        .init(id: "kr.heoninneung", ko: "서울 서초구 내곡동에 있는 조선 시대 왕릉 두 곳이다. 태종과 순조의 무덤이 가까이 있으며 조선 왕릉에 속한다.", english: "Two Joseon royal tombs in Naegok-dong, Seocho-gu, Seoul, close together. They hold King Taejong and King Sunjo and belong to the Joseon royal tombs."),
        .init(id: "kr.snu", ko: "서울 관악구 관악산 아래에 있는 국립대학교다. 넓은 캠퍼스가 산자락을 따라 이어지고 정문 모양이 잘 알려져 있다.", english: "A national university at the foot of Gwanaksan in Gwanak-gu, Seoul. Its large campus spreads along the mountain slope, and its gate is widely recognized."),
        .init(id: "kr.yonsei", ko: "서울 서대문구 신촌에 있는 사립대학교다. 돌로 지은 오래된 건물과 숲길이 있는 캠퍼스로 알려져 있다.", english: "A private university in Sinchon, Seodaemun-gu, Seoul. Its campus is known for old stone buildings and wooded paths."),
        .init(id: "kr.ewha", ko: "서울 서대문구에 있는 여자대학교다. 땅 속으로 이어진 유리 계단형 캠퍼스 복합 건물이 이름나 있다.", english: "A women’s university in Seodaemun-gu, Seoul. Its campus center, a sunken glass-sided corridor of steps, is a notable landmark."),
        .init(id: "kr.korea_univ", ko: "서울 성북구 안암동에 있는 사립대학교다. 돌로 지은 본관과 넓은 잔디 광장이 캠퍼스 중심에 있다.", english: "A private university in Anam-dong, Seongbuk-gu, Seoul. A stone main hall and a wide lawn stand at the heart of the campus."),
        .init(id: "kr.bulamsan", ko: "서울 노원구와 경기 남양주 사이에 솟은 바위산이다. 정상 근처의 큰 바위가 눈에 띄고 서울 동북쪽 조망이 트인다.", english: "A rocky mountain between Nowon-gu in Seoul and Namyangju in Gyeonggi. Large boulders near the summit stand out, with open views over northeastern Seoul."),
        .init(id: "kr.suraksan", ko: "서울 노원구와 경기 의정부 경계에 있는 산이다. 암벽과 계곡이 있어 서울 북동부 시민이 많이 오른다.", english: "A mountain on the border of Nowon-gu in Seoul and Uijeongbu in Gyeonggi. Rock faces and valleys draw many hikers from northeastern Seoul."),
        .init(id: "kr.umyeonsan", ko: "서울 서초구에 있는 낮은 산이다. 산책로와 약수터가 있어 주민들이 가볍게 오르며 예술의전당과 가깝다.", english: "A low mountain in Seocho-gu, Seoul. Trails and a spring make it a light hike for locals, and the Seoul Arts Center lies nearby."),
        .init(id: "kr.cheonggyesan", ko: "서울 서초구와 경기 성남, 과천에 걸친 산이다. 정상 가까이 매봉이 있고 숲길과 계곡이 이어져 등산객이 많다.", english: "A mountain spanning Seocho-gu in Seoul and Seongnam and Gwacheon in Gyeonggi. Forest paths and valleys lead toward its peaks, attracting many hikers."),
        .init(id: "kr.ansan_seoul", ko: "서울 서대문구 안산을 둘러 이어지는 순환 산책길이다. 나무 데크와 숲길을 따라 걸으며 도심과 북한산을 바라볼 수 있다.", english: "A loop trail around Ansan in Seodaemun-gu, Seoul. Wooden decks and forest paths offer views of the city and Bukhansan."),
        .init(id: "kr.yangjae_forest", ko: "서울 서초구 양재천 가까이에 있는 도심 숲 공원이다. 나무가 울창하고 산책로가 이어지며 기념 시설과 체육 공간도 있다.", english: "An urban forest park near Yangjaecheon in Seocho-gu, Seoul. Dense trees and walking paths run through it alongside memorials and sports facilities."),
        .init(id: "kr.garosu", ko: "서울 강남구 신사동에 있는 은행나무 가로수 길이다. 양옆으로 카페와 상점, 음식점이 늘어서 있다.", english: "A ginkgo-lined street in Sinsa-dong, Gangnam-gu, Seoul. Cafes, boutiques and restaurants stand along both sides."),
        .init(id: "kr.dongbaekseom", ko: "부산 해운대 해수욕장 서쪽 끝에 있는 곶 형태의 섬이다. 동백나무 숲과 해안 산책로가 있고 누리마루 하우스가 가깝다.", english: "A cape-like island at the west end of Haeundae Beach in Busan. It has a camellia forest and a coastal walking path, with Nurimaru House close by."),
        .init(id: "kr.nurimaru", ko: "부산 동백섬에 있는 국제회의장 건물이다. 2005년 아시아태평양경제협력체 정상회의가 열렸고 바다를 바라보는 전망이 좋다.", english: "A conference hall on Dongbaekseom in Busan. It hosted the 2005 Asia-Pacific Economic Cooperation summit and offers views over the sea."),
        .init(id: "kr.bexco", ko: "부산 해운대구 센텀시티에 있는 전시컨벤션센터다. 대형 박람회와 국제 행사가 열리며 주변에 백화점과 영화 관련 시설이 있다.", english: "An exhibition and convention center in Centum City, Haeundae-gu, Busan. It hosts large fairs and international events, with department stores and film facilities nearby."),
        .init(id: "kr.songdo_beach", ko: "부산 서구에 있는 해수욕장으로 국내에서 처음 문을 연 곳으로 알려져 있다. 바다 위로 걸을 수 있는 구름산책로와 케이블카가 있다.", english: "A beach in Seo-gu, Busan, known as Korea’s first public beach. A sea-walk path over the water and a cable car are among its attractions."),
        .init(id: "kr.dadaepo", ko: "부산 사하구 낙동강 하구 근처에 있는 넓은 해수욕장이다. 모래가 완만하게 이어지고 해질 무렵 풍경과 분수 공연으로 알려져 있다.", english: "A broad beach in Saha-gu, Busan, near the mouth of the Nakdong River. Its gently sloping sand is known for sunset views and a fountain show."),
        .init(id: "kr.geumjeongsanseong", ko: "부산 금정산 능선을 따라 쌓은 조선 시대 산성이다. 국내에서 가장 긴 산성이라는 설명도 있으며 동문과 남문 같은 성문이 남아 있다.", english: "A Joseon-era mountain fortress built along the ridge of Geumjeongsan in Busan. Gates such as the East and South Gates remain along its walls."),
        .init(id: "kr.bosu_book", ko: "부산 중구 보수동에 있는 헌책방 골목이다. 한국전쟁 때 피란지에서 시작된 책방들이 모여 지금도 헌책을 사고판다.", english: "A street of used bookstores in Bosu-dong, Jung-gu, Busan. The shops began during the Korean War refugee era, and old books are still traded here."),
        .init(id: "kr.gukje_market", ko: "부산 중구에 있는 대표적인 전통시장이다. 한국전쟁 이후 피란민이 모여 시작되었고 의류와 잡화, 먹거리 가게가 가득하다.", english: "A major traditional market in Jung-gu, Busan. It grew from a refugee gathering after the Korean War and is filled with clothing, sundries and food stalls."),
        .init(id: "kr.un_cemetery", ko: "부산 남구에 있는 유엔군 전사자 묘지다. 한국전쟁에서 목숨을 잃은 여러 나라 군인들이 잠들어 있으며 잘 가꿔진 잔디 묘역이 이어진다.", english: "A United Nations cemetery in Nam-gu, Busan. Soldiers from many countries who died in the Korean War are buried here in carefully kept grounds."),
        .init(id: "kr.citizens_park", ko: "부산 부산진구에 있는 큰 도심 공원이다. 옛 미군 기지 터를 공원으로 바꾸었고 잔디 광장과 산책로, 연못이 있다.", english: "A large urban park in Busanjin-gu, Busan. It was converted from a former US military camp site and has lawns, trails and a pond."),
        .init(id: "kr.huinnyeoul", ko: "부산 영도구 바닷가 절벽 위에 있는 마을이다. 좁은 골목과 벽화, 바다가 보이는 카페가 있는 문화마을로 가꾸어졌다.", english: "A hillside village on a seaside cliff in Yeongdo-gu, Busan. Narrow alleys, murals and sea-view cafes make it a cultural village."),
        .init(id: "kr.yeongdo_bridge", ko: "부산 중구와 영도구를 잇는 다리다. 배가 지나갈 때 상판을 들어 올리는 도개교로 알려져 있으며 지금은 정해진 시간에 올린다.", english: "A bridge linking Jung-gu and Yeongdo-gu in Busan. It is a drawbridge whose deck is raised to let ships pass, and it is lifted at scheduled times today."),
        .init(id: "kr.geunday", ko: "대구 중구 도심에 있는 근대 건물과 골목을 따라 걷는 길이다. 옛 교회와 병원, 집이 남은 곳을 둘러볼 수 있다.", english: "A walking route through old modern-era buildings and alleys in central Daegu. Visitors pass former churches, hospitals and houses that still stand."),
        .init(id: "kr.gyesan_cathedral", ko: "대구 중구에 있는 천주교 성당으로 1900년대 초에 지은 고딕 양식 건물이다. 붉은 벽돌의 두 첨탑이 인상적이며 사적으로 지정되어 있다.", english: "A Catholic cathedral in Jung-gu, Daegu, a Gothic-style building from the early 1900s. Its two red-brick spires are striking, and it is a designated historic site."),
        .init(id: "kr.yangnyeong", ko: "대구 중구에 있는 한약재 시장 거리다. 조선 시대부터 이어진 약령시의 전통이 있어 한약재와 건강 관련 가게가 모여 있다.", english: "A herbal medicine market district in Jung-gu, Daegu. It carries on a tradition dating to the Joseon period, with shops selling herbs and health products."),
        .init(id: "kr.dalseong_park", ko: "대구 중구에 있는 공원으로 옛 달성 토성 터에 조성되었다. 동물원과 산책로가 있고 도심 속 쉼터로 쓰인다.", english: "A park in Jung-gu, Daegu, built on the site of the old Dalseong earthen fortress. It has a zoo and walking paths and serves as a city retreat."),
        .init(id: "kr.dgb_park", ko: "대구 수성구에 있는 대형 종합 경기장이다. 축구 경기와 공연 등이 열리며 2002년 월드컵 경기장으로 지어졌다.", english: "A large sports stadium in Suseong-gu, Daegu. It hosts football matches and concerts and was built as a venue for the 2002 World Cup."),
        .init(id: "kr.lions_park", ko: "대구 수성구에 있는 프로야구 구장이다. 삼성 라이온즈의 홈구장으로 2016년에 문을 열었다.", english: "A professional baseball park in Suseong-gu, Daegu. It is the home of the Samsung Lions and opened in 2016."),
        .init(id: "kr.biseulsan", ko: "대구 달성군에 있는 산이다. 봄철 정상 부근에 진달래가 군락을 이루고 큰 바위 지대인 돌무더기 길이 알려져 있다.", english: "A mountain in Dalseong County, Daegu. Azaleas bloom in masses near the summit in spring, and a field of large boulders is a known feature."),
        .init(id: "kr.dodong_seowon", ko: "대구 달성군에 있는 조선 시대 서원이다. 김굉필을 기리기 위해 세워졌으며 유네스코 세계유산인 한국의 서원에 속한다.", english: "A Joseon-era Confucian academy in Dalseong County, Daegu. It was founded to honor Kim Gwangpil and is part of the Seowon of Korea, a UNESCO World Heritage Site."),
        .init(id: "kr.gatbawi", ko: "대구 팔공산 관봉에 있는 석조여래좌상이다. 머리 위에 갓 모양의 넓적한 돌을 얹은 모습으로, 많은 이가 소원을 빌러 찾아온다.", english: "A seated stone Buddha on Gwanbong peak of Palgongsan in Daegu. A flat hat-shaped stone sits on its head, and many people come to make wishes."),
        .init(id: "kr.gaehang", ko: "인천 중구에 있는 개항 이후의 근대 건축이 모인 구역이다. 옛 은행과 일본식 건물, 차이나타운이 가까이 있다.", english: "A district in Jung-gu, Incheon where modern buildings from the port-opening era gather. Former banks, Japanese-style buildings and Chinatown lie close by."),
        .init(id: "kr.jayu_park", ko: "인천 중구의 언덕에 있는 공원으로 우리나라 최초의 서구식 공원으로 알려져 있다. 맥아더 장군 동상과 인천항 조망이 있다.", english: "A hilltop park in Jung-gu, Incheon, known as Korea’s first Western-style park. It has a statue of General MacArthur and views of Incheon Port."),
        .init(id: "kr.sinpo", ko: "인천 중구 신포동에 있는 전통시장이다. 닭강정과 쫄면, 만두 같은 먹거리로 알려져 있고 개항장과 가깝다.", english: "A traditional market in Sinpo-dong, Jung-gu, Incheon. It is known for fried chicken, spicy cold noodles and dumplings, and lies close to the old open port."),
        .init(id: "kr.baedari", ko: "인천 동구에 있는 옛 헌책방 거리다. 좁은 골목에 책방과 작은 공방이 남아 있는 동네로 오래된 정취가 있다.", english: "A street of old used bookstores in Dong-gu, Incheon. Bookshops and small workshops remain in its narrow alleys, giving the neighborhood a nostalgic feel."),
        .init(id: "kr.soraepogu", ko: "인천 남동구에 있는 어촌 포구다. 새우젓과 활어를 파는 어시장이 있고 좁은 협궤 철도의 흔적과 소래철교가 남아 있다.", english: "A fishing port in Namdong-gu, Incheon. It has a fish market selling salted shrimp and live fish, and the old narrow-gauge railway bridge remains."),
        .init(id: "kr.songdo_tribowl", ko: "인천 송도국제도시에 있는 접시 모양의 복합 건물이다. 공연장과 전시 공간이 있고 인공 수로를 낀 센트럴파크 가까이에 있다.", english: "A bowl-shaped complex in Songdo International City, Incheon. It houses performance and exhibition spaces and stands near Central Park and its canal."),
        .init(id: "kr.airport", ko: "인천 영종도에 있는 한국의 대표적인 국제공항이다. 서울과 수도권으로 오가는 많은 국제선과 환승 노선이 이 공항을 거친다.", english: "South Korea’s main international airport, on Yeongjongdo island in Incheon. Many international and transit flights serving Seoul and the capital region pass through it."),
        .init(id: "kr.ganghwa_sanseong", ko: "인천 강화도에 있는 옛 산성이다. 고려와 조선 시대 도읍 방어와 관련된 성벽으로 동문, 서문, 남문, 북문이 남아 있다.", english: "An old fortress on Ganghwado island in Incheon. Its walls served capital defense in the Goryeo and Joseon periods, and the east, west, south and north gates remain."),
        .init(id: "kr.baengnyeongdo", ko: "인천에서 배로 가는 서해 최북단의 큰 섬이다. 사곶해변과 두무진의 기암괴석이 알려져 있으며 군사적으로 중요한 지역이다.", english: "A large island at the northern edge of the Yellow Sea, reached by ferry from Incheon. It is known for Sagot Beach and the rock formations of Dumujin."),
        .init(id: "kr.muuido", ko: "인천 영종도 옆에 있는 섬으로 다리가 놓여 차로 갈 수 있다. 호룡곡산과 해변이 있어 등산과 바다 구경을 함께 즐긴다.", english: "An island beside Yeongjongdo in Incheon, now reachable by car over a bridge. Hiking on Horyonggoksan and walks along the beach are popular."),
        .init(id: "kr.ppura", ko: "광주 남구 양림동에 있는 오래된 동네다. 낡은 집과 골목에 설치된 조형물이 이어져 있어 골목 구경이 주된 재미다.", english: "An old neighborhood in Yangnim-dong, Nam-gu, Gwangju. Worn houses and installations along the alleys make wandering the lanes the main attraction."),
        .init(id: "kr.gwangju_stadium", ko: "광주 북구에 있는 프로야구 구장이다. KIA 타이거즈의 홈구장으로 2014년에 문을 열었다.", english: "A professional baseball park in Buk-gu, Gwangju. It is the home of the KIA Tigers and opened in 2014."),
        .init(id: "kr.gwangju_art", ko: "광주 북구 비엔날레 가까이에 있는 시립 미술관이다. 현대 미술과 지역 작가의 작품을 전시한다.", english: "A municipal art museum in Buk-gu, Gwangju, close to the Biennale venue. It shows contemporary art and works by regional artists."),
        .init(id: "kr.biennale", ko: "광주 북구에 있는 현대 미술 전시장이다. 격년으로 열리는 국제 미술 행사의 중심 공간으로 쓰인다.", english: "A contemporary art exhibition hall in Buk-gu, Gwangju. It serves as the main venue for the city’s international art biennale held every two years."),
        .init(id: "kr.jeungsimsa", ko: "광주 무등산 기슭에 있는 사찰이다. 통일신라 때 창건된 것으로 전해지며 계곡을 따라 오르는 숲길이 이어진다.", english: "A temple at the foot of Mudeungsan in Gwangju. It is said to date to the Unified Silla period and sits along a forest path beside a valley."),
        .init(id: "kr.pungam", ko: "광주 서구 풍암지구에 있는 호수 공원이다. 호수를 한 바퀴 도는 산책로가 있어 주민들이 걷고 쉬는 곳이다.", english: "A lake park in the Pungam district of Seo-gu, Gwangju. A trail circles the lake, where residents walk and relax."),
        .init(id: "kr.gwangsan", ko: "광주 광산구에 있는 철도역이다. 고속철도가 서는 광주의 주요 관문으로 공항과 가까워 이동이 편하다.", english: "A railway station in Gwangsan-gu, Gwangju. It is a major gateway served by high-speed trains and is close to the airport."),
        .init(id: "kr.daein_market", ko: "광주 동구 광주천 근처에 있는 전통시장이다. 예술가들이 참여한 야시장과 먹거리로 알려져 있다.", english: "A traditional market in Dong-gu, Gwangju, near the Gwangju Stream. It is known for its night market and food stalls involving local artists."),
        .init(id: "kr.kaist", ko: "대전 유성구에 있는 과학기술 특성화 대학이다. 연구 단지와 가까운 넓은 캠퍼스에 실험실과 연구동이 모여 있다.", english: "A science and technology university in Yuseong-gu, Daejeon. Its large campus, near the research complex, holds labs and research buildings."),
        .init(id: "kr.science_museum", ko: "대전 유성구에 있는 과학관이다. 자연사, 첨단 과학 전시와 천체관이 있어 체험하며 배울 수 있다.", english: "A science museum in Yuseong-gu, Daejeon. Natural history and advanced science exhibits plus a planetarium let visitors learn hands-on."),
        .init(id: "kr.hanwha_park", ko: "대전 중구에 있는 프로야구 구장이다. 한화 이글스의 홈구장으로 2025년에 새로 문을 열었다.", english: "A professional baseball park in Jung-gu, Daejeon. It is the home of the Hanwha Eagles and opened as a new stadium in 2025."),
        .init(id: "kr.oworld", ko: "대전 중구 보문산 자락에 있는 놀이공원과 동물원이다. 놀이 기구와 동물원, 식물원이 한 곳에 모여 있다.", english: "An amusement park and zoo at the foot of Bomunsan in Jung-gu, Daejeon. Rides, a zoo and a botanical garden are gathered in one place."),
        .init(id: "kr.sikjangsan", ko: "대전 동구와 충북 옥천 사이에 있는 산이다. 능선을 따라 걸으며 대전 시내와 대청호를 내려다볼 수 있다.", english: "A mountain between Dong-gu in Daejeon and Okcheon in North Chungcheong. Ridge trails overlook the Daejeon cityscape and Daecheongho Lake."),
        .init(id: "kr.jangtaesan", ko: "대전 서구에 있는 산으로 자연휴양림이 있다. 메타세쿼이아 숲길과 나무 전망대가 알려져 있다.", english: "A mountain in Seo-gu, Daejeon, with a natural recreation forest. A metasequoia forest path and wooden observation tower are well known."),
        .init(id: "kr.daejeon_station", ko: "대전 동구에 있는 대표 철도역이다. 경부선과 호남선이 만나는 교통의 중심으로 고속철도와 일반 열차가 오간다.", english: "The main railway station in Dong-gu, Daejeon. It is a transport hub where the Gyeongbu and Honam lines meet, served by high-speed and regular trains."),
        .init(id: "kr.euneungjeongi", ko: "대전 중구 도심에 있는 번화가 거리다. 음식점과 상점이 모여 있고 밤에는 큰 디지털 조명이 켜져 활기를 띤다.", english: "A busy street in downtown Jung-gu, Daejeon. Restaurants and shops gather here, and large digital lighting brightens it at night."),
        .init(id: "kr.ulsan_tower", ko: "울산 동구와 남구를 잇는 현수교로 울산항 위를 지난다. 두 개의 높은 탑이 케이블을 지탱하는 모습이 도시의 상징처럼 보인다.", english: "A suspension bridge linking Dong-gu and Nam-gu in Ulsan that crosses Ulsan Port. Its two tall towers holding the cables have become a symbol of the city."),
        .init(id: "kr.ulsan_grand_park", ko: "울산 남구에 있는 넓은 도시 공원이다. 장미원과 호수, 동물원, 산책로가 있어 시민들이 많이 찾는다.", english: "A large city park in Nam-gu, Ulsan. A rose garden, lake, zoo and trails draw many residents."),
        .init(id: "kr.ulsan_munsu", ko: "울산 남구에 있는 축구 경기장이다. 2002년 월드컵 때 지었으며 프로축구 울산 HD의 홈구장으로 쓰인다.", english: "A football stadium in Nam-gu, Ulsan. It was built for the 2002 World Cup and is the home ground of the professional club Ulsan HD."),
        .init(id: "kr.ilsan_beach", ko: "울산 동구에 있는 해수욕장이다. 곡선으로 이어진 모래밭이 있고 가까이에 대왕암공원이 있다.", english: "A beach in Dong-gu, Ulsan, with a curving stretch of sand. Daewangam Park lies close by."),
        .init(id: "kr.jinha", ko: "울산 울주군 동해안에 있는 해수욕장이다. 완만한 백사장과 맑은 바다 덕분에 여름 휴양지로 찾는 이가 많고 근처에 횟집이 이어진다.", english: "A beach on the East Sea coast in Ulju County, Ulsan. Its gently sloping sand and clear water make it a popular summer spot, with seafood restaurants nearby."),
        .init(id: "kr.seoksan", ko: "울산 울주군 가지산 자락에 자리한 비구니 사찰이다. 신라 시대에 창건된 것으로 전해지며 울창한 숲길과 계곡이 어우러진다.", english: "A temple in the foothills of Mt. Gaji in Ulju County, Ulsan, traditionally said to date from the Silla period. It is known for its wooded paths and valley stream."),
        .init(id: "kr.ganwolsan", ko: "울산 울주군과 경북 경주시에 걸친 영남알프스의 산이다. 정상 일대에 억새 평원이 펼쳐져 가을 산행지로 알려져 있다.", english: "A mountain in the Yeongnam Alps on the border of Ulju County and Gyeongju. Silver grass meadows near the summit make it a favored autumn hike."),
        .init(id: "kr.sejong_city_hall", ko: "세종특별자치시의 행정을 맡는 시청 청사다. 행정중심복합도시로 조성된 신도시의 중심부에 있다.", english: "The administrative office of Sejong Special Self-Governing City. It stands in the center of the planned administrative capital district."),
        .init(id: "kr.joseongsan", ko: "세종시 조치원읍에 있는 철도역이다. 경부선이 지나는 역으로 세종 북부의 관문 구실을 한다.", english: "A railway station in Jochiwon, Sejong, on the Gyeongbu Line. It serves as a northern gateway to the city."),
        .init(id: "kr.beopgyesa", ko: "세종시 전의면 비암산 자락에 있는 사찰이다. 삼국 시대 불상과 비석이 전해지는 오래된 절로 알려져 있다.", english: "A temple on the slopes of Mt. Biam in Jeonui, Sejong. It is an old temple known for ancient Buddhist stone carvings and monuments."),
        .init(id: "kr.wonsusan", ko: "세종시에 있는 산으로 도심 가까이에서 오를 수 있다. 능선을 따라 걷는 산책로가 이어져 주민들이 즐겨 찾는다.", english: "A mountain in Sejong that can be climbed close to the city. Trails run along its ridge and are popular with local walkers."),
        .init(id: "kr.jeonwolsan", ko: "세종시 금강 가까이에 솟은 낮은 산이다. 정상에서 강과 주변 도시 풍경을 내려다볼 수 있다.", english: "A low mountain rising near the Geum River in Sejong. The summit gives views of the river and the surrounding city."),
        .init(id: "kr.bears_garden", ko: "세종시 전동면에 있는 수목원 겸 곰 사육 공원이다. 정원과 야생화 산책로를 걸으며 곰을 가까이서 볼 수 있다.", english: "A garden and bear park in Jeondong, Sejong. Visitors stroll through landscaped gardens and wildflower paths and can watch the bears up close."),
        .init(id: "kr.paldalmun", ko: "수원화성 남쪽에 있는 성문이다. 조선 정조 때 쌓은 성곽의 일부로 위에 문루와 옹성이 있다.", english: "The southern gate of Suwon Hwaseong Fortress, built in the Joseon era under King Jeongjo. A gate tower stands on top and a half-moon barbican protects the front."),
        .init(id: "kr.haenggung", ko: "수원 화성 안에 있는 조선 시대 임금의 임시 궁궐이다. 정조가 아버지 사도세자의 묘를 참배하러 올 때 머문 곳이다.", english: "A temporary royal palace inside Hwaseong Fortress in Suwon from the Joseon dynasty. King Jeongjo stayed here when visiting his father Crown Prince Sado's tomb."),
        .init(id: "kr.yangju_ilyeongsa", ko: "경기 양주 천보산 아래에 있는 고려와 조선 시기 큰 절터다. 넓은 터에 건물 기단과 석물이 남아 있다.", english: "The site of a large temple from the Goryeo and Joseon periods below Mt. Cheonbo in Yangju. Building foundations and stone relics remain across the wide grounds."),
        .init(id: "kr.sooyangsa", ko: "경기 남양주 운길산 중턱에 있는 사찰이다. 두물머리가 내려다보이는 전망으로 유명하며 오래된 은행나무와 찻집이 있다.", english: "A temple on the slope of Mt. Ungil in Namyangju. It is known for its view of the Dumulmeori river confluence, an old ginkgo tree, and a tea house."),
        .init(id: "kr.silleuksa", ko: "경기 여주 남한강가에 있는 천년 고찰이다. 강변 바위 위에 세워진 벽돌탑 다층전탑이 대표 볼거리다.", english: "An ancient temple on the Namhan River in Yeoju. Its brick pagoda standing on a riverside rock is its most recognized feature."),
        .init(id: "kr.sejong_tomb", ko: "경기 여주에 있는 조선 세종대왕과 소헌왕후의 합장릉이다. 유네스코 세계유산인 조선왕릉에 속하며 옆에 효종의 능이 있다.", english: "The joint tomb of King Sejong and Queen Soheon of Joseon in Yeoju. It is part of the Joseon Royal Tombs World Heritage site, and King Hyojong's tomb lies nearby."),
        .init(id: "kr.donggureung", ko: "경기 구리에 있는 조선 왕실의 능역이다. 태조의 건원릉을 비롯해 여러 왕과 왕비의 능이 모여 있고 세계유산에 속한다.", english: "A Joseon royal tomb cluster in Guri that includes the tomb of founder King Taejo and several other kings and queens. It is part of the World Heritage Joseon Royal Tombs."),
        .init(id: "kr.seolleung_paju", ko: "경기 파주에 조성된 출판 단지다. 출판사와 인쇄소, 서점과 갤러리가 모여 있어 책과 건축을 함께 즐길 수 있다.", english: "A publishing district in Paju made up of publishers, printers, bookstores and galleries. It is a place to enjoy books alongside distinctive architecture."),
        .init(id: "kr.odusan", ko: "경기 파주 임진강과 한강이 만나는 오두산에 세운 전망대다. 강 건너 북녘 땅을 볼 수 있는 안보 관광지다.", english: "An observatory on Mt. Odu in Paju, where the Imjin and Han rivers meet. It offers views across the river into North Korea and is a security-themed tourist site."),
        .init(id: "kr.ansan_daebudo", ko: "경기 안산 서해 바다에 있는 섬으로 시화방조제로 육지와 이어진다. 갯벌과 포도밭, 해안 드라이브 길이 알려져 있다.", english: "An island off Ansan in the Yellow Sea, linked to the mainland by the Sihwa seawall. It is known for tidal flats, vineyards and coastal drives."),
        .init(id: "kr.jebudo", ko: "경기 화성 앞바다의 작은 섬이다. 하루 두 번 바닷길이 열려 걸어서 건널 수 있는 것으로 알려져 있다.", english: "A small island off Hwaseong. A seabed road opens at low tide twice a day so that visitors can cross on foot or by car."),
        .init(id: "kr.icheon_cerapia", ko: "경기 이천 사기막골에 도자기 공방이 모인 마을이다. 도예 체험과 작품 구경을 할 수 있고 이천은 예로부터 도자기로 알려진 고장이다.", english: "A village in Icheon where pottery studios cluster. Visitors can try ceramics workshops and browse works in a town long known for its pottery."),
        .init(id: "kr.gapyeong_jaraseom", ko: "경기 가평 북한강 가운데에 있는 섬이다. 캠핑장과 꽃밭이 있고 가을에는 재즈 축제가 열리는 곳으로 알려져 있다.", english: "An island in the middle of the Bukhan River in Gapyeong. It has campgrounds and flower fields and is known for a jazz festival held in autumn."),
        .init(id: "kr.morning_calm", ko: "경기 가평 축령산 자락에 있는 수목원이다. 계절마다 다른 정원과 한국식 정원이 있고 겨울 불빛 축제로도 알려져 있다.", english: "A garden on the slope of Mt. Chukryeong in Gapyeong. It has seasonal gardens and Korean-style landscapes, and is also known for its winter light festival."),
        .init(id: "kr.petite_france", ko: "경기 가평에 있는 프랑스 마을 풍의 테마 공간이다. 알록달록한 유럽식 건물과 전시관, 소품 가게가 모여 있다.", english: "A French village themed attraction in Gapyeong. It has colorful European-style buildings, exhibition halls and small shops."),
        .init(id: "kr.seoul_land", ko: "경기 과천 서울대공원 안에 있는 놀이공원이다. 청계산 자락에 놀이기구와 퍼레이드, 계절 행사가 있다.", english: "An amusement park in Gwacheon at the foot of Mt. Cheonggye. It offers rides, parades and seasonal events."),
        .init(id: "kr.pyeongtaek_port", ko: "경기 평택과 충남 아산 사이에 있는 인공 호수다. 호숫가 공원과 산책로, 일몰 풍경으로 알려져 있다.", english: "An artificial lake between Pyeongtaek and Asan. It is known for lakeside parks, walking paths and sunset views."),
        .init(id: "kr.ansungmachum", ko: "경기 안성에 있는 체험형 공원이다. 안성의 전통 유기 같은 맞춤 공예 문화를 소개하고 천문대와 놀이 시설이 있다.", english: "A theme park in Anseong that introduces the local tradition of made-to-order craftsmanship. It also has an observatory and play facilities."),
        .init(id: "kr.chuncheon_soyang", ko: "강원 춘천 소양강을 막아 쌓은 다목적 댐이다. 국내에서 규모가 큰 사력댐 가운데 하나이며 위에서 소양호를 내려다볼 수 있다.", english: "A multipurpose dam on the Soyang River in Chuncheon. It is one of Korea's large rock-fill dams and overlooks Lake Soyang."),
        .init(id: "kr.chuncheon_skywalk", ko: "강원 춘천 소양강 위에 놓인 유리 바닥 보행로다. 강 위로 걸어 들어가며 물과 주변 산 풍경을 즐긴다.", english: "A glass-floored walkway over the Soyang River in Chuncheon. Visitors walk out over the water and enjoy views of the river and surrounding hills."),
        .init(id: "kr.gangchon", ko: "강원 춘천 북한강변에 있는 휴양지다. 레일바이크와 래프팅, 카페 거리로 이름난 곳이다.", english: "A riverside resort area on the Bukhan River in Chuncheon. It is known for rail bikes, rafting and cafe streets."),
        .init(id: "kr.sokcho_jungang", ko: "강원 속초 중앙동에 있는 전통 시장이다. 닭강정과 오징어순대, 건어물 등 먹거리와 해산물로 알려져 있다.", english: "A traditional market in central Sokcho. It is known for fried chicken, stuffed squid sausage, dried seafood and fresh fish."),
        .init(id: "kr.abai", ko: "강원 속초 청초호 가에 있는 실향민 마을이다. 한국전쟁 때 함경도에서 내려온 이들이 정착한 곳으로 가자미식해와 갯배로 알려져 있다.", english: "A village by Cheongcho Lake in Sokcho settled by refugees from the north during the Korean War. It is known for its fermented flatfish dish and the hand-pulled ferry."),
        .init(id: "kr.yeongnangho", ko: "강원 속초 바닷가에 있는 자연 석호다. 호수 둘레를 도는 산책로가 있고 설악산이 멀리 보인다.", english: "A natural lagoon by the sea in Sokcho. A walking path circles the lake and Seoraksan can be seen in the distance."),
        .init(id: "kr.samcheok_cave", ko: "강원 삼척 대이리 동굴지대에 있는 석회 동굴이다. 천연기념물로 지정되었고 넓은 동굴 안에 종유석과 폭포가 있다.", english: "A limestone cave in the Daei-ri cave area of Samcheok, designated as a natural monument. Its large chambers hold stalactites and an underground waterfall."),
        .init(id: "kr.samcheok_rail", ko: "강원 삼척 동해안 옛 철길을 따라 달리는 레일바이크다. 바다와 절벽 풍경을 보며 페달을 밟을 수 있다.", english: "A rail bike ride along an old coastal railway in Samcheok. Riders pedal past sea and cliff scenery."),
        .init(id: "kr.taebaeksan", ko: "강원 태백에 있는 높은 산으로 한강과 낙동강의 발원지가 가까운 산이다. 겨울 눈꽃 산행과 천제단으로 알려져 있다.", english: "A high mountain in Taebaek near the sources of the Han and Nakdong rivers. It is known for winter snow-flower hikes and a summit altar."),
        .init(id: "kr.jeongseon", ko: "강원 정선에서 닷새마다 열리는 전통 시장이다. 곤드레밥과 메밀전병 같은 산골 음식과 나물을 맛볼 수 있다.", english: "A traditional market held every five days in Jeongseon. Visitors can taste mountain foods such as gondre rice and buckwheat crepes."),
        .init(id: "kr.hwajinpo", ko: "강원 고성 동해안에 있는 석호와 해변이다. 호수와 바다 사이에 소나무 숲이 있고 옛 별장들이 남아 있다.", english: "A lagoon and beach on the East Sea coast in Goseong. Pine forests lie between the lake and sea, and old historic villas remain."),
        .init(id: "kr.yanggu_punch", ko: "강원 양구에 있는 분지로 화채 그릇처럼 움푹 패어 펀치볼이라 불린다. 한국전쟁의 격전지였고 지금은 평화 전망 시설과 농촌 풍경으로 알려져 있다.", english: "A bowl-shaped basin in Yanggu, also known as the Punchbowl. It was the site of fierce fighting in the Korean War and is now known for its farmland and peace observation sites."),
        .init(id: "kr.danyang_mancheonha", ko: "충북 단양 남한강 위 산 정상에 설치한 전망대다. 유리 바닥과 구름다리에서 남한강과 단양 시내를 내려다본다.", english: "A skywalk on a hilltop above the Namhan River in Danyang. Glass floors and a suspension walkway give views of the river and the town."),
        .init(id: "kr.guinsa", ko: "충북 단양 소백산 자락에 있는 천태종 총본산이다. 산비탈을 따라 큰 전각이 층층이 놓여 있다.", english: "The head temple of the Cheontae Order, on the slopes of Mt. Sobaek in Danyang. Large halls are stacked in tiers up the mountainside."),
        .init(id: "kr.sobaeksan", ko: "충북 단양과 경북 영주에 걸친 국립공원의 산이다. 철쭉 군락과 완만한 능선, 겨울 눈 쌓인 풍경으로 알려져 있다.", english: "A mountain in a national park spanning Danyang and Yeongju. It is known for royal azalea fields, gentle ridges and snowy winter scenery."),
        .init(id: "kr.chungjuho", ko: "충북 충주 남한강을 막아 생긴 인공 호수다. 유람선과 호반 드라이브 길, 주변 산과 어우러진 풍경이 있다.", english: "An artificial lake formed by damming the Namhan River in Chungju. It offers cruises, lakeside drives and views of the surrounding hills."),
        .init(id: "kr.tangeumdae", ko: "충북 충주 남한강가 언덕에 있는 명승지다. 신라 우륵이 가야금을 탔다는 곳이며 임진왜란 때 신립 장군의 전투 장소로도 알려져 있다.", english: "A scenic hill on the Namhan River in Chungju. Tradition says the musician Ureuk played the gayageum here, and it was also the site of a battle in the Imjin War."),
        .init(id: "kr.suanbo", ko: "충북 충주 수안보에 있는 온천 마을이다. 오래전부터 온천으로 알려져 호텔과 대중 온천탕이 모여 있다.", english: "A hot spring town in Chungju. Known as a spa area for many years, it has hotels and public bathhouses."),
        .init(id: "kr.cheongju_craft", ko: "충북 청주에서 열리는 공예 분야 국제 행사다. 옛 연초제조창 건물을 활용한 전시장에서 공예 작품과 체험을 볼 수 있다.", english: "An international craft event held in Cheongju. Exhibits and workshops are shown in a repurposed former tobacco factory building."),
        .init(id: "kr.jikji", ko: "충북 청주에 있는 인쇄 문화 박물관이다. 세계에서 가장 오래된 금속활자본으로 알려진 직지와 관련한 자료를 전시한다.", english: "A museum on printing culture in Cheongju. It exhibits materials about Jikji, which is known as the oldest extant book printed with movable metal type."),
        .init(id: "kr.sanmagi", ko: "충북 괴산 괴산호 가장자리를 따라 이어지는 옛길이다. 산자락과 호수 사이로 걷는 산책로로 출렁다리와 전망대가 있다.", english: "An old path along the edge of Goesan Lake in Goesan. The trail runs between hillside and water, with a suspension bridge and viewpoints."),
        .init(id: "kr.ongnyeong", ko: "충북 옥천에 있는 시인 정지용의 생가다. 향수의 고향으로 알려져 있으며 초가집과 옆의 문학관을 함께 볼 수 있다.", english: "The birthplace of the poet Jeong Ji-yong in Okcheon. The thatched house stands beside a literature museum dedicated to his work."),
        .init(id: "kr.magoksa", ko: "충남 공주 태화산 자락에 있는 천년 고찰이다. 유네스코 세계유산인 한국의 산사 중 하나이며 계곡을 낀 숲길이 알려져 있다.", english: "An ancient temple on the slopes of Mt. Taehwa in Gongju. It is one of the Sansa mountain monasteries on the World Heritage list and sits in a valley forest."),
        .init(id: "kr.sudeoksa", ko: "충남 예산 덕숭산에 있는 사찰이다. 대웅전은 고려 시대 목조 건물로 국보로 지정되어 있다.", english: "A temple on Mt. Deoksung in Yesan. Its main hall is a wooden building from the Goryeo period designated a national treasure."),
        .init(id: "kr.deoksan", ko: "충남 예산 덕산면에 있는 온천 지역이다. 온천 시설과 숙박 시설이 모여 있고 근처에 수덕사와 덕산도립공원이 있다.", english: "A hot spring area in Deoksan, Yesan. Spas and lodgings cluster here, with Sudeoksa temple and a provincial park nearby."),
        .init(id: "kr.onyang", ko: "충남 아산 온양에 있는 온천 지역이다. 조선 시대 임금들도 찾았다고 전해지는 오랜 온천 고장이다.", english: "A hot spring area in Asan. It is a long-established spa town said to have been visited by Joseon kings."),
        .init(id: "kr.hyeonchungsa", ko: "충남 아산에 있는 이순신 장군의 사당이다. 장군이 어린 시절을 보낸 곳 가까이에 있고 유물 전시관과 정원이 있다.", english: "A shrine to Admiral Yi Sun-sin in Asan, near where he spent his youth. It has a relics exhibition hall and gardens."),
        .init(id: "kr.seosan_magaebul", ko: "충남 서산 바위 절벽에 새겨진 백제 시대 불상이다. 세 분의 불상이 부드러운 미소를 띠고 있어 백제의 미소로 알려져 있다.", english: "A group of three Buddha figures carved into a rock cliff in Seosan from the Baekje period. Their gentle smiles are known as the Baekje smile."),
        .init(id: "kr.ganwoldo", ko: "충남 서산 간월도 바닷가에 있는 작은 암자다. 물이 들면 섬처럼 떠 있고 썰물에는 걸어 들어갈 수 있다.", english: "A small hermitage on the shore of Ganwoldo in Seosan. At high tide it appears to float like an island, and at low tide it can be reached on foot."),
        .init(id: "kr.mallipo", ko: "충남 태안 서해안에 있는 해수욕장이다. 넓은 백사장과 소나무 숲이 있고 인근에 천리포수목원이 있다.", english: "A beach on the west coast in Taean. It has a broad sandy shore and pine woods, with Chollipo Arboretum nearby."),
        .init(id: "kr.chunjangdae", ko: "충남 서천 서해안에 있는 해수욕장이다. 곱고 넓은 백사장과 소나무 숲이 이어지고 일몰 풍경이 알려져 있다.", english: "A beach on the west coast in Seocheon. Fine sand and pine groves stretch along the shore, and it is known for sunsets."),
        .init(id: "kr.ppeuri", ko: "충남 부여에 있는 백제 시대 인공 연못이다. 무왕 때 조성된 것으로 전해지며 연꽃과 정자가 있다.", english: "An artificial pond in Buyeo from the Baekje period, traditionally attributed to King Mu. It has lotus flowers and a pavilion."),
        .init(id: "kr.nonsan_gwanchoksa", ko: "충남 논산 반야산에 있는 사찰이다. 높이 솟은 석조 불상으로 알려져 있고 은진미륵이라 불린다.", english: "A temple on Mt. Banya in Nonsan. It is known for a tall stone Buddha statue called the Eunjin Maitreya."),
        .init(id: "kr.chilgapsan", ko: "충남 청양에 있는 산으로 도립공원이다. 굽이굽이 이어진 능선과 장곡사, 콩밭 같은 풍경으로 알려져 있다.", english: "A mountain park in Cheongyang. It is known for winding ridges and Janggoksa temple, and for the rural scenery around it."),
        .init(id: "kr.jeondong", ko: "전북 전주 한옥마을에 있는 로마네스크 양식의 성당이다. 조선 시대 천주교 순교 터에 지었고 붉은 벽돌 건물이 특징이다.", english: "A Romanesque-style cathedral in Jeonju Hanok Village. It was built on a site tied to Catholic martyrs of the Joseon era and features a red brick design."),
        .init(id: "kr.nambu_market", ko: "전북 전주에 있는 전통 시장이다. 야시장과 비빔밥, 콩나물국밥 같은 전주 음식을 맛볼 수 있다.", english: "A traditional market in Jeonju. Its night market and local dishes such as bibimbap and bean sprout soup are popular."),
        .init(id: "kr.deokjin", ko: "전북 전주에 있는 큰 연못 공원이다. 여름 연꽃과 호수 위 출렁다리, 산책로가 알려져 있다.", english: "A large pond park in Jeonju. It is known for summer lotus flowers, a suspension bridge over the water and walking paths."),
        .init(id: "kr.gunsan_modern", ko: "전북 군산 항구 근처에 있는 박물관이다. 일제강점기 개항 이후 군산의 근대 역사와 생활상을 소개한다.", english: "A museum near the port of Gunsan. It presents the modern history and everyday life of the city after the port opened."),
        .init(id: "kr.gyeongam", ko: "전북 군산 경암동에 있는 옛 철길 마을이다. 기찻길 양옆에 낡은 집들이 이어져 옛 교복 체험과 사진 촬영으로 찾는다.", english: "An old railroad village in Gyeongam-dong, Gunsan. Weathered houses line both sides of the track, drawing visitors for retro photos and costume rental."),
        .init(id: "kr.seonyudo_gunsan", ko: "전북 군산 앞바다의 고군산군도에 있는 섬이다. 다리로 육지와 이어지고 해변과 봉우리 풍경이 알려져 있다.", english: "An island in the Gogunsan archipelago off Gunsan, connected to the mainland by bridges. It is known for its beach and rocky peaks."),
        .init(id: "kr.chaeseokgang", ko: "전북 부안 서해안의 해식 절벽이다. 책을 층층이 쌓아 놓은 듯한 암석과 일몰 풍경으로 알려져 있다.", english: "A sea cliff on the west coast in Buan. Its rock layers look like stacked books, and it is known for sunsets."),
        .init(id: "kr.naesosa", ko: "전북 부안 변산반도 국립공원에 있는 사찰이다. 전나무 숲길과 꽃창살이 있는 대웅보전으로 알려져 있다.", english: "A temple in Byeonsanbando National Park in Buan. It is known for a fir tree path and a main hall with carved floral lattice doors."),
        .init(id: "kr.geumsansa", ko: "전북 김제 모악산에 있는 사찰이다. 백제 시대 창건으로 전해지며 미륵전이 국보로 지정되어 있다.", english: "A temple on Mt. Moak in Gimje, said to date from the Baekje era. Its Maitreya Hall is designated a national treasure."),
        .init(id: "kr.gwanghalluwon", ko: "전북 남원에 있는 조선 시대 정원이다. 광한루와 오작교, 연못이 있어 춘향전의 배경으로 알려져 있다.", english: "A Joseon-era garden in Namwon. With its Gwanghallu pavilion, Ojakgyo bridge and pond, it is known as a setting of the folk tale of Chunhyang."),
        .init(id: "kr.gochang_eupseong", ko: "전북 고창에 있는 조선 시대 읍성이다. 성곽 위를 한 바퀴 걷는 길이 있고 답성놀이 풍습으로 알려져 있다.", english: "A Joseon-period walled town in Gochang. Visitors can walk the full circuit along the top of the wall, and it is tied to the custom of walking the fortress."),
        .init(id: "kr.imsil_cheese", ko: "전북 임실에 있는 치즈 체험 공원이다. 한국 치즈 산업의 시작으로 알려진 고장에서 치즈 만들기와 목장 체험을 할 수 있다.", english: "A cheese theme park in Imsil, known as the cradle of Korean cheese making. Visitors can make cheese and enjoy ranch activities."),
        .init(id: "kr.jinnamgwan", ko: "전남 여수에 있는 조선 시대 전라좌수영 객사다. 규모가 큰 목조 건물로 국보로 지정되어 있다.", english: "A Joseon-era guesthouse of the Jeolla Left Naval Command in Yeosu. It is a large wooden building designated a national treasure."),
        .init(id: "kr.yeosu_cable", ko: "전남 여수 바다 위를 가로지르는 케이블카다. 바닥이 유리인 객실에서 돌산대교와 여수 앞바다를 내려다본다.", english: "A cable car crossing the sea at Yeosu. Cabins with glass floors give views of Dolsan Bridge and the coast."),
        .init(id: "kr.odongdo", ko: "전남 여수 앞바다의 작은 섬으로 방파제로 육지와 이어진다. 동백나무 숲과 해안 산책로가 있다.", english: "A small island off Yeosu connected to the mainland by a breakwater. It has camellia woods and a coastal walking path."),
        .init(id: "kr.seonamsa", ko: "전남 순천 조계산 자락에 있는 사찰이다. 유네스코 세계유산인 한국의 산사 가운데 하나이며 승선교와 매화로 알려져 있다.", english: "A temple at the foot of Mt. Jogye in Suncheon. It is one of the Sansa mountain monasteries on the World Heritage list, known for the Seungseongyo bridge and plum blossoms."),
        .init(id: "kr.suncheon_garden", ko: "전남 순천만 습지 옆에 조성된 대형 정원이다. 세계 여러 나라의 정원과 호수, 갈대밭 풍경을 함께 즐길 수 있다.", english: "A large garden created beside the Suncheon Bay wetlands. It combines gardens from different countries with lakes and reed-bed scenery."),
        .init(id: "kr.mokpo_cable", ko: "전남 목포 유달산 아래에서 바다 위를 지나는 케이블카다. 목포 앞바다의 섬과 다리를 내려다볼 수 있다.", english: "A cable car running over the sea from the foot of Mt. Yudal in Mokpo. It gives views of islands and bridges off the coast."),
        .init(id: "kr.yudalsan", ko: "전남 목포 시내에 솟은 바위산이다. 정상 일대에서 목포 항구와 다도해를 내려다볼 수 있다.", english: "A rocky mountain rising in the middle of Mokpo. The summit gives views of the harbor and the islands beyond."),
        .init(id: "kr.daeheungsa", ko: "전남 해남 두륜산에 있는 사찰이다. 유네스코 세계유산인 한국의 산사 가운데 하나이며 편백 숲길이 이어진다.", english: "A temple on Mt. Duryun in Haenam. It is one of the Sansa mountain monasteries on the World Heritage list, with a path through cypress woods."),
        .init(id: "kr.wolchulsan", ko: "전남 영암에 있는 국립공원 산이다. 기암괴석이 솟은 능선과 구름다리가 알려져 있다.", english: "A national park mountain in Yeongam. It is known for rocky peaks along the ridge and a suspension bridge."),
        .init(id: "kr.cheongsando", ko: "전남 완도 앞바다의 섬이다. 돌담길과 유채꽃밭, 느리게 걷는 슬로길이 알려져 있다.", english: "An island off Wando. It is known for stone-walled lanes, rapeseed flower fields and slow walking trails."),
        .init(id: "kr.hongdo", ko: "전남 신안 서해 끝에 있는 섬으로 천연기념물로 지정되어 있다. 기암괴석과 유람선 해상 관광으로 알려져 있다.", english: "An island in Sinan at the far end of the western sea, designated as a natural monument. It is known for rock formations and boat tours around its coast."),
        .init(id: "kr.geumosan", ko: "전남 여수에 속한 섬으로 해안 절벽을 따라 비렁길이 이어진다. 바다 풍경과 걷기 여행으로 알려져 있다.", english: "An island in Yeosu with a cliffside walking trail called Biryeongil. It is known for sea views and hiking."),
        .init(id: "kr.gyeongju_tower", ko: "경북 경주 보문관광단지 근처의 전망 탑이다. 신라 시대 건축 요소를 본뜬 모양으로 높은 곳에서 시내를 내려다볼 수 있다.", english: "An observation tower near the Bomun Tourist Complex in Gyeongju. Its design draws on Silla-era architecture and offers high views over the city."),
        .init(id: "kr.hwangnidan", ko: "경북 경주 황남동의 거리다. 한옥을 고친 카페와 식당, 가게가 모여 있고 대릉원 근처에 있다.", english: "A street in Hwangnam-dong, Gyeongju. Renovated hanok houses hold cafes, restaurants and shops, close to the Daereungwon tombs."),
        .init(id: "kr.bomun", ko: "경북 경주 보문관광단지에 있는 인공 호수다. 호숫가 산책로와 자전거 길이 있고 벚꽃철에 많이 찾는다.", english: "An artificial lake in the Bomun Tourist Complex in Gyeongju. It has lakeside walking and cycling paths and is popular in cherry blossom season."),
        .init(id: "kr.munmu", ko: "경북 경주 동해 바다 가까이에 있는 신라 문무왕의 수중릉이다. 왕이 죽은 뒤 바다를 지키겠다는 유언에 따라 바위 사이에 모셨다고 전해진다.", english: "The tomb of Silla King Munmu placed among rocks in the East Sea off Gyeongju. By tradition, he asked to be buried at sea to protect the kingdom."),
        .init(id: "kr.yangdong", ko: "경북 경주에 있는 조선 시대 양반 마을이다. 기와집과 초가집이 언덕에 퍼져 있고 유네스코 세계유산에 속한다.", english: "A Joseon-period clan village in Gyeongju. Tiled and thatched houses spread across the hills, and it is a World Heritage site."),
        .init(id: "kr.bongjeongsa", ko: "경북 안동 천등산에 있는 사찰이다. 극락전은 현존하는 오래된 목조 건물로 알려져 있고 유네스코 세계유산에 속한다.", english: "A temple on Mt. Cheondeung in Andong. Its Geungnakjeon hall is known as one of Korea's oldest surviving wooden buildings, and the temple is a World Heritage site."),
        .init(id: "kr.woryeonggyo", ko: "경북 안동 낙동강에 놓인 긴 나무 다리다. 이응태 부인의 편지에서 유래한 이야기가 있고 밤에는 조명과 분수가 켜진다.", english: "A long wooden footbridge across the Nakdong River in Andong. A famous love letter story inspired it, and at night it is lit up with a fountain."),
        .init(id: "kr.mungyeong", ko: "경북 문경 조령산을 넘는 옛 고갯길이다. 조선 시대 영남과 한양을 잇던 길로 지금은 숲길로 걸을 수 있다.", english: "An old mountain pass over Mt. Joryeong in Mungyeong. It once linked Yeongnam to Hanyang in the Joseon era and is now a walking trail through forest."),
        .init(id: "kr.spacewalk", ko: "경북 포항 환호공원에 있는 철제 조형 전망 시설이다. 나선형 계단을 올라 바다와 항구를 내려다볼 수 있다.", english: "A steel walkway sculpture in Hwanho Park in Pohang. Visitors climb its spiral stairs for views of the sea and harbor."),
        .init(id: "kr.yeongildae", ko: "경북 포항 영일만에 있는 해수욕장이다. 해변 위에 설치된 누각과 야경이 알려져 있다.", english: "A beach on Yeongil Bay in Pohang. It is known for a pavilion by the shore and its night views."),
        .init(id: "kr.sosu_seowon", ko: "경북 영주에 있는 조선 시대 서원이다. 한국 최초의 사액 서원으로 알려져 있고 유네스코 세계유산인 한국의 서원에 속한다.", english: "A Joseon-era Confucian academy in Yeongju. It is known as the first to receive a royal name plaque, and is part of the World Heritage Seowon of Korea."),
        .init(id: "kr.chunjiyeon_uljin", ko: "경북 울진 천축산 계곡에 있는 사찰이다. 신라 시대에 창건된 비구니 절로 전해지고 연못에 비친 불영암 바위가 알려져 있다.", english: "A temple in a valley of Mt. Cheonchuk in Uljin, traditionally founded in the Silla period. It is known for a rock reflected in its pond."),
        .init(id: "kr.geoje_badaro", ko: "경남 거제 남쪽 해안의 언덕이다. 풍차와 푸른 바다가 어우러져 사진 촬영 명소로 알려져 있다.", english: "A seaside hill on the south coast of Geoje. A windmill and blue sea make it a popular photo stop."),
        .init(id: "kr.hanlyeosu", ko: "경남 통영 앞바다의 섬이다. 임진왜란 때 이순신 장군이 한산도 대첩을 치른 곳으로 제승당이 있다.", english: "An island off Tongyeong. Admiral Yi Sun-sin fought the Battle of Hansando here during the Imjin War, and the Jeseungdang shrine stands on the island."),
        .init(id: "kr.geumsan_namhae", ko: "경남 남해 상주 해변 위에 솟은 산이다. 남해 금산 보리암으로 알려져 있고 바위 봉우리 사이로 남해 바다가 내려다보인다.", english: "A mountain rising above Sangju Beach in Namhae. Known for Borimam hermitage, it overlooks the southern sea between rocky peaks."),
        .init(id: "kr.daraengi", ko: "남해군 남면의 바닷가 비탈에 계단식 논이 층층이 이어진 마을이다. 좁은 땅을 일군 농경 풍경과 바다가 함께 보인다.", english: "A seaside village in Namhae where terraced rice paddies step down a steep slope toward the sea. The farmland and the ocean make a distinctive view."),
        .init(id: "kr.changwon_lake", ko: "창원 동읍에 있는 큰 저수지로 철새 도래지로 알려져 있다. 겨울 철새와 주변 습지 풍경을 볼 수 있다.", english: "A large reservoir in Changwon known as a stopover for migratory birds. Visitors come to watch winter birds and enjoy the surrounding wetlands."),
        .init(id: "kr.masan_gagopa", ko: "마산 앞바다에 떠 있는 작은 섬으로 배를 타고 들어간다. 숲길을 걸으며 바다 풍경을 즐길 수 있다.", english: "A small island off Masan reached by boat. Forest paths and sea views make it a relaxed short outing."),
        .init(id: "kr.gimhae_tomb", ko: "김해에 있는 금관가야의 시조 수로왕을 모신 능이다. 가야의 역사를 떠올리게 하는 차분한 사적 공간이다.", english: "The tomb of King Suro, the legendary founder of Geumgwan Gaya, in Gimhae. It is a quiet historic site tied to the Gaya kingdoms."),
        .init(id: "kr.sancheong", ko: "산청에 있는 전통 한옥 마을로 옛 돌담길이 이어진다. 고택과 오래된 나무가 어우러진 고즈넉한 풍경이다.", english: "A traditional hanok village in Sancheong lined with old stone-wall lanes. Historic houses and aged trees give it a tranquil feel."),
        .init(id: "kr.hwagaejangteo", ko: "하동 화개면 섬진강 가에 있는 장터로 경남과 전남 사람들이 오가던 곳이다. 지금은 지역 특산물과 먹거리를 파는 관광지다.", english: "A market by the Seomjin River in Hwagae, Hadong, once a meeting point for people from two provinces. Today it sells local specialties and snacks."),
        .init(id: "kr.ssanggyesa", ko: "하동 지리산 남쪽 자락의 사찰로 신라 시대에 창건된 것으로 전해진다. 화개 계곡과 차밭이 가깝고 봄 벚꽃길로도 알려져 있다.", english: "A temple on the southern foothills of Jirisan in Hadong, said to date from the Silla period. Nearby are the Hwagae valley, tea fields and a well-known spring cherry road."),
        .init(id: "kr.choe_chamnan", ko: "하동 악양 들판 위에 있는 한옥 고택으로 소설 토지의 배경으로 알려져 있다. 드라마 촬영지로도 쓰였고 들판과 지리산이 내려다보인다.", english: "A hanok mansion above the Akyang plain in Hadong, known as the setting of the novel Toji. It overlooks wide fields with Jirisan beyond."),
        .init(id: "kr.hwangmaesan", ko: "합천에 있는 산으로 봄 철쭉 군락과 가을 억새로 알려져 있다. 능선을 따라 걷는 산행과 일출 감상지로 찾는다.", english: "A mountain in Hapcheon known for spring royal azaleas and autumn silvergrass. Hikers walk its ridges and come for sunrise views."),
        .init(id: "kr.hamdeok", ko: "제주시 북동쪽에 있는 해수욕장으로 완만한 백사장과 에메랄드빛 바다가 특징이다. 가까이 서우봉이 있어 산책하기 좋다.", english: "A beach on the northeast coast of Jeju City with gentle white sand and clear turquoise water. Nearby Seoubong hill offers an easy walk."),
        .init(id: "kr.woljeongri", ko: "제주 동쪽 구좌읍에 있는 해변으로 맑은 바다와 고운 모래가 이어진다. 해안을 따라 카페가 많아 쉬어 가기 좋다.", english: "A beach in Gujwa on Jeju's east coast with clear water and fine sand. Cafes along the shore make it a pleasant place to rest."),
        .init(id: "kr.aewol", ko: "제주 서북쪽 애월 해안의 한담 해변으로 검은 현무암과 푸른 바다가 어우러진다. 해안 산책로를 따라 걷기 좋다.", english: "Handam Beach on Aewol's coast in northwest Jeju, where dark basalt meets blue sea. A coastal walking path runs along the shore."),
        .init(id: "kr.oedolgae", ko: "서귀포 앞바다에 홀로 솟은 바위 기둥이다. 화산 활동으로 생긴 해안 절벽 풍경과 산책로가 이어진다.", english: "A lone sea stack rising off the coast of Seogwipo. Volcanic cliffs and a coastal walking trail surround it."),
        .init(id: "kr.jusangjeolli", ko: "서귀포 중문 해안의 주상절리로 용암이 식으며 기둥 모양으로 굳은 바위 절벽이다. 파도가 부딪히는 모습을 가까이서 볼 수 있다.", english: "A coastal cliff in Jungmun, Seogwipo, formed of columnar basalt that cooled from lava. Waves crash against the rock columns below the viewing paths."),
        .init(id: "kr.sanbangsan", ko: "제주 남서쪽 해안에 솟은 종 모양의 용암 돔 산이다. 산 중턱에 암자 같은 굴이 있고 주변에 용머리해안과 바다가 펼쳐진다.", english: "A bell-shaped lava dome rising from Jeju's southwest coast. A small cave shrine sits partway up, and the sea and Yongmeori Coast lie nearby."),
        .init(id: "kr.songaksan", ko: "제주 서남쪽 바닷가에 있는 낮은 오름으로 둘레길이 이어진다. 가파도와 마라도, 형제섬이 보이는 전망이 좋다.", english: "A low volcanic cone on Jeju's southwest shore with a loop trail. Views reach Gapado, Marado and the offshore islets."),
        .init(id: "kr.gapado", ko: "제주 모슬포 앞바다에 있는 낮고 평평한 섬이다. 봄에는 청보리밭이 펼쳐지며 걸어서 한 바퀴 돌아볼 수 있다.", english: "A low, flat island off Moseulpo in Jeju. In spring green barley fields cover it, and the whole island can be circled on foot."),
        .init(id: "kr.marado", ko: "우리나라 최남단에 있는 섬으로 제주 남쪽 바다에 떠 있다. 평평한 지형을 따라 걷는 둘레길과 등대, 작은 성당이 있다.", english: "The southernmost inhabited island of Korea, lying south of Jeju. A flat loop path passes a lighthouse and a small chapel."),
        .init(id: "kr.seongeup", ko: "제주 표선면에 있는 전통 마을로 옛 제주 읍성 터를 중심으로 한다. 초가집과 돌담, 느티나무가 남아 있어 제주의 옛 생활을 보여 준다.", english: "A traditional village in Pyoseon on Jeju, built around an old county fortress site. Thatched houses, stone walls and old trees show the island's past way of life."),
        .init(id: "kr.dongmun", ko: "제주시 원도심에 있는 전통 시장이다. 감귤과 해산물, 제주 먹거리를 한곳에서 볼 수 있다.", english: "A traditional market in downtown Jeju City. Citrus, seafood and local street food are all found in one place."),
        .init(id: "kr.bijarim", ko: "제주 구좌읍에 있는 비자나무 숲으로 오래된 나무가 빽빽하게 자란다. 천연기념물로 지정되어 있으며 숲길이 평탄해 걷기 좋다.", english: "A forest of torreya trees in Gujwa, Jeju, with many very old specimens. It is a designated natural monument with an easy, flat walking path."),
        .init(id: "kr.saebyeol", ko: "제주시 애월읍 쪽에 있는 오름으로 억새가 많다. 정상에서 한라산과 서쪽 들판이 내려다보인다.", english: "A volcanic cone near Aewol in Jeju covered with silvergrass. From the top, Hallasan and the western plains are in view."),
        .init(id: "kr.yongmeori", ko: "산방산 아래 바닷가에 있는 해안 절벽으로 용이 머리를 내민 모양이라 이름이 붙었다. 수천 년에 걸쳐 쌓인 퇴적암 층이 물결무늬로 드러나 있다.", english: "A coastal cliff below Sanbangsan named for its resemblance to a dragon’s head reaching into the sea. Layers of sedimentary rock are carved into wave-like patterns."),
        .init(id: "kr.bangyeri_ginkgo", ko: "원주 문막읍에 있는 수령이 오래된 은행나무로 천연기념물이다. 가을에는 노랗게 물든 거대한 나무와 낙엽이 장관을 이룬다.", english: "A very old ginkgo tree in Munmak, Wonju, designated a natural monument. In autumn its huge golden crown and fallen leaves draw many visitors."),
        .init(id: "kr.hongcheon_ginkgo", ko: "홍천 내면에 있는 은행나무 숲으로 가을 단풍철에 개방된다. 노란 은행잎이 숲 바닥을 가득 덮는다.", english: "A ginkgo grove in Hongcheon that opens to visitors during autumn color season. Yellow leaves blanket the forest floor."),
        .init(id: "kr.inje_birch", ko: "인제 원대리에 조성된 자작나무 숲이다. 흰 줄기가 곧게 뻗은 숲길을 따라 천천히 걸을 수 있다.", english: "A planted birch forest in Wondae-ri, Inje. Slender white trunks line a trail made for slow walks."),
        .init(id: "kr.daegwallyeong_sheep", ko: "평창 대관령 고원에 있는 목장으로 양에게 먹이를 주는 체험을 할 수 있다. 초원과 능선이 이어지는 산책로가 있다.", english: "A ranch on the Daegwallyeong highlands in Pyeongchang where visitors can feed sheep. Walking paths cross open meadows and ridgelines."),
        .init(id: "kr.hanbando", ko: "영월 선암마을 부근에 있는 지형으로 강이 휘돌아 한반도 모양을 이룬다. 전망대에서 굽이치는 서강과 숲이 내려다보인다.", english: "A river bend near Seonam Village in Yeongwol that curves into the shape of the Korean Peninsula. An overlook shows the winding Seogang River and surrounding forest."),
        .init(id: "kr.cheongnyeongpo", ko: "영월 남한강 상류의 세 면이 강으로 둘러싸인 곳이다. 조선 단종이 유배되었던 장소로 알려져 있으며 소나무 숲이 있다.", english: "A spot in Yeongwol surrounded by river on three sides. It is known as the place where Joseon’s King Danjong was exiled, with a pine grove nearby."),
        .init(id: "kr.yongmun_ginkgo", ko: "양평 용문사 경내에 서 있는 아주 오래된 은행나무로 천연기념물이다. 높이가 매우 높아 가을 단풍 명소로 꼽힌다.", english: "A very old ginkgo tree in the grounds of Yongmunsa in Yangpyeong, designated a natural monument. Its great height and autumn color draw many visitors."),
        .init(id: "kr.hwadam", ko: "곤지암 인근 산자락에 조성된 수목원이다. 다양한 나무와 꽃, 이끼 정원이 있고 계절마다 풍경이 바뀐다.", english: "A botanical garden on a hillside near Gonjiam. Many trees, flowers and moss gardens change with each season."),
        .init(id: "kr.jeongipumsong", ko: "보은 속리산 입구에 있는 소나무로 천연기념물이다. 조선 세조가 지나갈 때 가지를 들어 올렸다는 전설이 전해진다.", english: "A pine tree near the entrance to Songnisan in Boeun, designated a natural monument. Legend says it lifted its branch for King Sejo of Joseon as he passed."),
        .init(id: "kr.gokgyocheon", ko: "아산 곡교천을 따라 은행나무가 늘어선 길이다. 가을이면 노란 터널이 이어져 걷기와 사진 명소가 된다.", english: "A road in Asan lined with ginkgo trees along the Gokgyo Stream. In autumn it becomes a golden tunnel for walking and photos."),
        .init(id: "kr.sinseongri", ko: "서천 금강 하구 가까이에 있는 넓은 갈대밭이다. 가을 억새와 갈대가 바람에 흔들리고 영화 촬영지로도 알려져 있다.", english: "A wide reed field near the Geum River estuary in Seocheon. Reeds sway in autumn winds, and it has appeared in films."),
        .init(id: "kr.geumsan_yogwang", ko: "금산 요광리에 있는 오래된 은행나무로 천연기념물이다. 가을이면 노란 잎이 마을 앞을 물들인다.", english: "An old ginkgo tree in Yogwang-ri, Geumsan, designated a natural monument. In autumn its yellow leaves color the village."),
        .init(id: "kr.gochang_hakwon", ko: "고창에 있는 농장으로 봄 청보리밭과 가을 메밀꽃 풍경으로 알려져 있다. 넓은 들판을 거닐며 계절 경관을 즐길 수 있다.", english: "A farm in Gochang known for green barley fields in spring and buckwheat flowers in autumn. Visitors stroll across the wide fields."),
        .init(id: "kr.gangcheonsan", ko: "순창에 있는 산으로 계곡과 단풍이 좋아 군립공원으로 지정되어 있다. 현수교와 폭포를 지나는 산책로가 인기다.", english: "A mountain in Sunchang designated a county park for its valleys and autumn foliage. A suspension bridge and waterfalls lie along the popular trail."),
        .init(id: "kr.gwanbangjerim", ko: "담양 관방천 둑을 따라 오래된 나무가 늘어선 숲이다. 조선 시대에 홍수를 막으려 쌓은 제방에 심은 것으로 전해진다.", english: "A long row of old trees along the Gwanbang Stream embankment in Damyang. The embankment is said to have been built in the Joseon era to control floods."),
        .init(id: "kr.soswaewon", ko: "담양에 있는 조선 시대 선비의 별서 정원이다. 계곡 물길과 대나무, 정자가 어우러진 한국 전통 정원이다.", english: "A Joseon-era scholar’s garden in Damyang. A stream, bamboo and pavilions form a classic Korean landscape garden."),
        .init(id: "kr.sansuyu", ko: "구례 산동면에 있는 마을로 봄에 산수유꽃이 노랗게 핀다. 지리산 자락 마을 곳곳이 꽃으로 물든다.", english: "A village in Sandong, Gurye, covered in yellow cornelian cherry blossoms in spring. The flowers color the slopes at the foot of Jirisan."),
        .init(id: "kr.gwangyang_maehwa", ko: "광양 섬진강 가에 있는 마을로 이른 봄 매화꽃이 가득 핀다. 매실 농가와 강 풍경이 어우러진다.", english: "A village by the Seomjin River in Gwangyang filled with plum blossoms in early spring. Plum orchards and river scenery combine here."),
        .init(id: "kr.seryangji", ko: "화순에 있는 저수지로 물가에 비친 산 풍경이 알려져 있다. 봄 벚꽃과 새벽 물안개, 가을 단풍이 사진 명소다.", english: "A reservoir in Hwasun known for mountain reflections on its water. Spring blossoms, morning mist and autumn leaves attract photographers."),
        .init(id: "kr.jusanji", ko: "청송 주왕산 자락에 있는 오래된 저수지로 물속에 자라는 왕버들이 특징이다. 이른 아침 물안개 풍경으로 알려져 있다.", english: "An old reservoir in the Juwangsan area of Cheongsong, with willow trees growing in the water. It is known for misty early mornings."),
        .init(id: "kr.yonggye_ginkgo", ko: "영덕과 인근 지역 옛 마을에 서 있는 아주 오래된 은행나무다. 가을이면 노란 단풍으로 눈길을 끈다.", english: "A very old ginkgo tree standing in a former village in the Yeongdeok area. Its yellow autumn foliage is the main attraction."),
        .init(id: "kr.ungok_ginkgo", ko: "경북의 서원에 서 있는 오래된 은행나무다. 서원의 고요한 분위기와 가을 단풍이 잘 어울린다.", english: "An old ginkgo tree beside a historic Confucian academy in Gyeongbuk. Its autumn gold suits the quiet grounds."),
        .init(id: "kr.geumgang_pine", ko: "울진 소광리 일대에 이어지는 금강소나무 숲길이다. 곧게 자란 소나무 사이를 걷는 숲 산책로다.", english: "A forest trail through Geumgang pines around Sogwang-ri in Uljin. It winds among tall, straight trees."),
        .init(id: "kr.dodong_cypress", ko: "대구 달성 도동 마을 가까이에 있는 측백나무 숲으로 천연기념물이다. 절벽 위에 자생하는 희귀한 숲으로 알려져 있다.", english: "An arborvitae forest near Dodong in Dalseong, Daegu, designated a natural monument. The trees grow naturally on a cliff slope."),
        .init(id: "kr.hadong_cherry", ko: "하동 화개 쌍계사 쪽으로 이어지는 벚나무 길이다. 봄이면 꽃터널이 십 리 넘게 이어져 드라이브 명소로 알려져 있다.", english: "A road lined with cherry trees leading toward Ssanggyesa in Hwagae, Hadong. In spring the blossoms form a long tunnel loved by drivers."),
        .init(id: "kr.chamseongdan", ko: "강화 마니산 정상에 있는 제단이다. 단군이 하늘에 제사를 지냈다는 전설이 전해지며 사적으로 지정되어 있다.", english: "An altar at the summit of Manisan on Ganghwa Island. Legend says Dangun held rites to heaven here, and it is a designated historic site."),
        .init(id: "kr.sinlim_oak", ko: "서울 관악구 신림동에 있는 굴참나무다. 도심 속에서 오랜 세월을 견딘 노거수로 보호받고 있다.", english: "A cork oak in Sillim-dong, Gwanak District, Seoul. An old urban tree that has been protected for its age."),
        .init(id: "kr.jeju_camellia", ko: "제주 안덕면에 있는 수목원이다. 겨울에 동백꽃이 피고 계절마다 다른 꽃과 정원을 볼 수 있다.", english: "A botanical garden in Andeok, Jeju. Camellias bloom in winter, and different flowers and gardens appear through the seasons."),
        .init(id: "intl.jp.tokyo", ko: "일본의 수도로 전통과 현대가 공존하는 대도시다. 센소지, 시부야, 도쿄 스카이트리 등이 대표 볼거리다.", english: "The capital of Japan, a huge city where tradition and modern life sit side by side. Highlights include Senso-ji, Shibuya and Tokyo Skytree."),
        .init(id: "intl.jp.osaka", ko: "일본 간사이 지방의 중심 도시로 먹거리로 유명하다. 오사카성과 도톤보리가 대표 명소다.", english: "The main city of Japan’s Kansai region, famous for its food. Osaka Castle and Dotonbori are the best-known sights."),
        .init(id: "intl.jp.fukuoka", ko: "일본 규슈 북부의 도시로 한국에서 가깝다. 포장마차 거리와 하카타 라멘, 다자이후 신사가 알려져 있다.", english: "A city in northern Kyushu, Japan, close to Korea. It is known for open-air food stalls, Hakata ramen and Dazaifu Shrine."),
        .init(id: "intl.jp.sapporo", ko: "일본 홋카이도의 중심 도시다. 눈 축제와 맥주, 신선한 해산물과 홋카이도 먹거리로 알려져 있다.", english: "The main city of Hokkaido, Japan. It is known for its snow festival, beer and fresh seafood."),
        .init(id: "intl.jp.nagoya", ko: "일본 중부 아이치현의 중심 도시다. 나고야성과 도요타 관련 시설, 독특한 향토 요리가 알려져 있다.", english: "The center of Aichi Prefecture in central Japan. Nagoya Castle, car-industry museums and distinctive local dishes are highlights."),
        .init(id: "intl.jp.naha", ko: "일본 오키나와현의 현청 소재지다. 슈리성과 국제거리, 류큐 문화와 남국 바다로 알려져 있다.", english: "The prefectural capital of Okinawa, Japan. Shuri Castle, Kokusai Street and Ryukyuan culture define the city."),
        .init(id: "intl.jp.aomori", ko: "일본 혼슈 최북단의 항구 도시다. 네부타 축제와 사과, 신선한 해산물로 알려져 있다.", english: "A port city at the northern tip of Honshu, Japan. It is known for the Nebuta festival, apples and fresh seafood."),
        .init(id: "intl.jp.hakodate", ko: "일본 홋카이도 남쪽의 항구 도시다. 하코다테산의 야경과 아침 시장, 서양식 건물이 있는 언덕 마을이 유명하다.", english: "A port city in southern Hokkaido, Japan. It is famous for the night view from Mount Hakodate, its morning market and hillside old Western-style buildings."),
        .init(id: "intl.jp.hiroshima", ko: "일본 서부의 도시로 평화 기념 공원과 원폭 돔이 있다. 가까운 미야지마의 이쓰쿠시마 신사도 널리 알려져 있다.", english: "A city in western Japan home to the Peace Memorial Park and the Atomic Bomb Dome. Itsukushima Shrine on nearby Miyajima is also well known."),
        .init(id: "intl.jp.ishigaki", ko: "일본 오키나와현 야에야마 제도에 있는 섬 도시다. 맑은 바다와 산호초, 주변 섬으로 가는 배편의 관문이다.", english: "An island city in Japan’s Yaeyama Islands, Okinawa. Clear seas and coral reefs make it a gateway to nearby islands."),
        .init(id: "intl.jp.kagoshima", ko: "일본 규슈 남쪽의 도시로 활화산 사쿠라지마가 바다 건너에 보인다. 온천과 흑돼지 요리로도 알려져 있다.", english: "A city in southern Kyushu, Japan, facing the active volcano Sakurajima across the bay. It is also known for hot springs and black pork dishes."),
        .init(id: "intl.jp.kitakyushu", ko: "일본 규슈 북쪽 끝의 항구 공업 도시다. 모지코 레트로 지구와 고쿠라성이 있고 후쿠오카와 가깝다.", english: "A port and industrial city at the northern tip of Kyushu, Japan. The retro Mojiko district and Kokura Castle are nearby, not far from Fukuoka."),
        .init(id: "intl.jp.kobe", ko: "일본 효고현의 항구 도시로 개항 이후 서양 문물이 들어온 곳이다. 이진칸 거리와 고베 비프, 항구 야경이 알려져 있다.", english: "A port city in Hyogo, Japan, shaped by early foreign trade. It is known for the Kitano foreign residences, Kobe beef and harbor night views."),
        .init(id: "intl.jp.komatsu", ko: "일본 이시카와현의 도시로 고마쓰 공항이 있어 호쿠리쿠 지방의 관문이다. 가까이에 가나자와와 온천 마을이 있다.", english: "A city in Ishikawa, Japan, with an airport serving the Hokuriku region. Kanazawa and hot spring towns are nearby."),
        .init(id: "intl.jp.kumamoto", ko: "일본 규슈 중부의 도시로 구마모토성이 중심이다. 가까이 아소산과 온천이 있고 마스코트 쿠마몬으로도 알려져 있다.", english: "A city in central Kyushu, Japan, centered on Kumamoto Castle. Mount Aso and hot springs are nearby, and the mascot Kumamon is famous."),
        .init(id: "intl.jp.matsuyama", ko: "일본 시코쿠 에히메현의 중심 도시다. 오래된 도고 온천과 마쓰야마성이 대표 볼거리다.", english: "The main city of Ehime on Shikoku, Japan. The old Dogo Onsen and Matsuyama Castle are its main sights."),
        .init(id: "intl.jp.miyazaki", ko: "일본 규슈 남동쪽의 도시로 따뜻한 기후와 해안으로 알려져 있다. 신화와 연결된 신사와 서핑 해변이 있다.", english: "A city on Kyushu’s southeast coast, Japan, known for its warm climate and shoreline. It has shrines tied to myth and surf beaches."),
        .init(id: "intl.jp.nagasaki", ko: "일본 규슈 서쪽의 항구 도시로 오랫동안 해외 교류의 창구였다. 평화 공원과 언덕 위 야경, 짬뽕으로 알려져 있다.", english: "A port city in western Kyushu, Japan, long a window to the outside world. It is known for its Peace Park, hillside night views and champon noodles."),
        .init(id: "intl.jp.niigata", ko: "일본 혼슈 동해 쪽의 항구 도시다. 쌀과 사케로 알려져 있고 사도섬으로 가는 배편이 있다.", english: "A port city on Honshu’s Sea of Japan coast. It is known for rice and sake, with ferries to Sado Island."),
        .init(id: "intl.jp.okayama", ko: "일본 혼슈 서부의 도시로 검은 외벽의 오카야마성과 고라쿠엔 정원이 있다. 가까운 구라시키 미관지구로 가기 좋다.", english: "A city in western Honshu, Japan, with the black-walled Okayama Castle and Korakuen Garden. The historic Kurashiki district is nearby."),
        .init(id: "intl.jp.oita", ko: "일본 규슈 동북부의 도시로 벳푸와 유후인 온천 지역과 가깝다. 지역에서 온천이 많이 나는 것으로 알려져 있다.", english: "A city in northeastern Kyushu, Japan, near the hot spring areas of Beppu and Yufuin. The region is known for its abundant hot springs."),
        .init(id: "intl.jp.sendai", ko: "일본 도호쿠 지방의 중심 도시로 숲이 많아 숲의 도시로 불린다. 소고기 혀구이 요리와 가까운 마쓰시마 만이 알려져 있다.", english: "The main city of Japan’s Tohoku region, called the city of trees. It is known for grilled beef tongue and nearby Matsushima Bay."),
        .init(id: "intl.jp.miyakojima", ko: "일본 오키나와현 미야코 제도의 섬이다. 투명한 바다와 긴 다리, 해변이 있는 휴양지로 알려져 있다.", english: "An island in Japan’s Miyako Islands, Okinawa. It is a resort destination with clear water, long bridges and beautiful beaches."),
        .init(id: "intl.jp.shizuoka", ko: "일본 혼슈 중부의 도시로 후지산이 가깝다. 녹차 산지와 스루가만 해산물로 알려져 있다.", english: "A city in central Honshu, Japan, close to Mount Fuji. It is known for green tea fields and seafood from Suruga Bay."),
        .init(id: "intl.jp.takamatsu", ko: "일본 시코쿠 가가와현의 중심 도시다. 사누키 우동과 리쓰린 공원, 나오시마 등 예술 섬으로 가는 관문이다.", english: "The main city of Kagawa on Shikoku, Japan. It is known for Sanuki udon and Ritsurin Garden, and is a gateway to art islands such as Naoshima."),
        .init(id: "intl.jp.tokushima", ko: "일본 시코쿠 동부의 도시로 아와오도리 춤 축제로 알려져 있다. 가까운 나루토 해협의 소용돌이도 볼거리다.", english: "A city in eastern Shikoku, Japan, famous for the Awa Odori dance festival. The whirlpools of nearby Naruto Strait are another draw."),
        .init(id: "intl.jp.yonago", ko: "일본 돗토리현의 도시로 동해 쪽 항구 도시다. 요나고 공항과 다이센 산, 가까운 온천 지역이 있다.", english: "A city in Tottori on Japan’s Sea of Japan coast. It has an airport, and Mount Daisen and hot spring areas are nearby."),
        .init(id: "intl.cn.beijing", ko: "중국의 수도로 오랜 역사를 지닌 도시다. 자금성과 천안문 광장, 만리장성이 대표 볼거리다.", english: "The capital of China, a city with a long history. The Forbidden City, Tiananmen Square and the Great Wall are the top sights."),
        .init(id: "intl.cn.shanghai", ko: "중국 동부의 대도시로 상업과 금융의 중심이다. 와이탄과 푸둥의 고층 빌딩 야경이 대표 풍경이다.", english: "A major city on China’s east coast and a center of commerce and finance. The Bund and the skyscrapers of Pudong define its skyline."),
        .init(id: "intl.cn.guangzhou", ko: "중국 남부 광둥성의 중심 도시로 오랜 무역 도시다. 딤섬 등 광둥 요리와 광저우타워가 알려져 있다.", english: "The center of Guangdong in southern China and a long-time trading city. It is known for Cantonese cuisine such as dim sum and the Canton Tower."),
        .init(id: "intl.cn.shenzhen", ko: "중국 남부 홍콩 맞은편에 있는 현대 도시다. 개혁 개방과 함께 빠르게 성장했고 기술 산업의 중심으로 알려져 있다.", english: "A modern city in southern China just across from Hong Kong. It grew rapidly after economic reforms and is known as a technology hub."),
        .init(id: "intl.cn.chengdu", ko: "중국 쓰촨성의 중심 도시다. 자이언트 판다 번식 기지와 매운 쓰촨 요리, 찻집 문화로 알려져 있다.", english: "The capital of Sichuan, China. It is known for its giant panda breeding base, spicy Sichuan cuisine and teahouse culture."),
        .init(id: "intl.cn.chongqing", ko: "중국 서남부 양쯔강과 자링강이 만나는 산악 도시다. 층층이 겹친 지형의 야경과 훠궈로 알려져 있다.", english: "A hilly city in southwest China where the Yangtze and Jialing rivers meet. It is known for its layered night views and hot pot."),
        .init(id: "intl.cn.changchun", ko: "중국 지린성의 성도로 동북 지방의 도시다. 자동차 산업과 영화 제작 역사, 넓은 공원과 겨울 풍경이 알려져 있다.", english: "The capital of Jilin Province in northeast China. It is known for its auto industry, film history, large parks and snowy winters."),
        .init(id: "intl.cn.changsha", ko: "중국 후난성의 중심 도시다. 마오쩌둥 청년 시절 유적과 굴섬 공원, 매운 후난 요리로 알려져 있다.", english: "The capital of Hunan, China. It is known for sites from Mao Zedong’s youth, Orange Isle Park and spicy Hunan food."),
        .init(id: "intl.cn.dalian", ko: "중국 랴오닝성의 항구 도시로 황해 연안에 있다. 해안 광장과 해변 산책로가 있고 신선한 해산물이 알려져 있다.", english: "A port city in Liaoning, China, on the Yellow Sea coast. It has seaside squares and promenades and is known for fresh seafood."),
        .init(id: "intl.cn.fuzhou", ko: "중국 푸젠성의 성도로 오래된 항구 도시다. 삼방칠항 옛 거리와 온천, 푸젠 지방 요리가 알려져 있다.", english: "The capital of Fujian, China, and an old port city. It is known for the historic Three Lanes and Seven Alleys district, hot springs and Fujian cuisine."),
        .init(id: "intl.cn.guilin", ko: "중국 광시성의 도시로 석회암 봉우리가 이어지는 풍경으로 알려져 있다. 리강 유람과 양숴 일대가 대표 볼거리다.", english: "A city in Guangxi, China, famed for its limestone peaks. Li River cruises and the nearby Yangshuo area are the main attractions."),
        .init(id: "intl.cn.guiyang", ko: "중국 구이저우성의 성도로 여름이 서늘한 도시다. 소수 민족 문화와 인근 폭포, 산악 풍경을 즐길 수 있다.", english: "The capital of Guizhou, China, with cool summers. Minority cultures, nearby waterfalls and mountain scenery are its draws."),
        .init(id: "intl.cn.haikou", ko: "중국 하이난섬 북쪽에 있는 도시로 하이난성의 성도다. 열대 기후와 야자수, 오래된 상가 거리가 알려져 있다.", english: "The capital of Hainan Province on the island’s north coast, China. It has a tropical climate, palm trees and old arcade streets."),
        .init(id: "intl.cn.hangzhou", ko: "중국 저장성의 성도로 서호가 중심이다. 오랜 시인과 화가에게 사랑받은 호수 풍경과 용정차 산지가 알려져 있다.", english: "The capital of Zhejiang, China, centered on West Lake. Its lake scenery has long inspired poets and artists, and Longjing tea grows nearby."),
        .init(id: "intl.cn.harbin", ko: "중국 헤이룽장성의 성도로 북쪽 끝 도시다. 러시아풍 건축과 겨울 빙등 축제로 알려져 있다.", english: "The capital of Heilongjiang in northern China. It is known for Russian-style architecture and its winter ice festival."),
        .init(id: "intl.cn.hefei", ko: "중국 안후이성의 성도다. 과학 연구 기관이 많고 소요진 같은 옛 유적과 인근 황산 여행의 거점이 된다.", english: "The capital of Anhui, China. It has many research institutes and old sites such as Xiaoyaojin, and serves as a base for trips toward Huangshan."),
        .init(id: "intl.cn.hohhot", ko: "중국 내몽골 자치구의 성도다. 초원 문화와 몽골 전통 음식, 라마 사원이 알려져 있다.", english: "The capital of Inner Mongolia, China. It is known for grassland culture, Mongolian food and Tibetan Buddhist temples."),
        .init(id: "intl.cn.jiamusi", ko: "중국 헤이룽장성 동북부의 도시로 쑹화강 가에 있다. 추운 겨울과 인근 습지, 러시아와의 국경 지대에 가깝다.", english: "A city on the Songhua River in northeastern Heilongjiang, China. It has cold winters and lies near wetlands and the Russian border."),
        .init(id: "intl.cn.kunming", ko: "중국 윈난성의 성도로 사계절 온화해 봄의 도시로 불린다. 석림과 전지 호수, 소수 민족 문화로 가는 관문이다.", english: "The capital of Yunnan, China, called the Spring City for its mild climate. It is a gateway to the Stone Forest, Dian Lake and minority cultures."),
        .init(id: "intl.cn.nanjing", ko: "중국 장쑤성의 성도로 여러 왕조의 도읍이었던 고도다. 중산릉과 명나라 성벽, 친화이강 일대가 알려져 있다.", english: "The capital of Jiangsu, China, and an ancient capital of several dynasties. Sun Yat-sen Mausoleum, the Ming city wall and the Qinhuai River area are highlights."),
        .init(id: "intl.cn.ordos", ko: "중국 내몽골 남서부의 도시로 사막과 초원이 가까이 있다. 칭기즈 칸 능원과 쿠부치 사막이 알려져 있다.", english: "A city in southwest Inner Mongolia, China, near deserts and grasslands. The Genghis Khan Mausoleum and the Kubuqi Desert are known sights."),
        .init(id: "intl.cn.qingdao", ko: "중국 산둥성의 해안 도시로 독일 조차지 시절의 건축물이 남아 있다. 칭다오 맥주와 해변, 잔교가 알려져 있다.", english: "A coastal city in Shandong, China, with buildings from its German colonial era. It is known for Tsingtao beer, beaches and Zhanqiao Pier."),
        .init(id: "intl.cn.sanya", ko: "중국 최남단 하이난섬에 있는 해안 도시다. 따뜻한 기후와 야자수 해변, 리조트로 알려진 휴양지다.", english: "Sanya is a coastal city at the southern tip of China’s Hainan Island. It is a tropical resort destination known for warm weather, palm-lined beaches and seaside hotels."),
        .init(id: "intl.cn.shenyang", ko: "중국 랴오닝성의 중심 도시로 동북 지방의 큰 도시다. 청나라 초기 황궁이었던 선양고궁이 대표 볼거리다.", english: "Shenyang is the main city of Liaoning Province in northeastern China. Its best-known sight is the Shenyang Imperial Palace, built in the early Qing era."),
        .init(id: "intl.cn.shijiazhuang", ko: "중국 허베이성의 성도로 베이징 남서쪽에 있다. 철도 교통의 요지이며 주변에 오래된 사찰과 유적이 있다.", english: "Shijiazhuang is the capital of Hebei Province, southwest of Beijing. It is a railway hub, with old temples and historic sites in the surrounding area."),
        .init(id: "intl.cn.tianjin", ko: "중국 북동부 발해만에 면한 직할시로 베이징과 가깝다. 옛 조계지의 유럽풍 건물과 하이허강변 풍경이 볼만하다.", english: "Tianjin is a municipality on China’s northeastern coast, close to Beijing. It features European-style buildings from its former concessions and scenic walks along the Hai River."),
        .init(id: "intl.cn.urumqi", ko: "중국 서북부 신장위구르 자치구의 중심 도시다. 실크로드 문화와 다양한 민족의 음식, 시장이 어우러진다.", english: "Urumqi is the main city of Xinjiang in northwestern China. Silk Road heritage, diverse ethnic cuisines and busy bazaars shape its character."),
        .init(id: "intl.cn.weihai", ko: "중국 산둥반도 끝자락에 있는 항구 도시다. 한국과 가까운 바다 건너 도시로 해변과 깨끗한 거리가 특징이다.", english: "Weihai is a port city at the tip of the Shandong Peninsula, across the sea from Korea. It is known for its seaside promenades and tidy streets."),
        .init(id: "intl.cn.wenzhou", ko: "중국 저장성 남부 해안의 항구 도시다. 상업 활동이 활발하며 인근 옌당산 등 산수 경관이 있다.", english: "Wenzhou is a port city on the southern coast of Zhejiang Province. It has a lively commercial culture, and scenic mountains such as Yandang lie nearby."),
        .init(id: "intl.cn.wuhan", ko: "중국 중부 창장강과 한수이강이 만나는 대도시다. 황학루와 동호 호수 등이 대표 명소다.", english: "Wuhan is a large central Chinese city where the Yangtze and Han rivers meet. Yellow Crane Tower and East Lake are among its well-known sights."),
        .init(id: "intl.cn.wuxi", ko: "중국 장쑤성의 타이호 호숫가에 있는 도시다. 호수 풍경과 운하, 전통 정원이 볼거리다.", english: "Wuxi is a city in Jiangsu Province on the shore of Lake Tai. Lake views, canals and traditional gardens are its main attractions."),
        .init(id: "intl.cn.xian", ko: "중국 산시성의 고도로 여러 왕조의 수도였던 역사 도시다. 진시황릉 병마용과 오래된 성벽이 대표 볼거리다.", english: "Xi’an is an ancient capital in Shaanxi Province that served several dynasties. The Terracotta Army and the old city walls are its signature sights."),
        .init(id: "intl.cn.xiamen", ko: "중국 푸젠성 남동 해안의 섬 도시다. 아열대 기후에 해안 산책로가 좋고 인근 구랑위섬의 옛 건축이 유명하다.", english: "Xiamen is an island city on the southeastern coast of Fujian Province. It has a mild subtropical climate, seaside walks and the old colonial buildings of nearby Gulangyu."),
        .init(id: "intl.cn.yancheng", ko: "중국 장쑤성 동부 황해 연안의 도시다. 넓은 갯벌과 습지가 있어 철새 도래지로 알려져 있다.", english: "Yancheng is a city on the Yellow Sea coast of eastern Jiangsu. Its wide tidal flats and wetlands are known as a stopover for migratory birds."),
        .init(id: "intl.cn.yanji", ko: "중국 지린성 옌볜 조선족 자치주의 중심 도시다. 한글 간판이 흔하고 한국 음식과 문화를 접할 수 있다.", english: "Yanji is the main city of the Yanbian Korean Autonomous Prefecture in Jilin Province. Korean signs are common, and Korean food and culture are easy to find."),
        .init(id: "intl.cn.yantai", ko: "중국 산둥반도 북쪽 해안의 항구 도시다. 해변과 포도주 산지로 알려져 있고 한국과 뱃길로 이어진다.", english: "Yantai is a port city on the northern coast of the Shandong Peninsula. It is known for its beaches and wine production, and is linked to Korea by sea routes."),
        .init(id: "intl.cn.yichang", ko: "중국 후베이성 창장강 변의 도시다. 싼샤 댐과 창장 싼샤 유람의 출발지로 알려져 있다.", english: "Yichang is a city on the Yangtze River in Hubei Province. It is known as the gateway to the Three Gorges Dam and Yangtze gorge cruises."),
        .init(id: "intl.cn.zhangjiajie", ko: "중국 후난성의 산악 관광 도시다. 하늘로 솟은 사암 기둥 봉우리 경관으로 알려진 국립삼림공원이 있다.", english: "Zhangjiajie is a mountain tourism city in Hunan Province. Its national forest park is known for towering sandstone pillar peaks."),
        .init(id: "intl.cn.zhengzhou", ko: "중국 허난성의 성도이며 철도가 모이는 교통 요지다. 가까이에 소림사와 옛 도읍 유적이 있다.", english: "Zhengzhou is the capital of Henan Province and a major railway junction. Shaolin Temple and ancient capital ruins lie within reach of the city."),
        .init(id: "intl.hk.hongkong", ko: "중국 남부 해안의 특별행정구로 빅토리아항을 끼고 있다. 고층 빌딩 야경과 피크 전망대, 딤섬 같은 음식이 유명하다.", english: "Hong Kong is a special administrative region on China’s southern coast, built around Victoria Harbour. It is known for its dense skyline, the Peak viewpoint and dim sum."),
        .init(id: "intl.mo.macau", ko: "중국 남부 주장강 어귀의 특별행정구다. 포르투갈 시대의 옛 거리와 성당 유적, 대형 카지노 리조트가 공존한다.", english: "Macau is a special administrative region at the mouth of the Pearl River. Portuguese-era streets and church ruins sit alongside large casino resorts."),
        .init(id: "intl.tw.taipei", ko: "타이완의 수도이자 최대 도시다. 타이베이 101과 고궁박물원, 야시장이 대표 볼거리다.", english: "Taipei is the capital and largest city of Taiwan. Taipei 101, the National Palace Museum and its night markets are the main draws."),
        .init(id: "intl.tw.kaohsiung", ko: "타이완 남부의 항구 도시로 큰 무역항이 있다. 항구 주변 예술 지구와 롄츠탄 호수가 볼거리다.", english: "Kaohsiung is a port city in southern Taiwan with a major harbor. The waterfront art districts and Lotus Pond are popular sights."),
        .init(id: "intl.tw.taichung", ko: "타이완 중서부의 대도시로 기후가 온화하다. 무지개 마을과 문화 시설, 펑지아 야시장 등이 알려져 있다.", english: "Taichung is a large city in west-central Taiwan with a mild climate. It is known for its Rainbow Village, cultural venues and Fengjia night market."),
        .init(id: "intl.mn.ulaanbaatar", ko: "몽골의 수도이자 최대 도시다. 간단사 같은 불교 사원과 박물관이 있고 근교에서 초원과 유목 문화를 접할 수 있다.", english: "Ulaanbaatar is the capital and largest city of Mongolia. It has Buddhist monasteries such as Gandan and museums, with steppe and nomadic culture just outside the city."),
        .init(id: "intl.vn.danang", ko: "베트남 중부 동해안의 항구 도시다. 긴 해변과 바나힐, 대리석 산이 있으며 호이안과도 가깝다.", english: "Da Nang is a port city on Vietnam’s central coast. It has a long beach, Ba Na Hills and the Marble Mountains, and is close to Hoi An."),
        .init(id: "intl.vn.hanoi", ko: "베트남의 수도로 북부 홍강 유역에 있다. 호안끼엠 호수와 구시가지, 프랑스 식민 시대 건물이 어우러진다.", english: "Hanoi is the capital of Vietnam, on the Red River in the north. Hoan Kiem Lake, the Old Quarter and French colonial buildings define its look."),
        .init(id: "intl.vn.hochiminh", ko: "베트남 남부의 최대 도시로 옛 이름은 사이공이다. 벤탄 시장과 노트르담 대성당, 전쟁 박물관이 알려져 있다.", english: "Ho Chi Minh City is the largest city in southern Vietnam, formerly called Saigon. Ben Thanh Market, the Notre-Dame Cathedral and the War Remnants Museum are well known."),
        .init(id: "intl.vn.nhatrang", ko: "베트남 남중부 해안의 휴양 도시다. 긴 해변과 섬 투어, 머드 온천이 인기 있다.", english: "Nha Trang is a resort city on Vietnam’s south-central coast. Its long beach, island boat tours and mud baths attract visitors."),
        .init(id: "intl.vn.phuquoc", ko: "베트남 남서쪽 타이만에 있는 가장 큰 섬이다. 흰 모래 해변과 리조트, 후추와 액젓 생산으로 알려져 있다.", english: "Phu Quoc is Vietnam’s largest island, in the Gulf of Thailand off the southwest coast. It is known for white-sand beaches, resorts, pepper farms and fish sauce."),
        .init(id: "intl.th.bangkok", ko: "태국의 수도로 짜오프라야강을 끼고 있다. 왕궁과 왓 아룬 같은 사원, 수상 시장과 길거리 음식이 유명하다.", english: "Bangkok is the capital of Thailand, set along the Chao Phraya River. It is known for the Grand Palace, temples such as Wat Arun, floating markets and street food."),
        .init(id: "intl.th.chiangmai", ko: "태국 북부 산악 지대의 옛 란나 왕국 도시다. 구시가지의 사원과 야시장, 주변 산지의 코끼리 보호 시설이 알려져 있다.", english: "Chiang Mai is a city in northern Thailand and the old capital of the Lanna Kingdom. Its walled old town has many temples and night markets, with mountains and elephant sanctuaries nearby."),
        .init(id: "intl.th.phuket", ko: "태국 남부 안다만해의 가장 큰 섬이다. 여러 해변과 리조트, 주변 섬으로 가는 보트 투어가 인기다.", english: "Phuket is Thailand’s largest island, in the Andaman Sea. It offers many beaches, resorts and boat trips to nearby islands."),
        .init(id: "intl.ph.manila", ko: "필리핀의 수도로 루손섬 마닐라만에 있다. 스페인 식민 시대의 성곽 도시 인트라무로스가 대표 유적이다.", english: "Manila is the capital of the Philippines, on Manila Bay in Luzon. Intramuros, the walled city from the Spanish colonial era, is its main historic site."),
        .init(id: "intl.ph.cebu", ko: "필리핀 중부 비사야 제도의 섬이자 도시다. 스페인 시대 유적과 인근 바다의 다이빙, 고래상어 관광으로 알려져 있다.", english: "Cebu is an island and city in the central Visayas of the Philippines. It has Spanish-era landmarks and is known for diving and whale shark encounters nearby."),
        .init(id: "intl.ph.clark", ko: "필리핀 루손섬 중부 팜팡가주의 옛 미군 기지 지역이다. 국제공항과 골프장, 카지노 리조트가 있다.", english: "Clark is a former U.S. air base area in Pampanga in central Luzon. It now has an international airport, golf courses and casino resorts."),
        .init(id: "intl.ph.boracay", ko: "필리핀 중부 비사야 제도의 작은 섬이다. 고운 흰 모래의 화이트 비치와 해 질 녘 풍경이 알려져 있다.", english: "Boracay is a small island in the central Visayas of the Philippines. It is known for fine white sand at White Beach and its sunsets."),
        .init(id: "intl.ph.bohol", ko: "필리핀 비사야 제도의 섬이다. 언덕이 원뿔 모양으로 늘어선 초콜릿 힐스와 안경원숭이로 알려져 있다.", english: "Bohol is an island in the Visayas of the Philippines. It is known for the cone-shaped Chocolate Hills and the tiny tarsier."),
        .init(id: "intl.my.kualalumpur", ko: "말레이시아의 수도이자 최대 도시다. 페트로나스 트윈 타워와 바투 동굴, 다민족 음식 문화가 대표적이다.", english: "Kuala Lumpur is the capital and largest city of Malaysia. The Petronas Twin Towers, Batu Caves and its multi-ethnic food scene stand out."),
        .init(id: "intl.my.kotakinabalu", ko: "말레이시아 보르네오섬 사바주의 도시다. 키나발루산 등반의 관문이며 인근 섬과 해변, 해넘이로 알려져 있다.", english: "Kota Kinabalu is a city in Sabah on Borneo, Malaysia. It is the gateway to Mount Kinabalu and is known for nearby islands, beaches and sunsets."),
        .init(id: "intl.sg.singapore", ko: "말레이반도 끝에 있는 도시국가다. 마리나 베이 샌즈와 가든스 바이 더 베이, 깨끗한 거리와 다양한 음식이 알려져 있다.", english: "Singapore is a city-state at the southern tip of the Malay Peninsula. It is known for Marina Bay Sands, Gardens by the Bay, clean streets and varied food."),
        .init(id: "intl.id.bali", ko: "인도네시아의 힌두교 문화가 이어지는 섬이다. 해변과 계단식 논, 바다 사원이 볼거리다.", english: "Bali is an Indonesian island with a living Hindu culture. Beaches, terraced rice fields and sea temples are its highlights."),
        .init(id: "intl.id.jakarta", ko: "인도네시아의 수도로 자바섬 북서부 해안에 있다. 네덜란드 식민 시대의 구시가 코타 투아와 독립 기념탑이 있다.", english: "Jakarta is the capital of Indonesia, on the northwest coast of Java. It has the Dutch colonial old town of Kota Tua and the National Monument."),
        .init(id: "intl.id.batam", ko: "인도네시아 리아우 제도의 섬으로 싱가포르에서 배로 가깝다. 리조트와 해산물 식당이 있어 짧은 휴양지로 찾는다.", english: "Batam is an island in Indonesia’s Riau Islands, a short ferry ride from Singapore. Resorts and seafood restaurants make it a popular short getaway."),
        .init(id: "intl.kh.phnompenh", ko: "캄보디아의 수도로 메콩강과 톤레삽강이 만나는 곳에 있다. 왕궁과 은 사원, 국립박물관이 대표 볼거리다.", english: "Phnom Penh is the capital of Cambodia, where the Mekong and Tonle Sap rivers meet. The Royal Palace, Silver Pagoda and National Museum are its main sights."),
        .init(id: "intl.la.vientiane", ko: "라오스의 수도로 메콩강변에 자리한다. 불탑 탓 루앙과 개선문 모양의 빠뚜싸이가 대표 명소다.", english: "Vientiane is the capital of Laos, on the bank of the Mekong River. That Luang stupa and the Patuxai monument are its best-known landmarks."),
        .init(id: "intl.mm.yangon", ko: "미얀마 최대 도시이자 옛 수도다. 황금빛 쉐다곤 파고다와 식민 시대 건물이 남아 있다.", english: "Yangon is Myanmar’s largest city and former capital. The golden Shwedagon Pagoda and colonial-era buildings remain in the city."),
        .init(id: "intl.np.kathmandu", ko: "네팔의 수도로 히말라야 기슭 분지에 있다. 더르바르 광장과 불탑 스와얌부나트 등 힌두·불교 유적이 모여 있다.", english: "Kathmandu is the capital of Nepal, in a valley at the foot of the Himalayas. Durbar Square and the Swayambhunath stupa are among its Hindu and Buddhist heritage sites."),
        .init(id: "intl.bd.dhaka", ko: "방글라데시의 수도로 부리강가강 변에 있다. 올드 다카의 무굴 시대 유적과 붐비는 시장, 릭샤 거리가 특징이다.", english: "Dhaka is the capital of Bangladesh, on the Buriganga River. Old Dhaka’s Mughal-era sites, crowded markets and rickshaw streets give it its character."),
        .init(id: "intl.in.delhi", ko: "인도의 수도권 대도시로 올드델리와 뉴델리로 나뉜다. 붉은 요새와 후마윤 묘, 인도 문 같은 유적이 있다.", english: "Delhi is India’s capital region, split into Old Delhi and New Delhi. Sights include the Red Fort, Humayun’s Tomb and India Gate."),
        .init(id: "intl.kz.almaty", ko: "카자흐스탄 남동부 톈산 산맥 기슭의 최대 도시다. 옛 수도로 공원과 산악 전망, 근교 스키장이 알려져 있다.", english: "Almaty is the largest city in Kazakhstan, at the foot of the Tian Shan mountains. A former capital, it is known for parks, mountain views and nearby ski areas."),
        .init(id: "intl.kz.astana", ko: "카자흐스탄의 수도로 북부 초원 지대에 있다. 독특한 현대 건축물과 바이테렉 탑이 도시 경관을 이룬다.", english: "Astana is the capital of Kazakhstan, on the northern steppe. Its distinctive modern architecture and the Baiterek tower shape the skyline."),
        .init(id: "intl.uz.tashkent", ko: "우즈베키스탄의 수도로 중앙아시아의 큰 도시다. 옛 이슬람 건축과 소련 시대 건물, 지하철역 장식, 재래시장이 볼만하다.", english: "Tashkent is the capital of Uzbekistan and a major city of Central Asia. Islamic architecture, Soviet-era buildings, decorated metro stations and bazaars are worth seeing."),
        .init(id: "intl.ae.dubai", ko: "아랍에미리트의 페르시아만 연안 도시다. 세계에서 가장 높은 건물로 알려진 부르즈 할리파와 사막 체험, 대형 쇼핑몰이 있다.", english: "Dubai is a Persian Gulf city in the United Arab Emirates. It has the Burj Khalifa, a very tall skyscraper, along with desert excursions and large shopping malls."),
        .init(id: "intl.ae.abudhabi", ko: "아랍에미리트의 수도로 페르시아만의 섬 위에 있다. 흰 대리석의 셰이크 자이드 그랜드 모스크가 대표 명소다.", english: "Abu Dhabi is the capital of the United Arab Emirates, partly on an island in the Persian Gulf. The white marble Sheikh Zayed Grand Mosque is its signature landmark."),
        .init(id: "intl.qa.doha", ko: "카타르의 수도로 페르시아만 연안에 있다. 이슬람 미술관과 전통 시장 수크 와키프, 현대적 해안 스카이라인이 볼거리다.", english: "Doha is the capital of Qatar, on the Persian Gulf coast. The Museum of Islamic Art, the traditional Souq Waqif and a modern waterfront skyline are the highlights."),
        .init(id: "intl.il.telaviv", ko: "이스라엘 지중해 연안의 도시다. 해변과 바우하우스 양식 건물이 많은 백색 도시 지구, 활기찬 카페 문화가 특징이다.", english: "Tel Aviv is a Mediterranean coastal city in Israel. It is known for its beaches, the Bauhaus-style White City district and a lively cafe scene."),
        .init(id: "intl.tr.istanbul", ko: "튀르키예 보스포루스 해협을 사이에 두고 유럽과 아시아에 걸친 도시다. 아야소피아와 블루 모스크, 그랜드 바자르가 대표 명소다.", english: "Istanbul is a Turkish city spanning Europe and Asia across the Bosphorus Strait. Hagia Sophia, the Blue Mosque and the Grand Bazaar are its landmarks."),
        .init(id: "intl.et.addisababa", ko: "에티오피아의 수도로 고원 지대에 있다. 아프리카 연합 본부가 있으며 국립박물관과 시장, 에티오피아식 커피 문화로 알려져 있다.", english: "Addis Ababa is the capital of Ethiopia, set on a high plateau. It hosts the African Union headquarters and is known for its National Museum, markets and coffee culture."),
        .init(id: "intl.gb.london", ko: "영국의 수도로 템스강을 끼고 있다. 웨스트민스터 궁과 빅벤, 타워 브리지, 대영박물관이 대표 볼거리다.", english: "London is the capital of the United Kingdom, on the River Thames. The Palace of Westminster with Big Ben, Tower Bridge and the British Museum are major sights."),
        .init(id: "intl.fr.paris", ko: "프랑스의 수도로 센강 변에 있다. 에펠탑과 루브르 박물관, 노트르담 대성당 등 예술과 건축 명소가 많다.", english: "Paris is the capital of France, on the Seine. The Eiffel Tower, the Louvre and Notre-Dame Cathedral are among its many art and architecture sights."),
        .init(id: "intl.de.frankfurt", ko: "독일 헤센주의 금융 중심 도시로 마인강 변에 있다. 고층 빌딩 스카이라인과 옛 시청 광장 뢰머, 유럽 주요 공항이 있다.", english: "Frankfurt is a financial center in Hesse, Germany, on the River Main. It combines a high-rise skyline, the old Römer square and one of Europe’s major airports."),
        .init(id: "intl.de.munich", ko: "독일 바이에른주의 중심 도시다. 마리엔 광장과 영국 정원, 옥토버페스트 맥주 축제로 알려져 있다.", english: "Munich is the main city of Bavaria in Germany. It is known for Marienplatz, the English Garden and the Oktoberfest beer festival."),
        .init(id: "intl.at.vienna", ko: "오스트리아의 수도로 도나우강 변에 있다. 쇤브룬 궁전과 슈테판 대성당, 오페라와 클래식 음악 전통이 유명하다.", english: "Vienna is the capital of Austria, on the Danube. It is known for Schönbrunn Palace, St. Stephen’s Cathedral and a deep tradition of opera and classical music."),
        .init(id: "intl.ch.zurich", ko: "스위스 최대 도시로 취리히호수 끝에 있다. 금융 중심지이며 구시가지 골목과 호수 산책로가 볼거리다.", english: "Zurich is Switzerland’s largest city, at the northern end of Lake Zurich. It is a financial hub with an old town of narrow lanes and pleasant lakeside walks."),
        .init(id: "intl.nl.amsterdam", ko: "네덜란드의 수도로 운하가 도시를 둘러싼다. 반 고흐 미술관과 안네 프랑크의 집, 좁은 운하 주택이 볼거리다.", english: "Amsterdam is the capital of the Netherlands, crisscrossed by canals. The Van Gogh Museum, the Anne Frank House and narrow canal houses are highlights."),
        .init(id: "intl.it.rome", ko: "이탈리아의 수도로 고대 로마 제국의 중심이었다. 콜로세움과 포로 로마노, 바티칸의 성베드로 대성당이 가깝다.", english: "Rome is the capital of Italy and was the center of the ancient Roman Empire. The Colosseum, the Roman Forum and Vatican’s St. Peter’s Basilica are nearby."),
        .init(id: "intl.it.milan", ko: "이탈리아 북부 롬바르디아의 중심 도시다. 고딕 양식의 두오모와 스칼라 극장, 패션과 디자인 산업으로 알려져 있다.", english: "Milan is the main city of Lombardy in northern Italy. It is known for its Gothic Duomo, La Scala opera house and its fashion and design industries."),
        .init(id: "intl.es.madrid", ko: "스페인의 수도로 이베리아반도 중앙 고원에 있다. 프라도 미술관과 왕궁, 마요르 광장이 대표 명소다.", english: "Madrid is the capital of Spain, on the central plateau of the Iberian Peninsula. The Prado Museum, the Royal Palace and Plaza Mayor are its main sights."),
        .init(id: "intl.es.barcelona", ko: "스페인 카탈루냐의 지중해 연안 도시다. 가우디가 설계한 사그라다 파밀리아와 구엘 공원, 고딕 지구가 알려져 있다.", english: "Barcelona is a Mediterranean city in Catalonia, Spain. It is known for Gaudí’s Sagrada Família and Park Güell, and for its Gothic Quarter."),
        .init(id: "intl.pt.lisbon", ko: "포르투갈의 수도로 테주강 하구의 언덕에 있다. 노란 트램과 벨렝 탑, 알파마의 옛 골목이 볼거리다.", english: "Lisbon is the capital of Portugal, spread over hills at the mouth of the Tagus. Yellow trams, Belém Tower and the old lanes of Alfama are highlights."),
        .init(id: "intl.cz.prague", ko: "체코의 수도로 블타바강 변에 있다. 프라하성과 카를교, 구시가 광장 등 중세 건축이 잘 남아 있다.", english: "Prague is the capital of the Czech Republic, on the Vltava River. Medieval architecture survives well, including Prague Castle, Charles Bridge and Old Town Square."),
        .init(id: "intl.hu.budapest", ko: "헝가리의 수도로 도나우강을 사이에 두고 부다와 페슈트로 나뉜다. 국회의사당과 온천, 강변 야경이 유명하다.", english: "Budapest is the capital of Hungary, divided by the Danube into Buda and Pest. The Parliament building, thermal baths and riverside night views are well known."),
        .init(id: "intl.pl.warsaw", ko: "폴란드의 수도로 비스와강 변에 있다. 전쟁 후 복원된 구시가지와 쇼팽 관련 명소가 알려져 있다.", english: "Warsaw is the capital of Poland, on the Vistula River. Its old town, rebuilt after the war, and sites linked to Chopin are well known."),
        .init(id: "intl.pl.wroclaw", ko: "폴란드 남서부 오데르강 변의 도시다. 알록달록한 건물이 둘러싼 시장 광장과 다리, 난쟁이 조각상으로 알려져 있다.", english: "Wrocław is a city on the Oder River in southwestern Poland. It is known for a market square lined with colorful buildings, many bridges and small dwarf statues."),
        .init(id: "intl.fi.helsinki", ko: "핀란드의 수도로 발트해 연안에 있다. 헬싱키 대성당과 암석 교회, 디자인 지구와 항구 시장이 볼거리다.", english: "Helsinki is the capital of Finland, on the Baltic Sea coast. Helsinki Cathedral, the Rock Church, the design district and the harbor market are highlights."),
        .init(id: "intl.no.oslo", ko: "노르웨이의 수도로 오슬로 피오르드 안쪽에 있다. 바이킹선 박물관과 오페라 하우스, 비겔란 조각 공원이 대표 명소다.", english: "Oslo is the capital of Norway, at the head of the Oslo Fjord. The Viking Ship Museum, the Opera House and Vigeland Sculpture Park are main attractions."),
        .init(id: "intl.gr.athens", ko: "그리스의 수도로 서양 문명의 발상지 중 하나다. 아크로폴리스와 파르테논 신전, 고대 아고라가 대표 유적이다.", english: "Athens is the capital of Greece and a cradle of Western civilization. The Acropolis, the Parthenon and the Ancient Agora are its key ruins."),
        .init(id: "intl.us.newyork", ko: "미국 동부 해안의 최대 도시로 허드슨강 어귀에 있다. 자유의 여신상과 센트럴 파크, 타임스 스퀘어, 브로드웨이가 유명하다.", english: "New York is the largest city in the United States, at the mouth of the Hudson River. The Statue of Liberty, Central Park, Times Square and Broadway are famous."),
        .init(id: "intl.us.losangeles", ko: "미국 캘리포니아 남부의 대도시다. 할리우드와 산타모니카 해변, 그리피스 천문대가 대표 볼거리다.", english: "Los Angeles is a large city in Southern California. Hollywood, Santa Monica beach and Griffith Observatory are among its best-known sights."),
        .init(id: "intl.us.sanfrancisco", ko: "미국 캘리포니아 북부 샌프란시스코만의 언덕 도시다. 금문교와 케이블카, 앨커트래즈 섬이 알려져 있다.", english: "San Francisco is a hilly city on San Francisco Bay in Northern California. The Golden Gate Bridge, cable cars and Alcatraz Island are well known."),
        .init(id: "intl.us.seattle", ko: "미국 워싱턴주 퓨짓 사운드 연안의 도시다. 스페이스 니들과 파이크 플레이스 시장, 커피 문화로 알려져 있다.", english: "Seattle is a city on Puget Sound in Washington State. It is known for the Space Needle, Pike Place Market and its coffee culture."),
        .init(id: "intl.us.lasvegas", ko: "미국 네바다주 사막에 있는 오락 도시다. 스트립 거리의 대형 호텔과 카지노, 쇼와 야경으로 유명하다.", english: "Las Vegas is an entertainment city in the Nevada desert. It is famous for the big hotels and casinos along the Strip, live shows and bright night views."),
        .init(id: "intl.us.honolulu", ko: "미국 하와이주의 주도로 오아후섬 남쪽 해안에 있다. 와이키키 해변과 다이아몬드 헤드, 진주만 기념관이 대표 명소다.", english: "Honolulu is the capital of Hawaii, on the south shore of Oahu. Waikiki Beach, Diamond Head and the Pearl Harbor memorials are its main sights."),
        .init(id: "intl.us.chicago", ko: "미국 중서부 미시간호 연안의 대도시다. 고층 건축물과 밀레니엄 파크, 시카고 미술관이 알려져 있다.", english: "Chicago is a major Midwestern city on Lake Michigan. It is known for its skyscraper architecture, Millennium Park and the Art Institute of Chicago."),
        .init(id: "intl.us.atlanta", ko: "미국 남동부 조지아주의 주도다. 세계적 허브 공항이 있으며 마틴 루서 킹 국립역사지구와 조지아 수족관이 있다.", english: "Atlanta is the capital of Georgia in the southeastern United States. It has a major airport hub, the Martin Luther King Jr. National Historical Park and the Georgia Aquarium."),
        .init(id: "intl.us.boston", ko: "미국 매사추세츠주의 주도로 독립 혁명의 역사가 깊다. 프리덤 트레일과 하버드 대학, 펜웨이 파크가 알려져 있다.", english: "Boston is the capital of Massachusetts, with deep roots in the American Revolution. The Freedom Trail, nearby Harvard University and Fenway Park are well known."),
        .init(id: "intl.us.dallas", ko: "미국 텍사스주 북부의 대도시다. 케네디 대통령 관련 역사 전시와 아트 지구, 카우보이 문화가 알려져 있다.", english: "Dallas is a large city in northern Texas. It is known for historic exhibits tied to President Kennedy, an arts district and cowboy culture."),
        .init(id: "intl.us.detroit", ko: "미국 미시간주의 도시로 자동차 산업의 중심이었다. 헨리 포드 박물관과 모타운 음악 유산이 알려져 있다.", english: "Detroit is a Michigan city long at the center of the American auto industry. It is known for The Henry Ford museum and its Motown music heritage."),
        .init(id: "intl.us.minneapolis", ko: "미국 미네소타주 미시시피강 변의 도시다. 호수와 공원이 많고 인근 쌍둥이 도시 세인트폴과 함께 대도시권을 이룬다.", english: "Minneapolis is a Minnesota city on the Mississippi River. It has many lakes and parks and forms a metro area with its twin city, St. Paul."),
        .init(id: "intl.us.saltlake", ko: "미국 유타주의 주도로 로키산맥 기슭에 있다. 템플 스퀘어와 그레이트솔트호, 가까운 스키장으로 알려져 있다.", english: "Salt Lake City is the capital of Utah, at the foot of the Rocky Mountains. It is known for Temple Square, the Great Salt Lake and nearby ski resorts."),
        .init(id: "intl.us.washington", ko: "미국의 수도로 포토맥강 변에 있다. 백악관과 국회의사당, 내셔널 몰의 기념비와 스미스소니언 박물관들이 대표 명소다.", english: "Washington, D.C. is the capital of the United States, on the Potomac River. The White House, the Capitol, the monuments on the National Mall and the Smithsonian museums are key sights."),
        .init(id: "intl.gu.guam", ko: "서태평양 마리아나 제도의 미국령 섬이다. 투몬만 해변과 리조트, 쇼핑이 알려져 있고 한국에서 가까운 휴양지다.", english: "Guam is a U.S. territory in the Mariana Islands of the western Pacific. Tumon Bay’s beaches, resorts and shopping make it a popular getaway not far from Korea."),
        .init(id: "intl.mp.saipan", ko: "서태평양 북마리아나 제도의 중심 섬이다. 마나가하 섬과 마이크로 비치 같은 맑은 바다와 다이빙 명소가 있다.", english: "Saipan is the main island of the Northern Mariana Islands in the western Pacific. Clear waters at Managaha Island and Micro Beach and good diving sites are its draws."),
        .init(id: "intl.ca.vancouver", ko: "캐나다 서부 브리티시컬럼비아주의 항구 도시다. 산과 바다가 가까워 스탠리 파크와 개스타운이 알려져 있다.", english: "Vancouver is a port city in British Columbia on Canada’s west coast. Mountains and sea lie close together, and Stanley Park and Gastown are popular spots."),
        .init(id: "intl.ca.toronto", ko: "캐나다 최대 도시로 온타리오호 북쪽 연안에 있다. CN 타워와 다민족 지역 문화, 나이아가라 폭포 방문의 거점이다.", english: "Toronto is Canada’s largest city, on the northern shore of Lake Ontario. It has the CN Tower and diverse neighborhoods, and serves as a base for visiting Niagara Falls."),
        .init(id: "intl.ca.montreal", ko: "캐나다 퀘벡주의 최대 도시로 프랑스어 문화권이다. 올드 몬트리올의 돌 건물과 노트르담 대성당이 볼거리다.", english: "Montreal is the largest city in Quebec, Canada, with a French-speaking culture. Old Montreal’s stone buildings and Notre-Dame Basilica are highlights."),
        .init(id: "intl.mx.mexicocity", ko: "멕시코의 수도로 높은 고원 분지에 있다. 소칼로 광장과 국립 인류학 박물관, 아즈텍 시대의 유적이 대표적이다.", english: "Mexico City is the capital of Mexico, in a high-altitude basin. The Zócalo, the National Museum of Anthropology and Aztec-era ruins are among its main sights."),
        .init(id: "intl.au.sydney", ko: "오스트레일리아 동남부 해안의 최대 도시다. 시드니 오페라 하우스와 하버 브리지, 본다이 해변이 대표 명소다.", english: "Sydney is Australia’s largest city, on the southeastern coast. The Opera House, Harbour Bridge and Bondi Beach are its signature sights."),
        .init(id: "intl.au.melbourne", ko: "오스트레일리아 남동부 빅토리아주의 도시다. 골목 카페와 벽화 거리, 트램, 스포츠 경기장이 알려져 있다.", english: "Melbourne is a city in Victoria, southeastern Australia. It is known for laneway cafes, street art, trams and major sports venues."),
        .init(id: "intl.au.brisbane", ko: "오스트레일리아 퀸즐랜드주의 주도로 브리즈번강을 끼고 있다. 아열대 기후이며 강변 공원과 코알라 보호구역이 알려져 있다.", english: "Brisbane is the capital of Queensland, Australia, along the Brisbane River. It has a subtropical climate, riverside parks and koala sanctuaries."),
        .init(id: "intl.nz.auckland", ko: "뉴질랜드 북섬의 최대 도시로 두 개의 항구 사이에 있다. 스카이 타워와 화산 언덕, 항구의 요트 풍경이 알려져 있다.", english: "Auckland is the largest city on New Zealand’s North Island, set between two harbors. The Sky Tower, volcanic hills and harbor sailing scenes are well known."),
        .init(id: "kr.baekyangsa", ko: "전남 장성 내장산 자락에 있는 사찰이다. 경내 쌍계루와 연못에 비친 단풍 풍경으로 가을에 많이 찾는다.", english: "A temple at the foot of Naejangsan in Jangseong, South Jeolla. It is especially visited in autumn for the maples reflected in its pond by Ssangyeru Pavilion."),
        .init(id: "kr.hwaeomsa", ko: "전남 구례 지리산 남쪽 자락에 있는 큰 사찰이다. 국보인 각황전을 비롯해 여러 문화유산이 있고 봄에는 홍매화로 알려져 있다.", english: "A large temple on the southern slope of Jirisan in Gurye, South Jeolla. It holds the national treasure Gakhwangjeon Hall among many cultural properties and is known for its red plum blossoms in spring."),
        .init(id: "kr.cheoneunsa", ko: "전남 구례 지리산 남쪽에 있는 오래된 사찰이다. 근처 저수지와 숲길이 조용해 산책하기 좋다.", english: "An old temple on the southern side of Jirisan in Gurye, South Jeolla. The nearby reservoir and forest paths make for quiet walks."),
        .init(id: "kr.mihwangsa", ko: "전남 해남 달마산 아래에 있는 사찰이다. 대웅보전 너머로 바다와 섬 위로 지는 해를 볼 수 있다.", english: "A temple below Dalmasan in Haenam, South Jeolla. From its main hall you can watch the sun set over the sea and islands."),
        .init(id: "kr.jikjisa", ko: "경북 김천 황악산 자락에 있는 큰 사찰이다. 신라 시대에 세워졌다고 전하며 불교 조계종의 중심 사찰 가운데 하나다.", english: "A large temple at the foot of Hwangaksan in Gimcheon, North Gyeongsang. Tradition dates it to the Silla period, and it is one of the major temples of the Jogye Order."),
        .init(id: "kr.unmunsa", ko: "경북 청도 운악산 자락에 있는 사찰로 비구니 스님이 공부하는 승가대학으로 알려져 있다. 소나무 숲길과 고즈넉한 경내가 특징이다.", english: "A temple in Cheongdo, North Gyeongsang, known as a monastic college for Buddhist nuns. It is noted for its pine-lined approach and tranquil grounds."),
        .init(id: "kr.sinheungsa", ko: "강원 속초 설악산 국립공원 입구에 있는 사찰이다. 입구의 통일대불이 눈에 띄고 권금성과 울산바위로 가는 길목이다.", english: "A temple at the entrance of Seoraksan National Park in Sokcho, Gangwon. The large Unification Buddha stands out, and it is a gateway to Gwongeumseong and Ulsanbawi."),
        .init(id: "kr.geonbongsa", ko: "강원 고성에 있는 신라 시대에 창건되었다고 전하는 사찰이다. 민통선 가까이에 있어 한국 전쟁의 아픔이 남아 있고 불이문과 능파교가 볼거리다.", english: "A temple in Goseong, Gangwon, said to have been founded in the Silla period. It lies near the civilian control zone and still bears marks of the Korean War, with Burimun Gate and Neungpagyo Bridge as sights."),
        .init(id: "kr.cheongpyeongsa", ko: "강원 춘천 소양호 가까운 오봉산 자락에 있는 사찰이다. 고려 시대 이자현이 머문 곳으로 알려져 있고 회전문과 정원 유적이 남아 있다.", english: "A temple on Obongsan near Soyang Lake in Chuncheon, Gangwon. It is associated with the Goryeo-era scholar Yi Ja-hyeon and keeps its Hoejeonmun Gate and garden remains."),
        .init(id: "kr.gapsa", ko: "충남 공주 계룡산 자락에 있는 사찰이다. 백제 시대에 세워졌다고 전하며 입구의 숲길과 계곡이 아름답다.", english: "A temple at the foot of Gyeryongsan in Gongju, South Chungcheong. Tradition dates it to the Baekje period, and its forest approach and valley are pleasant."),
        .init(id: "kr.donghaksa", ko: "충남 공주 계룡산 동쪽 계곡에 있는 사찰이다. 비구니 승가대학이 있는 곳으로 알려져 있고 봄에는 벚꽃길이 이어진다.", english: "A temple in the eastern valley of Gyeryongsan in Gongju, South Chungcheong. It is known for a Buddhist nuns college, and a cherry blossom road leads to it in spring."),
        .init(id: "kr.boriam", ko: "경남 남해 금산 정상 가까이에 있는 암자다. 바다와 섬이 내려다보이는 전망과 해돋이로 널리 알려져 있다.", english: "A hermitage near the summit of Geumsan in Namhae, South Gyeongsang. It is well known for sweeping views over the sea and islands and for its sunrises."),
        .init(id: "kr.daewonsa", ko: "경남 산청 지리산 동쪽 자락에 있는 사찰이다. 비구니 스님이 수행하는 곳으로 알려져 있고 계곡 풍경이 맑다.", english: "A temple on the eastern slope of Jirisan in Sancheong, South Gyeongsang. It is known as a practice site for Buddhist nuns and sits beside a clear valley stream."),
        .init(id: "kr.gwaneumsa", ko: "제주시 한라산 북쪽 자락에 있는 제주의 대표 사찰이다. 4·3 사건 때 큰 피해를 입었으나 다시 세워졌으며 숲으로 둘러싸여 조용하다.", english: "A major temple on the northern slope of Hallasan in Jeju City. It was badly damaged during the Jeju 4.3 events and later rebuilt, and it sits quietly among the trees."),
        .init(id: "kr.yakcheonsa", ko: "제주 서귀포 대포동 바닷가 가까이에 있는 큰 사찰이다. 웅장한 대적광전이 눈에 띄고 제주 남쪽 바다를 내려다본다.", english: "A large temple near the coast of Daepo-dong in Seogwipo, Jeju. Its imposing main hall stands out above the southern sea."),
        .init(id: "kr.myeongjisan", ko: "경기 가평에 있는 높은 산으로 경기도에서 손꼽히는 높이다. 계곡과 폭포가 많아 여름 산행과 가을 단풍으로 찾는다.", english: "A tall mountain in Gapyeong, Gyeonggi, among the higher peaks in the province. Its many valleys and falls draw hikers in summer and for autumn foliage."),
        .init(id: "kr.unaksan", ko: "경기 가평과 포천에 걸친 산으로 바위 봉우리가 뾰족하다. 산중에 현등사가 있고 구름다리와 가을 풍경이 알려져 있다.", english: "A mountain spanning Gapyeong and Pocheon, Gyeonggi, with jagged rocky peaks. Hyeondeungsa Temple lies on it, and it is known for its suspension bridge and autumn colors."),
        .init(id: "kr.soyosan", ko: "경기 동두천에 있는 산으로 수도권에서 가까워 당일 산행지로 인기다. 자재암과 폭포, 가을 단풍이 알려져 있다.", english: "A mountain in Dongducheon, Gyeonggi, close to the capital area and popular for day hikes. Jajaeam Hermitage, its falls and the autumn foliage are well known."),
        .init(id: "kr.gamaksan", ko: "경기 파주와 양주 사이에 있는 산이다. 정상 부근에 감악산 비가 있고 출렁다리와 전망이 알려져 있다.", english: "A mountain between Paju and Yangju in Gyeonggi. A historic stele stands near its summit, and a suspension bridge and views are well known."),
        .init(id: "kr.yumyeongsan", ko: "경기 가평에 있는 산으로 자연휴양림이 있다. 숲길이 완만해 가족 산행과 패러글라이딩, 강변 드라이브로 알려져 있다.", english: "A mountain in Gapyeong, Gyeonggi, with a natural recreation forest. Gentle forest trails suit family hikes, and it is known for paragliding and riverside drives."),
        .init(id: "kr.yongmunsan", ko: "경기 양평에 있는 산으로 용문사가 자리한다. 용문사 은행나무는 매우 오래된 노거수로 가을 단풍철에 많이 찾는다.", english: "A mountain in Yangpyeong, Gyeonggi, home to Yongmunsa Temple. Its ancient ginkgo tree draws many visitors in autumn."),
        .init(id: "kr.gyebangsan", ko: "강원 평창과 홍천에 걸친 높은 산이다. 겨울 눈꽃 산행으로 알려져 있고 정상 가까이까지 차로 올라 능선을 걸을 수 있다.", english: "A high mountain spanning Pyeongchang and Hongcheon in Gangwon. It is known for winter snow-flower hikes, and one can drive near the top before walking the ridge."),
        .init(id: "kr.bangtaesan", ko: "강원 인제에 있는 산으로 깊은 계곡과 숲이 잘 보존되어 있다. 자연휴양림과 가을 단풍, 여름 계곡 물놀이로 알려져 있다.", english: "A mountain in Inje, Gangwon, with deep, well-preserved valleys and forests. It is known for a recreation forest, autumn foliage and summer valley swimming."),
        .init(id: "kr.jeombongsan", ko: "강원 설악산 남쪽에 이어진 산으로 보호 구역으로 관리된다. 곰배령 야생화 군락이 알려져 있어 예약해야 들어갈 수 있다.", english: "A mountain south of Seoraksan in Gangwon, managed as a protected area. Its Gombaeryeong wildflower meadows are famous, and entry requires a reservation."),
        .init(id: "kr.gariwangsan", ko: "강원 정선에 있는 높은 산으로 원시림이 남아 있다. 평창 겨울올림픽 알파인 스키 경기가 열린 곳이며 케이블카와 숲길이 있다.", english: "A high mountain in Jeongseon, Gangwon, with remnants of old-growth forest. It hosted the alpine skiing events of the Pyeongchang Winter Olympics and has a gondola and forest trails."),
        .init(id: "kr.geumsusan", ko: "충북 단양에 있는 산으로 이름처럼 비단에 수놓은 듯한 가을 풍경으로 알려져 있다. 충주호와 가까워 호수 전망도 볼 수 있다.", english: "A mountain in Danyang, North Chungcheong, named for its silk-embroidery-like autumn scenery. It is close to Chungju Lake, so lake views are part of the hike."),
        .init(id: "kr.oseosan", ko: "충남 홍성과 보령에 걸친 산이다. 서해안 가까이에서는 높은 편이라 전망이 좋고 정상 부근 억새밭으로 알려져 있다.", english: "A mountain spanning Hongseong and Boryeong in South Chungcheong. It is relatively tall for the west coast, with good views and a silver grass field near the top."),
        .init(id: "kr.daedunsan", ko: "전북 완주와 충남 논산에 걸친 바위산이다. 구름다리와 케이블카, 가을 단풍으로 알려진 도립공원이다.", english: "A rocky mountain spanning Wanju in North Jeolla and Nonsan in South Chungcheong. This provincial park is known for its suspension bridge, cable car and autumn colors."),
        .init(id: "kr.moaksan", ko: "전북 전주와 김제 사이에 있는 산이다. 금산사가 자리해 있고 정상에서 호남평야가 내려다보인다.", english: "A mountain between Jeonju and Gimje in North Jeolla. Geumsansa Temple lies on it, and the summit overlooks the Honam plain."),
        .init(id: "kr.jangansan", ko: "전북 장수에 있는 산으로 덕유산과 지리산 사이에 있다. 억새 능선과 계곡이 알려져 있고 가을 산행지로 찾는다.", english: "A mountain in Jangsu, North Jeolla, lying between Deogyusan and Jirisan. Its silver grass ridge and valleys make it a favored autumn hiking spot."),
        .init(id: "kr.unjangsan", ko: "전북 진안에 있는 산으로 금남정맥의 주요 봉우리다. 능선이 길고 정상에서 주변 산줄기가 한눈에 보인다.", english: "A mountain in Jinan, North Jeolla, and a main peak on the Geumnam ridgeline. Its long ridge gives views of the surrounding ranges from the summit."),
        .init(id: "kr.cheongwansan", ko: "전남 장흥 바닷가에 솟은 산이다. 기암괴석과 가을 억새로 알려져 있고 정상에서 다도해가 내려다보인다.", english: "A mountain rising by the coast in Jangheung, South Jeolla. It is known for odd rock formations and autumn silver grass, and its summit looks over the island-studded sea."),
        .init(id: "kr.duryunsan", ko: "전남 해남에 있는 산으로 대흥사를 품고 있다. 능선에서 남해 바다와 섬을 내려다볼 수 있고 한반도 남쪽 끝 산행지로 알려져 있다.", english: "A mountain in Haenam, South Jeolla, that shelters Daeheungsa Temple. From its ridge you can see the southern sea and islands, and it is a well-known hike near the peninsula's southern tip."),
        .init(id: "kr.palyeongsan", ko: "전남 고흥에 있는 산으로 여덟 개의 봉우리가 바다를 따라 이어진다. 능선에서 다도해와 주변 섬이 한눈에 보인다.", english: "A mountain in Goheung, South Jeolla, with eight peaks lined along the sea. The ridge gives wide views of the surrounding islands."),
        .init(id: "kr.jogyesan", ko: "전남 순천에 있는 산으로 동쪽에 송광사, 서쪽에 선암사가 있다. 두 절을 잇는 숲길이 알려져 있다.", english: "A mountain in Suncheon, South Jeolla, with Songgwangsa Temple on one side and Seonamsa Temple on the other. A forest path connects the two temples."),
        .init(id: "kr.geumjeongsan", ko: "부산 금정구와 동래구에 걸친 산이다. 한국에서 가장 큰 산성인 금정산성과 범어사가 있고 시내에서 가까운 산행지다.", english: "A mountain spanning Geumjeong-gu and Dongnae-gu in Busan. It holds Geumjeongsanseong Fortress and Beomeosa Temple, and is a hiking spot close to the city."),
        .init(id: "kr.geumosan_gumi", ko: "경북 구미와 김천 사이에 있는 산으로 도립공원이다. 정상 부근의 금오산성과 대혜폭포, 케이블카가 알려져 있다.", english: "A mountain between Gumi and Gimcheon in North Gyeongsang, designated a provincial park. Geumosanseong Fortress, Daehye Falls and a cable car are its main features."),
        .init(id: "kr.hwangaksan", ko: "경북 김천과 충북 영동에 걸친 산이다. 산 아래에 직지사가 있고 능선이 완만해 오르기 좋다.", english: "A mountain straddling Gimcheon in North Gyeongsang and Yeongdong in North Chungcheong. Jikjisa Temple sits at its foot, and the gentle ridge is easy to climb."),
        .init(id: "kr.cheonseongsan", ko: "경남 양산에 있는 산으로 원효대사의 일화가 전하는 곳이다. 정상 부근 습지와 억새밭, 능선 산행으로 알려져 있다.", english: "A mountain in Yangsan, South Gyeongsang, tied to stories of the monk Wonhyo. It is known for a wetland and silver grass fields near the top and for its ridge hikes."),
        .init(id: "kr.yeongchuksan", ko: "경남 양산과 울산에 걸친 산으로 통도사가 아래에 자리한다. 정상 부근 억새 평원과 능선 풍경이 알려져 있다.", english: "A mountain spanning Yangsan and Ulsan, with Tongdosa Temple at its foot. It is known for its silver grass plateau and ridge views."),
        .init(id: "kr.hwawangsan", ko: "경남 창녕에 있는 산으로 정상에 화왕산성이 있다. 가을 억새 평원과 정월대보름 억새태우기 행사로 알려져 있다.", english: "A mountain in Changnyeong, South Gyeongsang, with Hwawangsanseong Fortress at the summit. It is known for its autumn silver grass plain and a grass-burning event at the first full moon."),
        .init(id: "kr.jejudo", ko: "한국 남쪽 바다에 있는 가장 큰 섬으로 화산 활동으로 만들어졌다. 한라산과 오름, 용암 동굴, 해안 경관이 유네스코 세계자연유산으로 알려져 있다.", english: "The largest island of Korea, lying off its southern coast and formed by volcanic activity. Hallasan, parasitic cones, lava tubes and coastal scenery are recognized as a UNESCO World Natural Heritage site."),
        .init(id: "kr.geojedo", ko: "경남 남해안에 있는 큰 섬으로 한국에서 손꼽히는 크기다. 조선 시대 수군 기지였고 외도, 몽돌 해변, 거제 포로수용소 유적이 알려져 있다.", english: "A large island off the south coast of South Gyeongsang, among the biggest in Korea. It was a naval base in the Joseon era and is known for Oedo Island, pebble beaches and the POW camp site."),
        .init(id: "kr.ganghwado", ko: "인천 서쪽 한강 하구에 있는 섬으로 고려와 조선 시대 역사가 깊다. 고인돌 유적과 갯벌, 전등사, 마니산 참성단으로 알려져 있다.", english: "An island at the mouth of the Han River west of Incheon, rich in Goryeo and Joseon history. It is known for dolmen sites, tidal flats, Jeondeungsa Temple and the Chamseongdan altar on Manisan."),
        .init(id: "kr.jindo", ko: "전남 서남쪽 바다에 있는 큰 섬으로 다리로 육지와 이어진다. 진돗개의 고향이고 바닷길이 열리는 신비의 바닷길 축제로 알려져 있다.", english: "A large island off southwest South Jeolla, linked to the mainland by bridges. It is the home of the Jindo dog and known for the sea-parting festival when the tide opens a path."),
        .init(id: "kr.wando", ko: "전남 남쪽 바다에 있는 섬으로 여러 섬으로 이루어진 군이다. 통일신라 때 장보고가 청해진을 설치한 곳으로 알려져 있고 해변과 전복 양식으로 유명하다.", english: "An island in southern South Jeolla and the center of a county of many islands. It is known as the site of Jang Bogo's Cheonghaejin base in the Unified Silla era, and for beaches and abalone farming."),
        .init(id: "kr.anmyeondo", ko: "충남 태안에 있는 섬으로 다리로 육지와 이어진다. 안면 소나무 숲과 꽃지 해변의 할미할아비바위 일몰, 꽃 축제로 알려져 있다.", english: "An island in Taean, South Chungcheong, connected to the mainland by a bridge. It is known for its pine forests, the sunset at Kkotji Beach with the Grandmother and Grandfather Rocks, and flower festivals."),
        .init(id: "kr.namhaedo", ko: "경남 남해안에 있는 큰 섬으로 다리로 육지와 이어진다. 독일마을과 다랭이마을, 금산, 상주 은모래 해변으로 알려져 있다.", english: "A large island on the south coast of South Gyeongsang, linked to the mainland by bridges. It is known for the German Village, terraced Darangi Village, Geumsan Mountain and Sangju Beach."),
        .init(id: "kr.heuksando", ko: "전남 신안 서남쪽 끝에 있는 섬으로 홍어와 철새로 알려져 있다. 정약전이 유배 와서 지낸 곳으로 전하며 섬을 도는 해안 경치가 볼만하다.", english: "A remote island at the southwestern edge of Sinan, South Jeolla, known for skate fish and migratory birds. The scholar Jeong Yak-jeon is said to have lived here in exile, and the coastal scenery is worth seeing."),
        .init(id: "kr.bigeumdo", ko: "전남 신안에 있는 섬으로 천일염 생산이 활발하다. 하누넘 해변과 원평 해변이 있고 섬 안에 산책로와 갯벌이 있다.", english: "An island in Sinan, South Jeolla, active in sun-dried sea salt production. It has Hanuneom and Wonpyeong beaches along with trails and tidal flats."),
        .init(id: "kr.jeungdo", ko: "전남 신안에 있는 섬으로 국내 최대 규모의 태평염전이 있다. 슬로시티로 지정되었고 짱뚱어다리와 갯벌 풍경으로 알려져 있다.", english: "An island in Sinan, South Jeolla, with Taepyeong Salt Farm, one of the largest in the country. It is a Slow City and known for the mudskipper bridge and tidal flat scenery."),
        .init(id: "kr.sorokdo", ko: "전남 고흥에 있는 작은 섬으로 한센병 환자를 위한 국립병원이 있었던 곳이다. 지금은 다리로 연결되어 있고 병원 역사와 해안 산책로를 볼 수 있다.", english: "A small island in Goheung, South Jeolla, once home to a national hospital for people with Hansen disease. It is now linked by a bridge, with the hospital history and coastal paths to see."),
        .init(id: "kr.geomundo", ko: "전남 여수 남쪽 바다에 있는 섬으로 거문도 등대와 영국군 점령 역사로 알려져 있다. 동도, 서도, 고도 세 섬으로 이루어졌다.", english: "An island in the sea south of Yeosu, South Jeolla, known for its lighthouse and a 19th-century British occupation. It consists of three main islands: Dongdo, Seodo and Godo."),
        .init(id: "kr.bogildo", ko: "전남 완도에 있는 섬으로 다리로 이어진다. 윤선도가 머물며 세연정 등 정원을 가꾼 곳이고 예송리 몽돌 해변이 알려져 있다.", english: "An island in Wando, South Jeolla, reached by bridge. The scholar Yun Seon-do lived here and shaped gardens such as Seyeonjeong, and Yesong-ri pebble beach is well known."),
        .init(id: "kr.gwanmaedo", ko: "전남 진도 서쪽에 있는 작은 섬으로 관매도 해수욕장과 기암괴석이 알려져 있다. 노을과 한적한 어촌 마을 분위기를 즐길 수 있다.", english: "A small island west of Jindo, South Jeolla, known for its beach and odd rock formations. Visitors enjoy the sunsets and quiet fishing village atmosphere."),
        .init(id: "kr.purple_island", ko: "전남 신안에 있는 작은 섬으로 다리를 건너 갈 수 있다. 지붕과 길을 보라색으로 칠하고 라벤더와 아스타 국화를 가꾼 섬으로 알려져 있다.", english: "A small island in Sinan, South Jeolla, reached over a bridge. Its roofs and paths are painted purple, and it is known for lavender and aster flowers."),
        .init(id: "kr.deokjeokdo", ko: "인천 옹진군에 있는 섬으로 서해 섬 가운데 큰 편이다. 서포리 해변의 소나무 숲과 부드러운 모래, 비조봉 산행으로 알려져 있다.", english: "An island in Ongjin County, Incheon, fairly large among the west sea islands. It is known for pines and soft sand at Seopo-ri Beach and the hike up Bijobong."),
        .init(id: "kr.daecheongdo", ko: "인천 옹진군에 있는 서해 최북단 섬 가운데 하나로 북한과 가깝다. 사탄동 해변과 농여해변 풍경이 알려져 있다.", english: "One of the northernmost islands of the west sea in Ongjin County, Incheon, close to North Korea. Its sand dunes and Nongyeo Beach are known sights."),
        .init(id: "kr.yeongjongdo", ko: "인천 서쪽 바다에 있는 큰 섬으로 인천국제공항이 자리한다. 다리로 육지와 이어지며 을왕리와 왕산 해변이 있다.", english: "A large island west of Incheon that hosts Incheon International Airport. It is linked to the mainland by bridges and has Eurwangni and Wangsan beaches."),
        .init(id: "kr.seokmodo", ko: "인천 강화군에 있는 섬으로 석모대교로 강화도와 이어진다. 보문사와 민머루 해변, 낙조로 알려져 있다.", english: "An island in Ganghwa County, Incheon, linked to Ganghwado by the Seokmo Bridge. It is known for Bomunsa Temple, Minmeoru Beach and sunsets."),
        .init(id: "kr.gyodongdo", ko: "인천 강화군에 있는 섬으로 북한과 가까운 접경 지역이다. 연산군 유배지였고 대룡시장의 옛 모습이 남아 있어 알려져 있다.", english: "A border island in Ganghwa County, Incheon, close to North Korea. It was an exile site of Prince Yeonsan and is known for Daeryong Market, which keeps an old atmosphere."),
        .init(id: "kr.jangbongdo", ko: "인천 옹진군에 있는 섬으로 영종도에서 배로 가기 쉽다. 갯벌과 해안 산책로가 알려져 있고 조개 캐기 체험을 할 수 있다.", english: "An island in Ongjin County, Incheon, easily reached by boat from Yeongjongdo. It is known for tidal flats, coastal trails and clam-digging experiences."),
        .init(id: "kr.chujado", ko: "제주와 전남 사이 바다에 있는 섬으로 행정상 제주에 속한다. 낚시와 참굴비 조기로 알려져 있고 나바론 하늘길 해안 절벽이 볼만하다.", english: "An island group between Jeju and the South Jeolla coast, administered by Jeju. It is known for fishing and its sea cliffs along the Navarone Sky Road."),
        .init(id: "kr.yokjido", ko: "경남 통영 남쪽 바다에 있는 섬으로 고구마와 낚시로 알려져 있다. 일출봉에서 바다 전망을 볼 수 있고 섬 둘레 도로가 이어진다.", english: "An island south of Tongyeong, South Gyeongsang, known for sweet potatoes and fishing. Ilchulbong offers sea views, and a road circles the island."),
        .init(id: "kr.bijindo", ko: "경남 통영 한산도 남쪽에 있는 섬으로 큰 비진도와 작은 비진도가 모래톱으로 이어진다. 두 개의 해변과 맑은 바다로 알려져 있다.", english: "An island south of Hansando in Tongyeong, South Gyeongsang, where two parts are joined by a sandbar. It is known for its twin beaches and clear water."),
        .init(id: "kr.maemuldo", ko: "경남 통영 한려해상국립공원에 속한 섬으로 대매물도와 소매물도로 나뉜다. 소매물도의 등대섬은 물때에 맞춰 걸어서 건널 수 있다.", english: "An island in Hallyeohaesang National Park off Tongyeong, South Gyeongsang, divided into Daemaemuldo and Somaemuldo. The lighthouse islet near Somaemuldo can be reached on foot at low tide."),
        .init(id: "kr.saryangdo", ko: "경남 통영에 있는 섬으로 상도와 하도가 이어져 있다. 지리산 능선을 닮은 바위 능선 산행과 다도해 전망으로 알려져 있다.", english: "An island in Tongyeong, South Gyeongsang, formed by Sangdo and Hado. It is known for rocky ridge hikes with views across the island-dotted sea."),
        .init(id: "kr.deoksugung_wall", ko: "서울 중구 덕수궁 담을 따라 이어지는 돌담길이다. 가을 은행나무와 정동 일대의 옛 건물이 어우러져 산책로로 알려져 있다.", english: "A stone-walled lane running along the Deoksugung Palace wall in Jung-gu, Seoul. It is a popular walk with autumn ginkgo trees and old buildings of the Jeongdong area."),
        .init(id: "kr.misiryeong", ko: "강원 속초와 인제를 잇는 설악산의 옛 고갯길이다. 지금은 터널이 생겨 한적하며 굽은 길과 설악산 전망이 알려져 있다.", english: "An old mountain pass on Seoraksan connecting Sokcho and Inje in Gangwon. Since a tunnel opened, the winding road is quiet and offers views of Seoraksan."),
        .init(id: "kr.hangyeryeong", ko: "강원 인제와 양양을 잇는 설악산의 고개 길이다. 구불구불한 도로와 기암괴석, 가을 단풍으로 알려져 있다.", english: "A mountain pass road on Seoraksan connecting Inje and Yangyang in Gangwon. It is known for its winding road, odd rock formations and autumn colors."),
        .init(id: "kr.daegwallyeong", ko: "강원 평창과 강릉을 잇던 옛 고갯길이다. 숲길과 계곡이 이어지고 예전 영동과 영서를 넘던 길의 정취가 남아 있다.", english: "An old pass road that once linked Pyeongchang and Gangneung in Gangwon. Forest paths and a valley follow it, and it keeps the feel of the old route between east and west."),
        .init(id: "kr.heonhwaro", ko: "강원 강릉 바다를 따라 달리는 해안 도로다. 한쪽은 절벽, 한쪽은 동해가 펼쳐지고 이름은 신라 시대 향가에서 비롯되었다.", english: "A coastal road along the sea in Gangneung, Gangwon, with cliffs on one side and the East Sea on the other. Its name comes from a Silla-era hyangga poem."),
        .init(id: "kr.saecheonnyeon", ko: "강원 동해안을 따라 이어지는 해안 도로다. 바다를 곁에 두고 달리며 일출과 해안 풍경을 즐길 수 있다.", english: "A coastal road along the east coast of Gangwon. Drivers run beside the sea and can enjoy sunrises and shoreline scenery."),
        .init(id: "kr.manhangjae", ko: "강원 정선과 태백 사이에 있는 높은 고개다. 차로 오를 수 있는 도로 가운데 높은 편이며 여름 야생화와 겨울 눈꽃으로 알려져 있다.", english: "A high pass between Jeongseon and Taebaek in Gangwon, among the higher roads one can drive. It is known for summer wildflowers and winter snow blossoms."),
        .init(id: "kr.haesanryeong", ko: "강원 화천에 있는 고개 길로 화천 산골을 넘는다. 구불구불한 도로와 계곡, 가을 단풍이 알려져 있다.", english: "A mountain pass road in Hwacheon, Gangwon, crossing hilly country. It is known for winding curves, valleys and autumn foliage."),
        .init(id: "kr.jeongnyeongchi", ko: "전북 남원 지리산 서쪽에 있는 고개다. 차로 올라 지리산 능선과 운해를 볼 수 있고 노고단 방향 능선 경치가 알려져 있다.", english: "A pass on the western side of Jirisan in Namwon, North Jeolla. You can drive up to see the ridgeline and a sea of clouds, with views toward Nogodan."),
        .init(id: "kr.jianjae", ko: "경남 함양에 있는 고갯길로 굽이굽이 이어지는 모양이 눈에 띈다. 밤에 차량 불빛이 만드는 궤적 사진으로 알려져 있다.", english: "A pass road in Hamyang, South Gyeongsang, with a strikingly winding shape. It is known for night photos of car light trails."),
        .init(id: "kr.okjeongho", ko: "전북 임실 옥정호를 따라 도는 도로다. 호수와 산을 곁에 두고 달리며 아침 안개와 일출 풍경이 알려져 있다.", english: "A road circling Okjeongho Lake in Imsil, North Jeolla. Drivers pass lake and hills, and the morning mist and sunrise are well known."),
        .init(id: "kr.baeksu", ko: "전남 영광 서해안을 따라 이어지는 해안 도로다. 노을이 아름다운 일몰 명소로 알려져 있고 칠산 바다와 갯벌 풍경이 이어진다.", english: "A coastal road along the west coast of Yeonggwang, South Jeolla. It is known for sunsets, with views over the sea and tidal flats."),
        .init(id: "kr.mulmi", ko: "경남 남해 동쪽 바다를 따라 달리는 해안 도로다. 물건마을과 미조 사이를 잇고 바다와 어촌, 방조림이 이어진다.", english: "A coastal road along the eastern sea of Namhae, South Gyeongsang. It links Mulgeon village and Mijo, passing the sea, fishing villages and a coastal forest."),
        .init(id: "kr.changseon_bridge", ko: "경남 남해군 창선도와 사천 삼천포를 잇는 여러 다리 구간이다. 바다 위 다리와 섬이 이어지고 일몰과 야경이 알려져 있다.", english: "A series of bridges connecting Changseon Island in Namhae with Samcheonpo in Sacheon, South Gyeongsang. The sea-spanning route links islands and is known for sunsets and night views."),
        .init(id: "kr.sanyang", ko: "경남 통영 미륵도를 한 바퀴 도는 해안 도로다. 한려수도 바다와 섬을 곁에 두고 달리며 일몰과 달아공원 전망이 알려져 있다.", english: "A coastal road circling Mireukdo Island in Tongyeong, South Gyeongsang. It runs beside the sea and islands, and is known for sunsets and the view from Darae Park."),
        .init(id: "kr.haegeumgang", ko: "경남 거제 남쪽 해금강을 따라 이어지는 해안 도로다. 바다 위 기암괴석 풍경과 남해 전망이 알려져 있다.", english: "A coastal road along Haegeumgang on southern Geoje, South Gyeongsang. It is known for sea-stack scenery and views over the southern sea."),
        .init(id: "kr.dalmaji", ko: "부산 해운대 달맞이고개를 따라 이어지는 길이다. 봄에는 벚꽃, 밤에는 해운대 해안 야경이 알려져 있다.", english: "A road along Dalmaji Hill in Haeundae, Busan. It is known for cherry blossoms in spring and night views of the coast."),
        .init(id: "kr.seomjin", ko: "지리산 자락에서 남해로 흐르는 섬진강을 따라 달리는 길이다. 하동과 광양 사이에서 봄에는 벚꽃과 매화가 피고 강 풍경이 아름답다.", english: "A road following the Seomjin River as it flows from the Jirisan area to the southern sea. Between Hadong and Gwangyang, cherry and plum blossoms line it in spring."),
        .init(id: "kr.yisunsin_bridge", ko: "전남 여수와 광양을 잇는 현수교다. 광양만을 가로지르며 이순신 장군의 이름을 땄고 밤에는 조명이 비친다.", english: "A suspension bridge linking Yeosu and Gwangyang in South Jeolla. It spans Gwangyang Bay, is named after Admiral Yi Sun-sin and is lit at night."),
        .init(id: "kr.geoga", ko: "부산과 경남 거제를 잇는 해상 다리와 해저터널 구간이다. 바다 위 사장교와 바닷속 터널로 이어진 도로로 알려져 있다.", english: "A road linking Busan and Geoje, South Gyeongsang, with cable-stayed bridges and an undersea tunnel. It is known for combining sea bridges with a tunnel under the water."),
        .init(id: "kr.jeodo", ko: "경남 창원 마산 앞바다의 저도와 육지를 잇는 다리다. 섬 둘레로 해안 산책로와 바다 전망이 이어진다.", english: "A bridge connecting Jeodo Island to the mainland off Masan in Changwon, South Gyeongsang. Coastal paths and sea views run around the island."),
        .init(id: "kr.cheongpung", ko: "충북 제천 청풍호를 따라 이어지는 호반 도로다. 충주호의 맑은 물과 산세, 청풍문화재단지와 케이블카가 알려져 있다.", english: "A lakeside road along Cheongpungho Lake in Jecheon, North Chungcheong. It is known for clear water and mountains, the Cheongpung Cultural Heritage Complex and a cable car."),
        .init(id: "kr.malti", ko: "충북 보은 속리산 가까이에 있는 고갯길이다. 굽은 길이 여러 번 이어지고 전망대에서 속리산과 마을이 내려다보인다.", english: "A mountain pass near Songnisan in Boeun, North Chungcheong. It has many hairpin bends, and an observatory overlooks Songnisan and nearby villages."),
        .init(id: "kr.cheongpyeong", ko: "경기 가평 청평호를 따라 이어지는 호반 도로다. 북한강 물가와 산을 곁에 두고 달리며 드라이브 코스로 알려져 있다.", english: "A lakeside road along Cheongpyeong Lake in Gapyeong, Gyeonggi. It runs beside the Bukhan River and hills and is a favored drive."),
        .init(id: "kr.bijarim_road", ko: "제주 구좌읍과 송당 사이를 지나는 도로다. 비자나무 숲이 터널처럼 이어지는 구간으로 알려져 있다.", english: "A road passing between Gujwa and Songdang on Jeju. It is known for a stretch where nutmeg yew trees form a tunnel."),
        .init(id: "kr.noksan", ko: "제주 서귀포 표선과 성산 사이 녹산로를 따라 달리는 길이다. 봄에는 유채꽃과 벚꽃이 어우러지는 드라이브 코스로 알려져 있다.", english: "A road in Seogwipo, Jeju, running between Pyoseon and Seongsan. It is known as a spring drive where canola flowers and cherry blossoms bloom together."),
        .init(id: "kr.road1100", ko: "제주 한라산 중턱을 가로질러 제주시와 서귀포를 잇는 도로다. 해발 1100미터 부근에 휴게소와 습지가 있다.", english: "A road crossing the middle of Hallasan, linking Jeju City and Seogwipo. A rest area and a wetland lie near the 1,100 meter point."),
        .init(id: "kr.ulleung_road", ko: "경북 울릉도를 둘러 달리는 순환 도로다. 바다와 기암절벽을 곁에 두며 일부 구간이 터널로 이어진다.", english: "A circular road around Ulleungdo in North Gyeongsang. It runs beside the sea and rocky cliffs, with some stretches passing through tunnels."),
        .init(id: "kr.geogeum_bridge", ko: "전남 고흥 녹동항과 거금도를 잇는 대교다. 바다 위 다리로 건너 거금도 해안 경치와 일몰을 볼 수 있다.", english: "A bridge linking Nokdong Port in Goheung, South Jeolla, with Geogeumdo Island. Crossing it, you can see coastal scenery and sunsets on the island."),
        .init(id: "intl.cn.ningbo", ko: "중국 저장성에 있는 항구 도시다. 오래된 무역 항구로 천일각 장서루 같은 역사 유적과 현대적인 도시 풍경을 함께 볼 수 있다.", english: "A port city in Zhejiang, China, with a long history as a trading harbor. Historic sites such as Tianyi Pavilion library sit alongside a modern cityscape."),
        .init(id: "intl.cn.datong", ko: "중국 산시성 북부의 역사 도시다. 윈강 석굴과 공중에 매달린 듯한 현공사로 알려져 있고 옛 성곽도 남아 있다.", english: "A historic city in northern Shanxi, China. It is known for the Yungang Grottoes and the Hanging Temple perched on a cliff, and it keeps its old city walls."),
        .init(id: "intl.cn.lijiang", ko: "중국 윈난성에 있는 도시로 옛 마을이 유네스코 세계문화유산이다. 수로와 돌길이 이어지는 구시가와 위룽쉐산이 대표 볼거리다.", english: "A city in Yunnan, China, whose old town is a UNESCO World Heritage site. Its canals and stone lanes and Jade Dragon Snow Mountain are the main sights."),
        .init(id: "intl.jp.ibaraki", ko: "일본 간토 지방 북동쪽의 현으로 도쿄에서 가깝다. 미토의 가이라쿠엔 정원과 히타치 해변공원의 네모필라 꽃밭으로 알려져 있다.", english: "A prefecture in northeastern Kanto, Japan, close to Tokyo. It is known for Kairakuen Garden in Mito and the nemophila flower fields of Hitachi Seaside Park."),
        .init(id: "intl.jp.obihiro", ko: "일본 홋카이도 도카치 평야에 있는 중심 도시다. 넓은 농지와 낙농으로 알려져 있고 돼지고기 덮밥 같은 향토 음식을 맛볼 수 있다.", english: "A city in the Tokachi plain of Hokkaido, Japan. It is known for broad farmland and dairy, and for local dishes such as pork rice bowls."),
        .init(id: "intl.tw.penghu", ko: "대만 서쪽 해협에 흩어진 펑후 제도의 섬 지역이다. 현무암 해안과 바다 풍경이 특징이며 여름 해양 휴양지로 찾는다.", english: "The Penghu archipelago lies in the Taiwan Strait west of the main island. It is known for basalt coastlines and sea views, and is a popular summer beach destination."),
        .init(id: "kr.r100_nogodan", ko: "지리산 노고단으로 오르는 산악 도로다. 구불구불한 길을 따라 숲과 능선이 이어지며 높은 곳에서 산의 풍경을 볼 수 있다.", english: "A mountain road leading up toward Nogodan in Jirisan. The winding route passes through forest and ridgelines with wide mountain views from the heights."),
        .init(id: "kr.r100_mungyeong_road", ko: "경북 문경의 문경새재를 지나는 옛 과거길이다. 조선 시대 선비들이 한양으로 넘던 고갯길로 지금은 숲길로 걷는다.", english: "The old exam road through Mungyeong Saejae in North Gyeongsang. In the Joseon era scholars crossed this pass on their way to Seoul, and today it is a pleasant forest path."),
        .init(id: "kr.r100_jindo_bridge", ko: "전남 진도와 육지를 잇는 다리다. 울돌목의 빠른 물살 위를 지나며 주변 바다 경치를 볼 수 있다.", english: "A bridge linking Jindo Island in South Jeolla to the mainland. It crosses the fast currents of the Uldolmok strait with sea views all around."),
        .init(id: "kr.r100_dongdaegu", ko: "대구 동구를 지나는 큰 도로다. 대구 동쪽 도심과 동대구역 일대를 이어 주는 길이다.", english: "A major road running through eastern Daegu. It connects the eastern city area around Dongdaegu Station."),
        .init(id: "kr.r100_seomjin_azalea", ko: "섬진강 주변을 따라 철쭉이 피는 도로다. 봄이면 길가를 따라 분홍빛 꽃이 이어져 드라이브 코스로 알려져 있다.", english: "A road along the Seomjin River lined with azaleas. In spring pink blossoms follow the roadside, making it a well-known drive."),
        .init(id: "kr.r100_forty_steps", ko: "부산 중구에 있는 계단 거리다. 한국전쟁 피란 시절의 삶을 담은 이야기와 조형물이 있어 부산의 옛 모습을 느낄 수 있다.", english: "A stepped street in Jung-gu, Busan. Its displays recall life during the Korean War refugee years and give a feel of old Busan."),
        .init(id: "kr.r100_cheongju_street", ko: "충북 청주의 가로수길이다. 길 양쪽에 늘어선 나무가 터널을 이루어 계절마다 다른 풍경을 보여 준다.", english: "A tree-lined road in Cheongju, North Chungcheong. The trees on both sides form a canopy that changes with the seasons."),
        .init(id: "kr.r100_nongdari", ko: "충북 진천에 있는 옛 돌다리다. 고려 시대에 놓은 것으로 전해지며 긴 돌 교각이 지네 모양처럼 이어진다.", english: "An old stone bridge in Jincheon, North Chungcheong. Said to date from the Goryeo period, its long stone piers stretch across the stream like a centipede."),
        .init(id: "kr.r100_geumgang_expressway", ko: "충북 옥천 일대의 금강 곁을 지나는 고속도로 구간이다. 강을 따라 달리며 휴게소에서 쉬어 갈 수 있다.", english: "An expressway stretch beside the Geum River in the Okcheon area of North Chungcheong. Drivers follow the river and can rest at the service area."),
        .init(id: "kr.r100_hangang_road", ko: "서울 한강 변을 따라 이어지는 공원길이다. 강과 도심 풍경을 보며 걷거나 달리기 좋은 길이다.", english: "A park road running along the Han River in Seoul. It offers views of the river and skyline for walking and driving."),
        .init(id: "kr.r100_manangyo", ko: "경기 안양에 있는 조선 시대 돌다리다. 정조 때 아버지 사도세자의 묘를 찾는 길에 놓은 것으로 전해진다.", english: "A Joseon-era stone bridge in Anyang, Gyeonggi. It is said to have been built under King Jeongjo for the royal route to his father’s tomb."),
        .init(id: "kr.r100_jodo_bridge", ko: "전남 진도군 조도면의 섬을 잇는 다리다. 다도해의 작은 섬과 푸른 바다 위를 지나는 경치를 볼 수 있다.", english: "A bridge joining islands of Jodo in Jindo County, South Jeolla. It crosses blue water among the small islands of the southwestern sea."),
        .init(id: "kr.r100_baekyang_road", ko: "전남 장성 백양사로 들어가는 진입 도로다. 백암산 자락의 숲길로 단풍철에 특히 많이 찾는다.", english: "The approach road to Baekyangsa temple in Jangseong, South Jeolla. It runs through woods at the foot of Baegamsan and is popular in autumn."),
        .init(id: "kr.r100_gyeongpo_road", ko: "강원 강릉의 경포호와 경포 해변 주변을 지나는 도로다. 호수와 바다 사이를 달리며 소나무 숲도 만날 수 있다.", english: "A road around Gyeongpo Lake and Gyeongpo Beach in Gangneung, Gangwon. It runs between lake and sea and passes pine groves."),
        .init(id: "kr.r100_gurye_cherry", ko: "섬진강을 따라 구례 일대에 벚꽃이 피는 길이다. 봄이면 강변을 따라 꽃길이 이어진다.", english: "A cherry blossom road along the Seomjin River around Gurye. In spring blossoms line the riverbank."),
        .init(id: "kr.r100_heungmu", ko: "경북 경주 흥무로에 벚꽃이 피는 길이다. 봄이면 가로수 벚나무가 길을 덮는다.", english: "A cherry blossom road on Heungmu-ro in Gyeongju, North Gyeongsang. In spring the roadside trees arch over the street."),
        .init(id: "kr.r100_cheongyang_cherry", ko: "충남 청양에 벚나무가 늘어선 길이다. 봄 꽃철에 한적하게 드라이브하기 좋다.", english: "A road lined with cherry trees in Cheongyang, South Chungcheong. It is a quiet spring drive during blossom season."),
        .init(id: "kr.r100_chiak_road", ko: "강원 원주의 치악산으로 가는 길이다. 산자락의 숲과 계곡을 따라 이어지며 등산 입구로 이어진다.", english: "The road to Chiaksan in Wonju, Gangwon. It follows forest and valley at the mountain’s foot and leads to the hiking trailheads."),
        .init(id: "kr.r100_hantijae", ko: "경북 영양과 청송 일대의 산악 고개다. 굽이진 길과 깊은 산세가 이어져 한적한 드라이브 코스다.", english: "A mountain pass in the Yeongyang and Cheongsong area of North Gyeongsang. Its bends and deep mountains make a quiet drive."),
        .init(id: "kr.r100_mokdong", ko: "서울 양천구 목동 중심부를 가로지르는 도로다. 아파트 단지와 상가가 이어지는 도심 길이다.", english: "A road crossing the center of Mokdong in Yangcheon-gu, Seoul. It runs through a city district of apartment complexes and shops."),
        .init(id: "kr.r100_gaya_street", ko: "경남 가야 문화권 지역에 있는 거리다. 가야의 역사를 떠올리게 하는 길을 따라 나무와 풍경을 즐길 수 있다.", english: "A street in the Gaya culture area of South Gyeongsang. It evokes Gaya history and has trees and scenery along the way."),
        .init(id: "kr.r100_jinhae_coast", ko: "경남 창원 진해구의 바다를 따라 달리는 해안도로다. 항구와 섬이 보이고 군항제 벚꽃철에는 특히 붐빈다.", english: "A coastal road along the sea in Jinhae, Changwon. It offers views of harbors and islands and is busy during the cherry blossom festival."),
        .init(id: "kr.r100_jindo_scenic", ko: "전남 진도의 바다와 섬을 따라 달리는 경치 좋은 도로다. 서남해의 다도해 풍경을 볼 수 있다.", english: "A scenic drive along the sea and islands of Jindo, South Jeolla. It shows the island-dotted waters of the southwestern coast."),
        .init(id: "kr.r100_spiral_road", ko: "충남 청양에서 산을 감아 오르는 나선형 도로다. 굽이진 길과 산 풍경이 어우러진 드라이브 명소다.", english: "A spiral road winding up a mountain in Cheongyang, South Chungcheong. Its curves and mountain views make it a popular drive."),
        .init(id: "kr.r100_cheonjabong", ko: "경남에 있는 천자봉 일대의 산 도로다. 산 정상에 가까워질수록 시야가 트여 주변 풍경이 펼쳐진다.", english: "A mountain road around Cheonjabong in South Gyeongsang. The view opens up toward the summit and surrounding landscape."),
        .init(id: "kr.r100_chukryeong", ko: "전남 장성 축령산의 편백나무 숲길이다. 산책과 산림욕을 즐기는 사람이 많이 찾는다.", english: "A forest road in Chukryeongsan, Jangseong, South Jeolla, known for its cypress woods. Visitors come to walk and enjoy forest bathing."),
        .init(id: "kr.r100_sorae_road", ko: "인천 남동구 소래포구 일대를 지나는 길이다. 갯벌과 어시장, 옛 협궤 철도 자취가 남아 있는 곳이다.", english: "A road around Sorae Port in Namdong-gu, Incheon. The area has tidal flats, a fish market and traces of an old narrow-gauge railway."),
        .init(id: "kr.r100_hagui", ko: "경기 안양과 의왕을 흐르는 학의천 변의 길이다. 하천을 따라 산책로와 자전거길이 이어진다.", english: "A path along Hagui Stream, which flows through Anyang and Uiwang in Gyeonggi. Walking and cycling trails follow the water."),
        .init(id: "kr.r100_yaksu_bike", ko: "울산에서 하천이나 호숫가를 따라 이어지는 자전거 도로다. 한적하게 달리며 자연 풍경을 즐길 수 있다.", english: "A cycling road in Ulsan that follows a waterside. It offers a calm ride with natural scenery."),
        .init(id: "kr.r100_songgwang_wanju", ko: "전북 완주의 송광사로 가는 길이다. 종남산 자락에 자리한 사찰로 이어지는 조용한 숲길이다.", english: "The road to Songgwangsa temple in Wanju, North Jeolla. It is a quiet wooded approach to a temple at the foot of Jongnamsan."),
        .init(id: "kr.r100_museom", ko: "경북 영주 무섬마을의 외나무다리 일대다. 내성천이 마을을 감싸 흐르고 전통 한옥이 남아 있다.", english: "The area around the single-log bridge of Museom Village in Yeongju, North Gyeongsang. The stream encircles a village that keeps traditional hanok houses."),
        .init(id: "kr.r100_olympic_bridge", ko: "서울 한강을 가로지르는 다리다. 강남과 강동·광진 쪽을 이어 주며 야경이 눈에 띄는 곳이다.", english: "A bridge spanning the Han River in Seoul. It links the Gangnam side with the east and is noted for its night view."),
        .init(id: "kr.r100_dolsan_bridge", ko: "전남 여수 돌산도와 육지를 잇는 다리다. 바다 위를 건너며 여수 앞바다와 항구 풍경을 볼 수 있다.", english: "A bridge connecting Dolsan Island to the mainland at Yeosu, South Jeolla. It crosses the water with views of the harbor and sea."),
        .init(id: "kr.r100_moraejae", ko: "전북 완주와 진안 사이의 고개다. 산을 넘는 굽은 길이 이어져 드라이브 코스로 알려져 있다.", english: "A mountain pass between Wanju and Jinan in North Jeolla. Its winding road over the hills is known as a drive."),
        .init(id: "kr.r100_yulgokro", ko: "서울 종로 도심을 지나는 도로다. 창덕궁과 안국동 일대를 잇는 길로 궁궐 곁을 지난다.", english: "A road through central Jongno in Seoul. It links the Changdeokgung and Anguk areas and passes beside the palace."),
        .init(id: "kr.r100_rt7", ko: "강원 동해안을 따라 남북으로 이어지는 국도 7호선 구간이다. 바다를 곁에 두고 달리는 해안 드라이브 길이다.", english: "A stretch of National Route 7 running north to south along Gangwon’s east coast. It is a coastal drive with the sea beside the road."),
        .init(id: "kr.r100_jungnyeong", ko: "경북 영주와 충북 단양 사이의 죽령을 넘는 옛길이다. 삼국 시대부터 이어진 고갯길로 알려져 있다.", english: "An old road over Jungnyeong Pass between Yeongju in North Gyeongsang and Danyang in North Chungcheong. The pass is known as an ancient route."),
        .init(id: "kr.r100_yangjaecheon", ko: "서울 서초와 강남을 흐르는 양재천 변의 길이다. 하천을 따라 산책로와 자전거길이 이어진다.", english: "A path along Yangjaecheon stream through Seocho and Gangnam in Seoul. Walking and cycling trails follow the water."),
        .init(id: "kr.r100_hoengseong_bridge", ko: "강원 횡성에서 횡성호 일대를 건너는 다리다. 호수와 산이 어우러진 경치를 볼 수 있다.", english: "A bridge crossing the Hoengseong Lake area in Gangwon. It offers views of lake and mountains."),
        .init(id: "kr.r100_namhae_bridge", ko: "경남 하동과 남해도를 잇는 현수교다. 1973년 개통했고 남해 바다 위를 건너는 길이다.", english: "A suspension bridge linking Hadong and Namhae Island in South Gyeongsang. It crosses the water of Namhae and opened in 1973."),
        .init(id: "kr.r100_seokmun", ko: "충남 당진에 있는 방조제다. 바다를 막아 만든 둑길로 서해와 들판 풍경을 볼 수 있다.", english: "A seawall in Dangjin, South Chungcheong. The embankment road offers views of the Yellow Sea and farmland."),
        .init(id: "kr.r100_cheongnam_road", ko: "충북 청주 대청호 변의 청남대로 가는 진입로다. 호수와 숲을 따라 이어지는 길이다.", english: "The approach road to Cheongnamdae beside Daecheong Lake near Cheongju. It follows the lake and forest."),
        .init(id: "kr.r100_boseong_daewon", ko: "전남 보성의 대원사로 향하는 길이다. 차 재배지가 가까운 산골 숲길로 이어진다.", english: "The road toward Daewonsa temple in Boseong, South Jeolla. It runs through quiet mountain woods near tea-growing country."),
        .init(id: "kr.r100_najetongmun", ko: "전북 무주에 있는 통로 모양의 바위 문이다. 옛 신라와 백제의 경계로 전해지는 곳이다.", english: "A natural rock gateway in Muju, North Jeolla. It is said to mark the old border between Silla and Baekje."),
        .init(id: "kr.r100_sagye", ko: "제주 서귀포 사계리의 해안도로다. 바다 너머로 산방산과 형제섬 풍경이 보이는 드라이브 길이다.", english: "A coastal road at Sagye-ri in Seogwipo, Jeju. It offers a drive with Sanbangsan and Hyeongje Island across the sea."),
        .init(id: "kr.r100_ttangkkeut_road", ko: "전남 해남 땅끝마을로 가는 길이다. 한반도 육지 최남단으로 알려진 곳을 향해 바다와 들판을 지난다.", english: "The road to Ttangkkeut village in Haenam, South Jeolla. It passes sea and fields toward the southern tip of the Korean mainland."),
        .init(id: "kr.r100_yeongdeok", ko: "경북 영덕 동해안을 따라 이어지는 길이다. 대게로 알려진 영덕의 바닷가 마을과 항구를 지난다.", english: "A road along Yeongdeok’s east coast in North Gyeongsang. It passes seaside villages and ports famed for snow crab."),
        .init(id: "kr.r100_haneuljae", ko: "경북 문경과 충북 충주 사이의 고개다. 신라 시대부터 이어진 길로 알려져 있으며 숲길이 아름답다.", english: "A pass between Mungyeong in North Gyeongsang and Chungju in North Chungcheong. It is known as an ancient route with a pleasant forest trail."),
        .init(id: "kr.r100_naeso_road", ko: "전북 부안 내소사로 들어가는 진입로다. 전나무 숲길이 이어져 사찰까지 걷기 좋다.", english: "The approach road to Naesosa temple in Buan, North Jeolla. A fir-lined path leads on foot to the temple."),
        .init(id: "kr.r100_daehakro", ko: "서울 종로구 혜화동 일대의 거리다. 소극장이 모여 있어 연극과 공연으로 알려진 곳이다.", english: "A street in the Hyehwa area of Jongno-gu, Seoul. Its many small theaters make it known for plays and performances."),
        .init(id: "kr.r100_biff", ko: "부산 중구 남포동의 광장이다. 부산국제영화제 개최지로 알려졌으며 영화인의 손도장과 먹거리 골목이 있다.", english: "A square in Nampo-dong, Jung-gu, Busan. It is linked to the Busan International Film Festival and has handprints and street-food alleys."),
        .init(id: "kr.r100_samcheong", ko: "서울 종로구 삼청동의 거리다. 한옥과 갤러리, 카페가 모여 있고 북촌과 경복궁 가까이에 있다.", english: "A street in Samcheong-dong, Jongno-gu, Seoul. Hanok houses, galleries and cafes sit near Bukchon and Gyeongbokgung."),
        .init(id: "kr.r100_jungnyeong_tunnel", ko: "경북 영주와 충북 단양 사이에 있는 죽령을 뚫은 터널이다. 중앙고속도로가 소백산 아래를 통과한다.", english: "A tunnel under Jungnyeong between Yeongju and Danyang. The Jungang Expressway passes beneath Sobaeksan here."),
        .init(id: "kr.r100_danyang_bridge", ko: "충북 단양을 흐르는 남한강을 건너는 다리다. 주변의 산과 강 풍경이 어우러진다.", english: "A bridge over the South Han River at Danyang, North Chungcheong. It sits among river and mountain scenery."),
        .init(id: "kr.r100_oksun", ko: "충북 단양 충주호에 놓인 다리다. 옥순봉 일대의 물과 절벽 풍경을 볼 수 있다.", english: "A bridge on Chungju Lake at Danyang, North Chungcheong. It looks over the water and cliffs around Oksunbong."),
        .init(id: "kr.r100_tongyeong_bridge", ko: "경남 통영과 미륵도를 잇는 다리다. 통영 바다와 섬, 항구 경치를 볼 수 있다.", english: "A bridge linking Tongyeong with Mireukdo Island in South Gyeongsang. It shows the sea, islands and harbor of Tongyeong."),
        .init(id: "kr.r100_arboretum_road", ko: "경기 포천 광릉 국립수목원으로 들어가는 진입 도로다. 전나무와 활엽수가 어우러진 숲길로 알려져 있다.", english: "The approach road to the Korea National Arboretum in Gwangneung, Pocheon, Gyeonggi. It passes through wooded land with firs and broadleaf trees."),
        .init(id: "kr.r100_baerong", ko: "충남 서천의 배롱나무가 늘어선 길이다. 여름이면 붉은 꽃이 길가를 장식한다.", english: "A road lined with crape myrtle trees in Seocheon, South Chungcheong. In summer red blossoms decorate the roadside."),
        .init(id: "kr.r100_hwangak", ko: "경북 김천 황악산으로 향하는 길이다. 산자락의 숲과 계곡을 지나 직지사 방면으로 이어진다.", english: "The road toward Hwangaksan in Gimcheon, North Gyeongsang. It passes forest and valley toward Jikjisa temple."),
        .init(id: "kr.r100_asiad", ko: "부산 연제구 일대의 아시아드 경기장 주변 큰길이다. 2002년 월드컵과 아시안게임이 열린 경기장과 가깝다.", english: "A broad road near the Asiad Stadium area in Yeonje-gu, Busan. It is near venues used for the Asian Games."),
        .init(id: "kr.r100_dongjin", ko: "경남과 전남의 강이나 바다를 건너는 동진대교다. 주변의 물과 들판 풍경이 열려 있다.", english: "Dongjin Bridge crosses the water in a quiet landscape. Open views of river and fields surround it."),
        .init(id: "kr.r100_nahyeseok", ko: "경기 수원의 나혜석거리다. 수원 출신 화가이자 작가 나혜석을 기리는 곳으로 행궁동 부근에 있다.", english: "Na Hye-seok Street in Suwon, Gyeonggi. It honors the painter and writer Na Hye-seok, a Suwon native, and lies near Haenggung-dong."),
        .init(id: "kr.r100_yongdam", ko: "경기 양평의 남한강을 건너는 양평대교 주변 도로다. 강변과 산을 보며 달릴 수 있다.", english: "The road around Yangpyeong Bridge over the South Han River in Gyeonggi. Drivers see riverside and mountains."),
        .init(id: "kr.r100_seohae_bridge", ko: "경기 평택과 충남 당진 사이 서해안고속도로의 다리다. 아산만 바다를 가로지르는 긴 사장교다.", english: "A long cable-stayed bridge on the West Coast Expressway between Pyeongtaek in Gyeonggi and Dangjin in South Chungcheong. It spans Asan Bay."),
        .init(id: "kr.r100_yeongjong_bridge", ko: "인천 영종도와 육지를 잇는 다리다. 인천국제공항으로 가는 길목에 있고 바다 위로 길게 놓여 있다.", english: "A bridge linking Yeongjongdo Island with the mainland in Incheon. It lies on the way to Incheon International Airport and spans the sea."),
        .init(id: "kr.r100_taean_road", ko: "충남 태안 서해안을 따라 이어지는 해안도로다. 해변과 갯벌, 소나무 숲을 지나며 일몰 풍경으로도 알려져 있다.", english: "A coastal road along Taean’s Yellow Sea shore in South Chungcheong. It passes beaches, tidal flats and pine groves and is known for sunsets."),
        .init(id: "kr.r100_yeongam_cherry", ko: "전남 영암에 벚나무가 늘어선 길이다. 봄 꽃철에 월출산 인근 풍경과 함께 즐길 수 있다.", english: "A cherry-lined road in Yeongam, South Jeolla. In blossom season it can be enjoyed with views of nearby Wolchulsan."),
        .init(id: "kr.r100_banghwa_bridge", ko: "서울 한강을 가로지르는 다리다. 강서구 방화동 쪽과 고양 방면을 잇는다.", english: "A bridge across the Han River in Seoul. It links Banghwa-dong in Gangseo-gu with the Goyang side."),
        .init(id: "kr.r100_janghoe", ko: "충북 단양 남한강 변의 장회나루 일대다. 충주호 유람선이 오가는 나루터이며 주변에 기암절벽이 있다.", english: "The Janghoe ferry landing area on the South Han River at Danyang, North Chungcheong. Lake cruise boats call here, and steep rocky cliffs rise nearby."),
        .init(id: "kr.r100_saemgol", ko: "전북 정읍에 있는 샘골 일대의 다리와 길이다. 한적한 산골과 하천 풍경이 이어진다.", english: "A bridge and road in the Saemgol area of Jeongeup, North Jeolla. It passes quiet hills and stream scenery."),
        .init(id: "kr.airport_gmp", ko: "서울 강서구에 있는 국제공항이다. 제주 등 국내선과 일부 가까운 해외 도시 노선을 잇는다.", english: "An international airport in Gangseo-gu, Seoul. It serves domestic routes such as Jeju and a few nearby overseas cities."),
        .init(id: "kr.airport_pus", ko: "부산 강서구에 있는 국제공항이다. 부산과 국내 도시, 일본 등 해외 도시를 잇는다.", english: "An international airport in Gangseo-gu, Busan. It connects Busan with domestic cities and overseas destinations such as Japan."),
        .init(id: "kr.airport_cju", ko: "제주시에 있는 국제공항이다. 제주와 서울 등 국내 도시, 일부 해외 도시를 잇는다.", english: "An international airport in Jeju City. It links Jeju with Seoul and other domestic cities, plus some overseas destinations."),
        .init(id: "kr.airport_tae", ko: "대구 동구에 있는 국제공항이다. 대구와 제주 등 국내 도시, 일부 해외 도시를 잇는다.", english: "An international airport in Dong-gu, Daegu. It connects Daegu with Jeju and other domestic cities, plus some overseas destinations."),
        .init(id: "kr.airport_cjj", ko: "충북 청주에 있는 국제공항이다. 청주와 제주 등 국내 도시, 일부 해외 도시를 잇는다.", english: "An international airport in Cheongju, North Chungcheong. It connects Cheongju with Jeju and other domestic cities, plus some overseas destinations."),
    ]

    private static let byID = Dictionary(uniqueKeysWithValues: items.map { ($0.id, $0) })

    /// 앱 언어의 설명. 장소에 설명이 없으면 빈 글이라 화면에 아무것도 그리지 않는다.
    static func text(for id: String, language: MapHomeLanguage) -> String {
        byID[id].map { language.runtimeText($0.ko, $0.english) } ?? ""
    }
}
